  ui_story_5080_50800100_27_dialog_content = "¡De ninguna manera!",
  ui_story_5080_50800100_28_dialog_content = "¿Por qué de repente hay tantos Eclipsites...?",
  ui_story_5080_50800100_29_dialog_content = "Estamos al borde del Desierto de Rediesel, ¿recuerdas? Todavía hay muchas áreas aquí que no han sido despejadas.",
  ui_story_5080_50800100_30_dialog_content = "Aún así, son demasiados... ¿Por qué el <color=#FFB400>subordinado</color> del Comandante Hiiro nos está esperando tan lejos de aquí? No tiene sentido...",
  ui_story_5080_50800100_31_dialog_content = "Escucha atentamente, Vice. La misión que estoy a punto de asignarte viene de la propia Gran Mariscal.",
  ui_story_5080_50800100_32_dialog_content = "Para esta misión ultrasecreta, trabajarás bajo el mando de una cierta persona y la ayudarás a completar su misión.",
  ui_story_5080_50800100_33_dialog_content = "Se te permite traer a cualquier compañero que consideres necesario para la misión, incluso aquellos que no son de Illumina.",
  ui_story_5080_50800100_34_dialog_content = "Estoy seguro de que la Gran Mariscal tiene sus razones para permitir esto.",
  ui_story_5080_50800100_35_dialog_content = "No creo que haya escuchado nunca de una misión como esta, Comandante Hiiro. ¿Quién es exactamente la persona en cuestión?",
  ui_story_5080_50800100_36_dialog_content = "No deberías ser un extraño para ella. Después de todo, ella es una de tus mayores—",
