  ui_story_5080_50800100_40_dialog_content = "El capitán que estamos buscando es el que te envió ese mapa, ¿verdad? ¿Cómo puedes confiar tanto en alguien que nunca hemos conocido antes?",
  ui_story_5080_50800100_41_dialog_content = "Pareces especialmente serio acerca de esta misión, Vice.",
