  ui_story_5080_50800100_43_dialog_content = "Bueno, eso es porque... Esta persona es una leyenda de la 3ra Legión.",
  ui_story_5080_50800100_44_dialog_content = "Cuando todavía estaba en la academia, aprendimos todo sobre sus brillantes logros y se esperaba que siguiéramos su ejemplo.",
  ui_story_5080_50800100_45_dialog_content = "¡Ya era una capitana altamente condecorada antes de tener mi edad!",
  ui_story_5080_50800100_46_dialog_content = "Una leyenda de la 3ra Legión... ¿Por qué no hemos oído hablar de ella antes?",
  ui_story_5080_50800100_47_dialog_content = "No estoy seguro de por qué, pero después de que ella desapareció repentinamente un día, nadie la volvió a ver...",
  ui_story_5080_50800100_48_dialog_content = "Graah—",
  ui_story_5080_50800100_49_dialog_content = "Hay demasiados Eclipsites.",
  ui_story_5080_50800100_50_dialog_content = "Este lugar es una zona de aterrizaje terrible...",
  ui_story_5080_50800100_51_dialog_content = "¿Y si le pido a <color=#FFB400>Soroz</color> que venga a recogernos ahora? Espera, solo atraería a más Eclipsites.",
  ui_story_5080_50800100_52_dialog_content = "¡Eso incluso pondría a este capitán en peligro!",
  ui_story_5080_50800100_53_dialog_content = "Parece que no tenemos opción. Carleen, ¡contendré a los Eclipsites mientras tú buscas un terreno más alto!",
  ui_story_5080_50800100_54_dialog_content = "¿Qué? ¡No pierdas la concentración, PlayerName! ¡Vuelve detrás de mí!",
  ui_story_5080_50800100_55_dialog_content = "¡Graaah!",
  ui_story_5080_50800100_56_dialog_content = "(¿¡Están atacando desde debajo de la arena?! No es bueno, ¡no puedo esquivar a tiempo!)",
  ui_story_5080_50800100_57_dialog_content = "¡PlayerName!",
  ui_story_5080_50800100_58_dialog_content = "Deberías aprender a protegerte antes de preocuparte por los demás, <color=#FFB400>Primero Celestita</color>.",
  ui_story_5080_50800100_59_dialog_content = "Esto fue solo una pequeña prueba. ¿Realmente fue tan difícil para ti?",
  ui_story_5080_50800100_60_dialog_content = "No importa. Evaluar tu verdadera fuerza también es una de mis responsabilidades.",
  ui_story_5080_50800100_61_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5080_50800100_62_dialog_content = "Estoy bien... ¿Quién es esa persona...",
  ui_story_5080_50800100_63_dialog_content = "Una mujer con una mirada penetrante, rodeada de drones...",
  ui_story_5080_50800100_64_dialog_content = "Y vistiendo el uniforme de un capitán de élite...",
  ui_story_5080_50800100_65_dialog_content = "¡Debes ser...!",
  ui_story_5080_50800100_66_dialog_content = "¿Eres el capitán del <color=#FFB400>Escuadrón Eagleeye</color>? ¡M-Muchas gracias por salvar a PlayerName!",
  ui_story_5080_50800100_67_dialog_content = "<color=#FFB400>Eagleeye</color>... Ya no hace falta mencionar eso.",
  ui_story_5080_50800100_68_dialog_content = "El Comandante dijo que han estado trabajando juntos durante mucho tiempo. ¿Cómo puedes seguir cometiendo tantos errores de principiante?",
  ui_story_5080_50800100_69_dialog_content = "Inviertes demasiadas emociones innecesarias en tus compañeros de escuadrón, Caelestite.",
  ui_story_5080_50800100_70_dialog_content = "En mi opinión, tu lancero es más que capaz de protegerte y defenderse por sí misma.",
  ui_story_5080_50800100_71_dialog_content = "En lugar de abandonar tu posición tan imprudentemente, deberías haber dejado que Vice eliminara a los objetivos más importantes.",
  ui_story_5080_50800100_72_dialog_content = "Y tú. También eres un capitán, ¿verdad?",
  ui_story_5080_50800100_73_dialog_content = "¡S-Sí, señora!",
  ui_story_5080_50800100_74_dialog_content = "Tu especialidad también radica en el reconocimiento. No hay razón para que... te metas en problemas.",
  ui_story_5080_50800100_75_dialog_content = "(¿Está ella... mostrando preocupación por Vice?)",
  ui_story_5080_50800100_76_dialog_content = "Para un escuadrón de tres personas enfrentando oleadas de Eclipsites, tu primera prioridad debería ser romper rápidamente las filas del enemigo.",
  ui_story_5080_50800100_77_dialog_content = "Con un francotirador en el escuadrón, la ofensiva debería dejarse casi por completo al lancero mientras los demás se centran en su objetivo.",
  ui_story_5080_50800100_78_dialog_content = "Pero ya que elegiste luchar a la defensiva... Lancer, ¿por qué sigues desviando tu atención para proteger a tu francotirador? Considerando que ella es más ágil que tú, deberías centrarte en proteger a la persona detrás de ti.",
  ui_story_5080_50800100_79_dialog_content = "(T-Tan estricto.)",
  ui_story_5080_50800100_80_dialog_content = "De alguna manera, me recuerda a alguien...",
  ui_story_5080_50800100_81_dialog_content = "¿Por qué todos me están mirando?",
  ui_story_5080_50800100_82_dialog_content = "Pero aún así, me resulta difícil confiar en alguien que nos puso a prueba de una manera tan peligrosa.",
  ui_story_5080_50800100_83_dialog_content = "... No me hace ninguna diferencia. Mi entendimiento original era que solo dos personas estaban asignadas a esta misión; no esperaba que la princesa de Lumopolis también estuviera aquí.",
  ui_story_5080_50800100_84_dialog_content = "¿Investigaste sobre mi pasado?",
  ui_story_5080_50800100_85_dialog_content = "No te sorprendas tanto. Me di cuenta de todo esto solo con mirarte.",
  ui_story_5080_50800100_86_dialog_content = "En cuanto a ti, El último Caelestite... Según las regulaciones de Illumina, no se permite la participación de forasteros en nuestras misiones. Pero dado que el Comandante estaba dispuesto a hacer una excepción por ti, no tengo nada más que decir.",
  ui_story_5080_50800100_87_dialog_content = "¿De-Debería estar agradecido por eso...?",
  ui_story_5080_50800100_88_dialog_content = "Mi nombre es Rachel. Seré tu oficial al mando para esta misión.",
  ui_story_5080_50800100_89_dialog_content = "Uh, mucho gusto. Yo soy...",
  ui_story_5080_50800100_90_dialog_content = "Durante esta misión, realizaremos operaciones como una unidad cohesiva. Una vez que la misión esté completa, el escuadrón será despedido; hasta entonces, nos comunicaremos usando nombres en clave.",
  ui_story_5080_50800100_91_dialog_content = "Eres el Celestita Uno.",
  ui_story_5080_50800100_92_dialog_content = "Eres Cría Dos.",
  ui_story_5080_50800100_93_dialog_content = "...",
  ui_story_5080_50800100_94_dialog_content = "En cuanto a ti, princesa de Lumopolis, eres una completa desconocida para el ejército de la Federación Illumina. Sin embargo, dado que llegaste junto a ellos, significa que también has aceptado las condiciones de la misión.",
  ui_story_5080_50800100_95_dialog_content = "A partir de ahora, te llamaré el Lancer Blanco.",
  ui_story_5080_50800100_96_dialog_content = "¿Se supone que debo estar de acuerdo con eso? Esperaba tanto de un soldado de Illumina...",
  ui_story_5080_50800100_97_dialog_content = "Esto es altamente irrespetuoso.",
  ui_story_5080_50800100_98_dialog_content = "Esto debe ser cómo operan nuestras fuerzas especiales. No creo que ella quiera decir algo con eso, Carleen.",
  ui_story_5080_50800100_99_dialog_content = "Los tres pueden llamarme Cazador Águila Cero o Capitán.",
  ui_story_5080_50800100_100_dialog_content = "Entendido... Cazador Águila Cero.",
  ui_story_5080_50800100_101_dialog_content = "(Parecía tan cariñosa hace un minuto... ¿por qué de repente parece tan fría y distante?)",
  ui_story_5080_50800100_102_dialog_content = "Capitán Rach—¡Capitán! Puede que no me conozcas, pero fui uno de tus menores. Aunque estaba en un campo de estudio diferente, sabía todo sobre ti.",
  ui_story_5080_50800100_103_dialog_content = "Todo sobre... ¿yo...?",
  ui_story_5080_50800100_104_dialog_content = "¡Así es! Cuando todavía estaba en la escuela, escuchamos todo sobre tus logros y cómo lideraste el Escuadrón Eagleeye.",
  ui_story_5080_50800100_105_dialog_content = "El Comandante Hiiro siempre nos dice que aprendamos de tu ejemplo cada vez que regresas de una misión exitosa.",
  ui_story_5080_50800100_106_dialog_content = "Aunque ha pasado mucho desde entonces, y aunque rara vez regreso a Illumina debido a mis aventuras con PlayerName, aún te admiro.",
  ui_story_5080_50800100_107_dialog_content = "Solo podíamos adivinar qué había sucedido cuando dejamos de tener noticias tuyas. Pero ahora está claro que tú y el Escuadrón Eagleeye debieron haber estado en una misión secreta, ¿verdad?",
  ui_story_5080_50800100_108_dialog_content = "...",
  ui_story_5080_50800100_109_dialog_content = "Y con tú a cargo de nuestra misión, ¡estoy seguro de que será un gran éxito! Esta es la oportunidad perfecta para que pueda estudiar tu trabajo en acción también.",
  ui_story_5080_50800100_110_dialog_content = "Dejemos las charlas ociosas a un lado por ahora. Ven conmigo para que podamos discutir la misión.",
  ui_story_5080_50800100_111_dialog_content = "(Parece que ella no quiere mencionar el pasado en absoluto... ¿Pero por qué? Después de todo, ella es una leyenda...)",
  ui_story_5080_50800100_112_dialog_content = "Para esta misión, te llevaré profundamente al desierto, territorio de Rediesel Wrench, para investigar la presencia de un Eclipsite único.",
  ui_story_5080_50800100_113_dialog_content = "Este tipo de Eclipsite comanda el poder de la lava. Como tal, solo aparece en entornos de alta temperatura, donde tiende a dejar claras señales de sus movimientos.",
  ui_story_5080_50800100_114_dialog_content = "Los Eclipsites como estos representan una seria amenaza y deben ser manejados con precaución.",
  ui_story_5080_50800100_115_dialog_content = "Todos ustedes deben seguir mi orden sin desviación si quieren evitar cualquier baja inesperada.",
  ui_story_5080_50800100_116_dialog_content = "Además, habrá momentos en los que tenga que investigar otros asuntos. Eres libre de moverte por tu cuenta durante esos momentos.",
  ui_story_5080_50800100_117_dialog_content = "¿Qué otras cuestiones, puedo preguntar?",
  ui_story_5080_50800100_118_dialog_content = "Dime, ¿sabes algo sobre el escuadrón <color=#FFB400>Freebird</color>?",
  ui_story_5080_50800100_119_dialog_content = "No puedo decir que lo haga... Lo siento.",
  ui_story_5080_50800100_120_dialog_content = "Entonces no tienes nada de qué preocuparte. Está fuera del alcance de nuestra misión, por lo que no necesitas ayudarme... Aunque eres bienvenido a darme cualquier pista que puedas encontrar.",
  ui_story_5080_50800100_121_dialog_content = "Somos bastante buenos amigos con Sinsa. Si nuestra misión es investigar a los Eclipsites, deberíamos intentar pedirle ayuda.",
  ui_story_5080_50800100_122_dialog_content = "Entiendo... Quizás esto es por lo que el Gran Mariscal te seleccionó para esta misión. Intercambiar información podría ser útil y eficiente. Tienes mi permiso para hacer contacto con él, ahora ve.",
  ui_story_5080_50800100_123_dialog_content = "¿Eh? Pero ¿y tú, Capitán...?",
  ui_story_5080_50800100_124_dialog_content = "Como oficial de la Federación Illumina, no tengo asuntos que discutir con forajidos del desierto. Si nos encontráramos, no tendría más opción que detenerlos y llevarlos ante la justicia.",
  ui_story_5080_50800100_125_dialog_content = "Ahora vete. Todavía tengo mis propios asuntos que investigar.",
  ui_story_5080_50800100_126_dialog_content = "¿Todo por ti mismo? Pero este lugar es tan peligroso, Capitán... ¿No deberíamos dividirnos en parejas en su lugar?",
  ui_story_5080_50800100_127_dialog_content = "Dado su historial de lucha conjunta, su sinergia en combate será más efectiva sin la adición de un luchador desconocido como yo.",
  ui_story_5080_50800100_128_dialog_content = "Ahora dirígete al campamento base de Rediesel Wrench y comienza a recopilar información, eso es una orden.",
  ui_story_5080_50800100_129_dialog_content = "Me encontraré contigo más tarde.",
  ui_story_5080_50800100_130_dialog_content = "Y así de fácil, ella se ha ido.",
  ui_story_5080_50800100_131_dialog_content = "Dejando de lado la falta de modales, es indudablemente una soldado capaz.",
  ui_story_5080_50800100_132_dialog_content = "... Oye, Vice? Todavía estoy pensando en algo que Rachel acaba de decir.",
  ui_story_5080_50800100_133_dialog_content = "Ese Escuadrón Freebird que mencionó... ¿Podría estar de alguna manera conectado con el Escuadrón Eagleeye?",
  ui_story_5080_50800100_134_dialog_content = "No estoy seguro. Podrían ser similares solo en nombre, pero... ¿Eh? El Escuadrón Freebird es en realidad de Illumina...",
  ui_story_5080_50800100_135_dialog_content = "Si nuestra misión actual es investigar la presencia de un cierto Eclipsite, ¿por qué el Capitán también está investigando a uno de sus escuadrones compañeros?",
  ui_story_5080_50800100_136_dialog_content = "No veo la conexión en absoluto... Pero juzgando por su carácter, dudo que ella haría algo sin razón.",
  ui_story_5080_50800100_137_dialog_content = "Oh, también me estás haciendo curioso... De todos modos, la Jefa Philyshy debe tener la respuesta. Permíteme preguntarle.",
  ui_story_5080_50800100_138_dialog_content = "¿Miau? Una comunicación sorpresa de Vice. ¿Te encontraste con algún tipo de problema?",
  ui_story_5080_50800100_139_dialog_content = "Solo quería preguntar si tienes alguna información sobre un grupo conocido como el Escuadrón Freebird?",
  ui_story_5080_50800100_140_dialog_content = "Hmm... Bueno, la convención de nombres suena como la nuestra, pero definitivamente es de hace un tiempo. Estoy seguro de que puedo encontrar algo en nuestros archivos.",
  ui_story_5080_50800100_141_dialog_content = "Gracias, Jefe Philyshy. Tengo mucha curiosidad al respecto. ¡Asegúrate de traerte una cecina de pescado de primera calidad la próxima vez que nos encontremos!",
  ui_story_5080_50800100_142_dialog_content = "Mientras la información no esté clasificada, no me hará daño compartirla contigo, pero de cualquier manera, ¡estaré esperando ese pez!",
  ui_story_5080_50800100_143_dialog_content = "Perdón por la espera, ¡miau! Aquí dice que el Escuadrón Freebird existió hace casi cuarenta años. Eran un equipo de operaciones especiales de élite que completó más de una docena de misiones altamente peligrosas sin errores.",
  ui_story_5080_50800100_144_dialog_content = "Pero durante su última misión, fueron enviados al desierto de Rediesel en busca de algo en particular. Y esa misión... terminó en fracaso, miau.",
  ui_story_5080_50800100_145_dialog_content = "Desafortunadamente, el resto de los detalles en este archivo están tan clasificados que ni siquiera tengo la autorización para verlos.",
  ui_story_5080_50800100_146_dialog_content = "¿Qué? ¿Hay archivos a los que ni siquiera tú puedes acceder?",
  ui_story_5080_50800100_147_dialog_content = "Ni siquiera puedo ver el nombre del líder de su escuadrón... Pero cuando algo está clasificado durante tanto tiempo, generalmente implica que una persona desertó de la Federación.",
  ui_story_5080_50800100_148_dialog_content = "Esto es bastante interesante. ¿Dónde encontraste este nombre, miau?",
  ui_story_5080_50800201_1_dialog_content = "¿Me pregunto qué está tardando tanto Sinsa?",
  ui_story_5080_50800201_2_dialog_content = "Están lejos de nosotros en este momento, y todos están demasiado ocupados trabajando en algún tipo de proyecto.",
  ui_story_5080_50800201_3_dialog_content = "...",
  ui_story_5080_50800201_4_dialog_content = "¿Estás bien, Vice? ¿Por qué te ves tan serio?",
  ui_story_5080_50800201_5_dialog_content = "¿Eh? Oh, estoy bien... Solo me pregunto por qué el Capitán mencionó a un escuadrón de hace tanto tiempo.",
  ui_story_5080_50800201_6_dialog_content = "No solo eso, sino un escuadrón cuyo capitán era sospechoso de deserción.",
  ui_story_5080_50800201_7_dialog_content = "Considerando cómo hace las cosas, diría que probablemente se especializa en recopilar información.",
  ui_story_5080_50800201_8_dialog_content = "¿Quizás eso es lo que está haciendo: recopilando información sobre el desertor sospechoso?",
  ui_story_5080_50800201_9_dialog_content = "Posiblemente, pero eso fue hace casi cuarenta años. ¿Cuál sería el punto de continuar con una investigación tan antigua?",
  ui_story_5080_50800201_10_dialog_content = "¿Podría ser que Rachel esté de alguna manera conectado con esa persona?",
  ui_story_5080_50800201_11_dialog_content = "El Escuadrón Freebird... Y el Escuadrón Eagleeye...",
  ui_story_5080_50800201_12_dialog_content = "¡Oye! ¿Qué pasa con todas las caras serias?",
  ui_story_5080_50800201_13_dialog_content = "¡Sinsa!",
  ui_story_5080_50800201_14_dialog_content = "¡Mucho tiempo sin verte! ¡También te ves mucho más fuerte ahora! ¿Finalmente has decidido trabajar para nosotros?",
  ui_story_5080_50800201_15_dialog_content = "Uh, eso probablemente todavía...",
  ui_story_5080_50800201_16_dialog_content = "¡Jajaja! No te preocupes por eso. ¡Puedes encontrarnos cuando decidas! Entonces, ¿qué te trae por aquí hoy, eh?",
  ui_story_5080_50800201_17_dialog_content = "De hecho, estamos aquí en una misión especial... ¿Sabes algo sobre Eclipsites únicos o anormales aquí en el desierto?",
  ui_story_5080_50800201_18_dialog_content = "¿Eh? ¿Como...?",
  ui_story_5080_50800201_19_dialog_content = "Eh, déjame pensar... ¿Quizás uno que parece estar ardiendo? ¿O uno que se encuentra cerca de los volcanos?",
  ui_story_5080_50800201_20_dialog_content = "¿De qué estás hablando? Hay toneladas de Eclipsites acechando alrededor de los volcanos.",
  ui_story_5080_50800201_21_dialog_content = "Sí, pero estos Eclipsites se sienten particularmente atraídos por los volcanes, e incluso pueden manejar el poder de la lava.",
  ui_story_5080_50800201_22_dialog_content = "Son anormalmente fuertes y dejan señales obvias de sus movimientos dondequiera que van.",
  ui_story_5080_50800201_23_dialog_content = "¿Puedes pensar en algún eclipse que se ajuste a los requisitos?",
  ui_story_5080_50800201_24_dialog_content = "Eclipsites de lava... De ninguna manera. Ha pasado más de una década...",
  ui_story_5080_50800201_25_dialog_content = "Entonces, ¿sí sabes algo sobre ellos?",
  ui_story_5080_50800201_26_dialog_content = "Por favor, cuéntanos lo que sabes. Necesitamos tanta información sobre ellos como sea posible en este momento.",
  ui_story_5080_50800201_27_dialog_content = "En lo que a la mayoría de la gente le concierne, esto es historia antigua. También tiene mucho que ver con nuestra familia...",
  ui_story_5080_50800201_28_dialog_content = "Pero ya que es tan importante para ustedes, supongo que puedo contarles al respecto.",
  ui_story_5080_50800201_29_dialog_content = "Sé sobre los Eclipsites que estás buscando... O más bien, los antiguos miembros de <color=#FFB400>Rediesel Wrench</color> tenían una enemistad a muerte con ellos.",
  ui_story_5080_50800201_30_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5080_50800201_31_dialog_content = "Ocurrió durante la <color=#FFB400>Crisis de Darkover</color>. En aquel entonces, yo era solo un chico de recados para el líder de Rediesel Wrench.",
  ui_story_5080_50800201_32_dialog_content = "Un día, los Eclipsites arrasaron nuestro antiguo hogar como una tormenta de arena, y no tuvimos más opción que dejarlo atrás.",
  ui_story_5080_50800201_33_dialog_content = "Para darnos tiempo para escapar, nuestro líder llevó a algunos de nuestros mejores luchadores para cubrir nuestra retaguardia.",
  ui_story_5080_50800201_34_dialog_content = "Todavía recuerdo lo que vi ese día... Un verdadero monstruo, uno que calcinaba la arena bajo sus pies hasta convertirla en vidrio fundido...",
  ui_story_5080_50800201_35_dialog_content = "¿Ah?",
  ui_story_5080_50800201_36_dialog_content = "¿Qué, no me escuchaste? Dije...",
  ui_story_5080_50800201_37_dialog_content = "¡¿Eh?!",
  ui_story_5080_50800201_38_dialog_content = "¡Guau—!",
  ui_story_5080_50800201_39_dialog_content = "¡Lo siento! Ayúdame, <color=#FFB400>Guerrero Maldito</color>!",
  ui_story_5080_50800201_40_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_5080_50800201_41_dialog_content = "¡Ahhh—Detente, ahora!",
  ui_story_5080_50800201_42_dialog_content = "Aaaaaahhh—",
  ui_story_5080_50800201_43_dialog_content = "Lo siento, cariño, pero nada puede detener el poder de la música!",
  ui_story_5080_50800201_44_dialog_content = "¡Gracias a Dios por el <color=#FFB400>Guerrero Maldito</color> y su fuerza monstruosa!",
  ui_story_5080_50800201_45_dialog_content = "¿Zeta? ¿Barbara y Tiny One también?! ¿¡Qué están haciendo?!",
  ui_story_5080_50800201_46_dialog_content = "Simplemente te abres camino hasta la base con tu camión, eso es simplemente...",
  ui_story_5080_50800201_47_dialog_content = "¡No hay tiempo para explicar! ¡Ahora súbete!",
  ui_story_5080_50800201_48_dialog_content = "¡¿Eh?!",
  ui_story_5080_50800201_49_dialog_content = "No me digas que no me escuchaste, <color=#FFB400>Guerrero Maldito</color>?! ¿Esos pasos de una tierra lejana—",
  ui_story_5080_50800201_50_dialog_content = "¡Ella está aquí! ¡La Cazadora de las Arenas!",
  ui_story_5080_50800201_51_dialog_content = "¡Mira allá! Es—",
  ui_story_5080_50800201_52_dialog_content = "<size=45>Rachel¡¡¡</size>",
  ui_story_5080_50800201_53_dialog_content = "¿Y quién es ese? Muy bien Zeta, tienes cinco segundos para decirme en qué tipo de lío te has metido!",
  ui_story_5080_50800201_54_dialog_content = "Oh, esto es malo...",
  ui_story_5080_50800201_55_dialog_content = "El airbag me ha atrapado en su lugar. ¡No puedo salir!",
  ui_story_5080_50800201_56_dialog_content = "Solo espera, te sacaré de aquí.",
  ui_story_5080_50800201_57_dialog_content = "¡No! ¡Tenemos que alejarnos de ella! ¡Es la súbdita del Rey Demonio!",
  ui_story_5080_50800201_58_dialog_content = "¡Bandidos del desierto de Rediesel! ¡Entreguen lo que han robado!",
  ui_story_5080_50800201_59_dialog_content = "Hmph, tienes mucho valor, señora.",
  ui_story_5080_50800201_60_dialog_content = "Al observar más de cerca, eres de Illumina, ¿no es así?",
  ui_story_5080_50800201_61_dialog_content = "¡Espera! Sinsa, Rachel, solo escúchanos...",
  ui_story_5080_50800201_62_dialog_content = "¡Tranquilo!",
  ui_story_5080_50800201_63_dialog_content = "Un soldado de Illumina que intentó cazar a un grupo de nuestros niños, y los obligó a estrellar su coche contra nuestra base...",
  ui_story_5080_50800201_64_dialog_content = "Algunos forajidos del desierto tienen la audacia de robar a mis camaradas de armas... ¡No te mostraré piedad!",
  ui_story_5080_50800201_65_dialog_content = "¿Buscas pelea, eh? ¡Bien! Ha pasado mucho tiempo desde que les lancé golpes a ustedes!",
  ui_story_5080_50800201_66_dialog_content = "¡Ven a mí!",
  ui_story_5080_50800201_67_dialog_content = "¡Esto no está bien! Vice, Carleen, ¡tenemos que detenerlos!",
  ui_story_5080_50800201_68_dialog_content = "¡Lo haremos juntos, ahora vamos!",
  ui_story_5080_50800202_1_dialog_content = "Molestos insectos voladores, ¡aplastaré a cada uno de ustedes!",
  ui_story_5080_50800202_2_dialog_content = "¿Qué más obtienes ahora?",
  ui_story_5080_50800202_3_dialog_content = "No te muevas. A menos que quieras ser lanzado al cielo, claro...",
  ui_story_5080_50800202_4_dialog_content = "¿Así que me pusiste explosivos justo ahora, eh? No está mal.",
  ui_story_5080_50800202_5_dialog_content = "A esta distancia, ninguno de nosotros sobrevivirá a la explosión.",
  ui_story_5080_50800202_6_dialog_content = "Y aún así no pareces tener miedo en absoluto... ¡Me gusta eso! Ahora, ¡vamos a descubrir qué sucede a continuación!",
  ui_story_5080_50800202_7_dialog_content = "Estoy más que dispuesto a dar mi vida si eso significa derribar al líder de Rediesel Wrench...",
  ui_story_5080_50800202_8_dialog_content = "¡Oye, oye, oye! ¡Ya basta, ustedes dos!",
  ui_story_5080_50800202_9_dialog_content = "¡La misión, Capitán! ¡Piensa en la misión!",
  ui_story_5080_50800202_10_dialog_content = "¿Qué harán los demás si algo te sucede, Sinsa?!",
  ui_story_5080_50800202_11_dialog_content = "¡Los niños aquí todavía te necesitan!",
  ui_story_5080_50800202_12_dialog_content = "\"¿Niños\"?",
  ui_story_5080_50800202_13_dialog_content = "Boo-hoo—",
  ui_story_5080_50800202_14_dialog_content = "Vamos a bajar las armas y averiguar qué está pasando, ¿de acuerdo?",
  ui_story_5080_50800202_15_dialog_content = "Soy quien provocó al Súbdito del Rey Demonio. Asumiré toda la responsabilidad, ¡así que solo dejen ir a mis amigos!",
  ui_story_5080_50800202_16_dialog_content = "...",
  ui_story_5080_50800202_17_dialog_content = "¿Qué está pasando aquí, Zeta?",
  ui_story_5080_50800202_18_dialog_content = "Todo comenzó con la leyenda de Zeta, el guerrero más grande de todos los tiempos—",
  ui_story_5080_50800202_19_dialog_content = "Después de practicar meticulosamente el arte de las carreras, aún no pude derrotar a la Bruja de la Pista en un concurso de velocidad.",
  ui_story_5080_50800202_20_dialog_content = "Estaba seguro de que tenía algo que ver con ella teniendo al último Celestita como aliado, así que decidí buscar un poderoso camarada propio.",
  ui_story_5080_50800202_21_dialog_content = "Fue entonces cuando encontré a Barbara, la <color=#FFB400>Cantante Supernova</color> y a Regina discutiendo sobre algún tipo de competencia de canto!",
  ui_story_5080_50800202_22_dialog_content = "\"¡Oh poderoso guerrero Zeta, por favor préstame tu fuerza!\"",
  ui_story_5080_50800202_23_dialog_content = "\"Con tú a mi lado, puedo atraer a una multitud más grande de la que Regina podría esperar! ¡Mi audiencia es la fuente de mi poder!\"",
  ui_story_5080_50800202_24_dialog_content = "\"¡Suena como un buen momento! Solo no te olvides de mí: ¡el leal <color=#FFB400>Maestro de Armas</color> de Zeta!\"",
  ui_story_5080_50800202_25_dialog_content = "¡Ah! ¿Podrían ser estos los aliados que busco? ¡Deben haber sido atraídos por mi majestuosidad!",
  ui_story_5080_50800202_26_dialog_content = "¡Y así, emprendemos nuestro glorioso viaje para recorrer el furioso desierto y reunir aún más aficionados!",
  ui_story_5080_50800202_27_dialog_content = "Y con nuestra última y gran invención, el <color=#FFB400>Super Idol-móvil de Rediesel</color>, entramos en batalla—",
  ui_story_5080_50800202_28_dialog_content = "¿Qué? ¿Podrías por favor ir directamente a la parte importante?!",
  ui_story_5080_50800202_29_dialog_content = "... Suspiro.",
  ui_story_5080_50800202_30_dialog_content = "¡Mientras nuestro grupo aventuraba a través del desierto con nuestra canción ardiendo en nuestros corazones, de repente noté algo!",
  ui_story_5080_50800202_31_dialog_content = "Un halcón solitario posado en la cima de las arenas.",
  ui_story_5080_50800202_32_dialog_content = "\"¡Apuesto a que podríamos usar a este pequeño para la iluminación o el sonido!\"",
  ui_story_5080_50800202_33_dialog_content = "Esas fueron las palabras de mi Maestro de Armas, pero pude ver su verdadera fuerza por mí mismo.",
  ui_story_5080_50800202_34_dialog_content = "¡Así que decidí traer al águila como miembro de nuestro grupo!",
  ui_story_5080_50800202_35_dialog_content = "Pero poco después, un ser malvado comenzó a perseguir al águila. Ella era implacable en su persecución, e incluso nos atacó.",
  ui_story_5080_50800202_36_dialog_content = "Sus disparos fueron algunos de los más temibles que he visto. Estaba demasiado asustado para detener el coche... Quiero decir, estaba demasiado asustado por la seguridad de mis compañeros!",
  ui_story_5080_50800202_37_dialog_content = "¿Así que te estrellaste a toda velocidad contra nuestra casa?!",
  ui_story_5080_50800202_38_dialog_content = "¡Y-Yo tenía fe en que el Guerrero Maldito sería capaz de detenernos a tiempo!",
  ui_story_5080_50800202_39_dialog_content = "Cielos, Zeta...",
  ui_story_5080_50800202_40_dialog_content = "... He tenido suficiente.",
  ui_story_5080_50800202_41_dialog_content = "Devuélveme a <color=#FFB400>Cazador Águila Tres</color> ahora mismo.",
  ui_story_5080_50800301_1_dialog_content = "Así que su nombre es <color=#FFB400>Cazador de Águilas Tres</color>, ¿eh...? ¡Ese es un nombre tan genial!",
  ui_story_5080_50800301_2_dialog_content = "Bien... Dado que <color=#FFB400>Eagle Hunter Three</color> ya tiene un dueño, lo devolveré... Por favor, deja de pelear...",
  ui_story_5080_50800301_3_dialog_content = "¡Oye! ¡¿A dónde crees que vas?!",
  ui_story_5080_50800301_4_dialog_content = "¿¡No vas a simplemente alejarte después de destrozar nuestro campamento y lastimar a estos pobres niños, verdad?!",
  ui_story_5080_50800301_5_dialog_content = "Independientemente de lo que digas, ellos son los que me robaron primero el <color=#FFB400>Eagle Hunter Three</color>.",
  ui_story_5080_50800301_6_dialog_content = "Puede que sea así, pero nosotros, los bandidos Rediesel, nos cubrimos las espaldas sin importar qué.",
  ui_story_5080_50800301_7_dialog_content = "¿Entonces todavía quieres pelear?",
  ui_story_5080_50800301_8_dialog_content = "¡Ya denle un descanso, ustedes dos!",
  ui_story_5080_50800301_9_dialog_content = "¿Qué está pasando aquí afuera? ¡Todo el lugar es un desastre y todos parecen tan nerviosos!",
  ui_story_5080_50800301_10_dialog_content = "¿J-Jeriah?!",
  ui_story_5080_50800301_11_dialog_content = "¿Y qué estás haciendo aquí, eh?",
  ui_story_5080_50800301_12_dialog_content = "No es que quisiera venir... Pero, ¿no escuchaste el rugido del volcán hace un momento, Sinsa?",
  ui_story_5080_50800301_13_dialog_content = "El Volcán Rugiente ha despertado, justo como lo hizo hace <color=#FFB400>quince años</color>.",
  ui_story_5080_50800301_14_dialog_content = "¿Qué es eso?",
  ui_story_5080_50800301_15_dialog_content = "¡Hola jefe! ¿Estás bien?",
  ui_story_5080_50800301_16_dialog_content = "Finalmente despejamos la mayoría de los escombros allí. ¿Están todos bien?",
  ui_story_5080_50800301_17_dialog_content = "¡Tiny One! ¡Barbara! ¡Zeta! ¿Dónde están ustedes tres?",
  ui_story_5080_50800301_18_dialog_content = "¡No entren así de golpe, chicos!",
  ui_story_5080_50800301_19_dialog_content = "¡Estamos hablando de cosas importantes! ¡Oye! ¡Ya basta, idiotas—!!!",
  ui_story_5080_50800301_20_dialog_content = "Dicen que el Volcán Rugiente está despierto de nuevo. ¿Es verdad?",
  ui_story_5080_50800301_21_dialog_content = "¿Estás bien, Zeta? No estás herido, ¿verdad?",
  ui_story_5080_50800301_22_dialog_content = "¡No! Estoy perfectamente bien, princesa Kindheart!",
  ui_story_5080_50800301_23_dialog_content = "Incluso yo escuché el retumbar hace un momento. No hay duda: el Volcán Rugiente está activo una vez más.",
  ui_story_5080_50800301_24_dialog_content = "La última vez que entró en erupción fue durante la <color=#FFB400>Crisis de Darkover</color>, y ha estado inactivo desde entonces. ¿Qué podría haber pasado—",
  ui_story_5080_50800301_25_dialog_content = "<size=45>¡Todos ustedes cállense ya!!!</size>",
  ui_story_5080_50800301_26_dialog_content = "¡Maldita sea, a dónde fue ese imbécil de Illumina?!",
  ui_story_5080_50800301_27_dialog_content = "¿Eh? ¿Qué idiota de Illumina? No estarás hablando de mí, ¿verdad?",
  ui_story_5080_50800301_28_dialog_content = "Uf—Uf—",
  ui_story_5080_50800301_29_dialog_content = "*resoplando* Nosotros... deberíamos estar a salvo... aquí.",
  ui_story_5080_50800301_30_dialog_content = "D-No hables, solo intenta recuperar el aliento.",
  ui_story_5080_50800301_31_dialog_content = "Eso estuvo cerca. Si no estuviéramos en buenos términos con Sinsa, eso habría sido un desastre aún mayor.",
  ui_story_5080_50800301_32_dialog_content = "Afortunadamente, tu pensamiento rápido nos permitió escapar mientras él estaba distraído.",
  ui_story_5080_50800301_33_dialog_content = "... Tenía la sensación de que esas personas serían irracionales.",
  ui_story_5080_50800301_34_dialog_content = "Después de todo, no son más que bandidos y desertores.",
  ui_story_5080_50800301_35_dialog_content = "¡No no es ese!",
  ui_story_5080_50800301_36_dialog_content = "Los Rediesel Wrench no son tan malos... Si nos hubiéramos acercado amablemente a Sinsa, ¡habría sido perfectamente razonable!",
  ui_story_5080_50800301_37_dialog_content = "Han estado viviendo en el Desierto de Rediesel durante años también. Si alguien sabe más sobre el Escuadrón Freebird, son ellos...",
  ui_story_5080_50800301_38_dialog_content = "Debatiendo la credibilidad de un montón de desertores es inútil, así que dejémoslo.",
  ui_story_5080_50800301_39_dialog_content = "Mientras recopilabas información en su campamento, logré encontrar rastros de nuestro objetivo. Ven conmigo.",
  ui_story_5080_50800301_40_dialog_content = "Al menos podrías escucharme...",
  ui_story_5080_50800301_41_dialog_content = "Echa un vistazo. La arena aquí ha sido abrasada, y el área tiene rastros de ceniza volcánica.",
  ui_story_5080_50800301_42_dialog_content = "No hay error. Está justo más adelante.",
  ui_story_5080_50800301_43_dialog_content = "Pero... Hay múltiples conjuntos de huellas.",
  ui_story_5080_50800301_44_dialog_content = "Es posible que nuestro objetivo ya se haya reproducido. Mantente alerta.",
  ui_story_5080_50800301_45_dialog_content = "¡Objetivos avistados, Capitán!",
  ui_story_5080_50800301_X45_dialog_content = "Graah... Urk—",
  ui_story_5080_50800301_46_dialog_content = "¿Es esto... lava? No, son Eclipsitos!",
  ui_story_5080_50800301_47_dialog_content = "Son completamente diferentes a todo lo que hemos visto antes. Parecen montones de lava caminantes...",
  ui_story_5080_50800301_48_dialog_content = "Tienes razón, y su extraña apariencia hace que sea difícil identificar sus puntos débiles.",
  ui_story_5080_50800301_49_dialog_content = "Con ese intenso calor protegiéndolos, dudo que los ataques a distancia tengan mucho efecto.",
  ui_story_5080_50800301_50_dialog_content = "Prepárate para la batalla.",
  ui_story_5080_50800301_51_dialog_content = "Pero.",
  ui_story_5080_50800301_52_dialog_content = "Tu fuerza es más que suficiente para ellos, Lancer Blanco. Dado que eres el más adecuado para luchar de frente, estarás al frente de nuestra formación.",
  ui_story_5080_50800301_53_dialog_content = "Lo siento, pero todavía no tienes autoridad sobre mí.",
  ui_story_5080_50800301_54_dialog_content = "¿Puedes convocar el poder de un corcel volador, verdad? Deberías usarlo para lanzar ataques aéreos sorpresa durante el combate.",
  ui_story_5080_50800301_55_dialog_content = "Juzgando por la composición de sus cuerpos, parece difícil para ellos mantener su protección total. Encontrar incluso la más mínima brecha en sus defensas hará que tus ataques sean mortales.",
  ui_story_5080_50800301_56_dialog_content = "...",
  ui_story_5080_50800301_57_dialog_content = "Mientras White Lancer se enfrenta a los Eclipsites en combate, Hatchling Two, usa tu Torrente Rápido para atacarlos desde lejos.",
  ui_story_5080_50800301_58_dialog_content = "Independientemente del tipo, todos los Eclipsites expondrán sus puntos débiles cuando estén bajo un ataque pesado. Ese será tu momento para atacar.",
  ui_story_5080_50800301_59_dialog_content = "Seguro que perderán el equilibrio tan pronto como explotemos sus debilidades, lo que permitirá a Lanza Blanca asestar el golpe mortal.",
  ui_story_5080_50800301_60_dialog_content = "¡Entendido!",
  ui_story_5080_50800301_61_dialog_content = "Los Cazadores de Águilas y yo proporcionaremos fuego de supresión y dirigiremos a los Eclipsites hacia White Lancer.",
  ui_story_5080_50800301_62_dialog_content = "El fuego constante debería evitar que se agrupen, facilitando eliminarlos uno por uno.",
  ui_story_5080_50800301_63_dialog_content = "Esa es una estrategia impresionante... Entonces, haremos lo que dices.",
  ui_story_5080_50800301_64_dialog_content = "(Aunque solo los ha visto en combate una vez, Rachel conoce exactamente sus habilidades y cómo usarlas a su máximo potencial...)",
  ui_story_5080_50800301_65_dialog_content = "Uno Caelestita.",
  ui_story_5080_50800301_66_dialog_content = "¡Muy mal!",
  ui_story_5080_50800301_67_dialog_content = "Estarás a cargo de comandar esta batalla.",
  ui_story_5080_50800301_68_dialog_content = "¿Ah?",
  ui_story_5080_50800301_69_dialog_content = "Incluso las preparaciones de combate más minuciosas pueden resultar inútiles en el calor de la batalla.",
  ui_story_5080_50800301_70_dialog_content = "Tu habilidad única para percibir senderos de luz te hace un comandante mucho más capaz para esta lucha.",
  ui_story_5080_50800301_71_dialog_content = "... No solo eso, ustedes tres tienen mucha experiencia peleando como equipo.",
  ui_story_5080_50800301_72_dialog_content = "Si alguien debería liderarlos en la batalla... Eres tú.",
  ui_story_5080_50800301_73_dialog_content = "Rachel, tú...",
  ui_story_5080_50800301_74_dialog_content = "Eso es \"Capitán\" para ti.",
  ui_story_5080_50800301_75_dialog_content = "¡Ahora prepárate para la batalla, Caelestite Uno!",
  ui_story_5080_50800302_1_dialog_content = "¡Cuidado, capitán!",
  ui_story_5080_50800302_2_dialog_content = "Urgh... ¡Ahora, Lancer Blanco!",
  ui_story_5080_50800302_3_dialog_content = "¡Velos perforadores!",
  ui_story_5080_50800302_4_dialog_content = "¡Oh no, el Capitán está herido! Tenemos que...",
  ui_story_5080_50800302_5_dialog_content = "¡Concéntrate en la batalla, Hatchling Two! ¡Todavía hay otro Eclipsite yendo hacia ti!",
  ui_story_5080_50800302_6_dialog_content = "Cazador de Águila Uno, Cazador de Águila Dos, ¡prepárense para interceptar!",
  ui_story_5080_50800302_7_dialog_content = "¡Graaaaah—!",
  ui_story_5080_50800302_8_dialog_content = "... Justo a tiempo.",
  ui_story_5080_50800302_9_dialog_content = "Eso estuvo cerca... Creo que conseguimos al último de ellos.",
  ui_story_5080_50800302_10_dialog_content = "¿Qué fue eso de ahora, Cría Dos?",
  ui_story_5080_50800302_11_dialog_content = "(Yo...)",
  ui_story_5080_50800302_12_dialog_content = "No dejes que tus emociones nublen tu juicio, soldado.",
  ui_story_5080_50800302_13_dialog_content = "Incluso si me lastimo, la misión es lo primero antes que nada. Recuerda eso.",
  ui_story_5080_50800302_14_dialog_content = "Acabamos con un escuadrón entero de poderosos Eclipsites. Esta herida es el precio más pequeño que podríamos haber pagado por nuestra victoria.",
  ui_story_5080_50800302_15_dialog_content = "Dime... después de pasar tanto tiempo con tus amigos, ¿has olvidado lo que significa ser un soldado de Illumina?",
  ui_story_5080_50800302_16_dialog_content = "N-No, señora... Eso no es todo.",
  ui_story_5080_50800302_17_dialog_content = "Estás siendo demasiado duro, Rachel. Vice solo estaba preocupado por ti.",
  ui_story_5080_50800302_18_dialog_content = "... Nombres en clave, Caelestite Uno. Perder tu concentración en el campo de batalla podría tener consecuencias graves. ¿Y si ella también se hubiera lesionado justo ahora?",
  ui_story_5080_50800302_19_dialog_content = "Si sigues mis instrucciones y la misión aún resulta en fracaso, entonces la culpa recae en mí.",
  ui_story_5080_50800302_20_dialog_content = "Asumo toda la responsabilidad por la seguridad y el bienestar de mis subordinados... Siempre y cuando confíes en mí.",
  ui_story_5080_50800302_21_dialog_content = "Como un capitán veterano, todo lo que dijiste ahora es completamente cierto.",
  ui_story_5080_50800302_22_dialog_content = "Entiendo y estoy de acuerdo con tu forma de pensar.",
  ui_story_5080_50800302_23_dialog_content = "Carleen?",
  ui_story_5080_50800302_24_dialog_content = "Oh... Vice, ¿estás bien?",
  ui_story_5080_50800302_25_dialog_content = "Ajá...",
  ui_story_5080_50800302_26_dialog_content = "Estos Eclipsites... Echa un vistazo a sus cadáveres...",
  ui_story_5080_50800302_27_dialog_content = "Capitán, todavía estás sangrando...",
  ui_story_5080_50800302_28_dialog_content = "Solo déjala ser. De todos modos, no te escuchará.",
  ui_story_5080_50800302_29_dialog_content = "Ella está cargando un peso que ninguno de nosotros puede comprender.",
  ui_story_5080_50800302_30_dialog_content = "Conozco esa mirada en sus ojos demasiado bien. La he visto tantas veces en Lumopolis...",
  ui_story_5080_50800302_31_dialog_content = "He estado luchando en el frente durante mucho tiempo, y he visto más Eclipsites de los que puedo contar.",
  ui_story_5080_50800302_32_dialog_content = "Pero nunca antes había encontrado Eclipsites como este.",
  ui_story_5080_50800302_33_dialog_content = "Juzgando por sus cabezas, estos Eclipsites han estado fuera de la Zona Oscura durante mucho tiempo.",
  ui_story_5080_50800302_34_dialog_content = "Además, su anatomía indica que su evolución no estaba orientada hacia el combate.",
  ui_story_5080_50800302_35_dialog_content = "Su carne es altamente resistente al calor, y sus cuerpos pueden almacenar cantidades significativas de energía... Estos Eclipsites evolucionaron para adaptarse a su entorno.",
  ui_story_5080_50800302_36_dialog_content = "Curiosamente, sus cadáveres permanecen mucho más tiempo que los de otros Eclipsites...",
  ui_story_5080_50800302_37_dialog_content = "... Yo también noté algo. Todos se ven notablemente similares.",
  ui_story_5080_50800302_38_dialog_content = "Muy perceptivo de tu parte notarlo... Aparte de tus tendencias emocionales, eres un digno capitán de reconocimiento.",
  ui_story_5080_50800302_39_dialog_content = "Lo siento, pero ¿a qué te refieres con \"notablemente similar\"? ¿No se parecen la mayoría de los Eclipsites?",
  ui_story_5080_50800302_40_dialog_content = "Diría que los otros Eclipsites son exactamente iguales.",
  ui_story_5080_50800302_41_dialog_content = "Muchos soldados pensaron que los Eclipsites no se reproducen en el sentido normal.",
  ui_story_5080_50800302_42_dialog_content = "Estos Eclipsites, por otro lado, parecen haber descendido de un ancestro común... se parecen, pero no son exactamente iguales.",
  ui_story_5080_50800302_43_dialog_content = "Los rasgos que poseen son similares a los que se transmiten de padres a hijos.",
  ui_story_5080_50800302_44_dialog_content = "Nuestros registros indican que la última investigación sobre estos Eclipsites fue hace más de treinta años.",
  ui_story_5080_50800302_45_dialog_content = "Son más pequeños que los observados en aquel entonces, y también menos poderosos. Esto puede ser el resultado de alguna forma desconocida de reproducción...",
  ui_story_5080_50800302_46_dialog_content = "Correcto.",
  ui_story_5080_50800302_47_dialog_content = "Durante la <color=#FFB400>Crisis de Darkover</color>, muchas personas en Rediesel Wrench vieron a estos Eclipsites. Comparados con los de antes, los Eclipsites que derrotaste eran casi cómicamente débiles.",
  ui_story_5080_50800302_48_dialog_content = "Jeriah?! ¿Cómo es esto, no aparezcas así de repente!",
  ui_story_5080_50800302_49_dialog_content = "Bueno, después de todo, me asignaron a todo este desierto.",
  ui_story_5080_50800302_50_dialog_content = "Tú... ¿Cómo lograste pasar desapercibido por la detección del Cazador Águila Tres?",
  ui_story_5080_50800302_51_dialog_content = "Oh, ¿ese es el nombre de tu dron? Parece estar funcionando un poco mal.",
  ui_story_5080_50800302_52_dialog_content = "¿Qué? ¡Cazador de Águilas Tres, regresa!",
  ui_story_5080_50800302_53_dialog_content = "Aun así, nunca esperé escuchar el rugido del volcán como lo hizo hace quince años o ver a estos chicos de nuevo...",
  ui_story_5080_50800302_54_dialog_content = "¿Qué sabes sobre ellos?",
  ui_story_5080_50800302_55_dialog_content = "Jeje, estoy aquí buscando <color=#FFB400>respuestas</color>, igual que tú.",
  ui_story_5080_50800302_56_dialog_content = "El transmisor de Eagle Hunter Three ha sido dañado. También hay algo extraño adjunto a él...",
  ui_story_5080_50800302_57_dialog_content = "¿Hola? ¿Pueden oírme chicos? Holaaa—",
  ui_story_5080_50800302_58_dialog_content = "Esa voz.",
  ui_story_5080_50800302_59_dialog_content = "Zeta?",
  ui_story_5080_50800302_60_dialog_content = "Gracias a mi brillante <color=#FFB400>Maestro de Armas</color>, pudimos tomar esto, eh... ¿Cómo lo llamaste de nuevo?",
  ui_story_5080_50800302_61_dialog_content = "¡Oh cierto, lo \"hackeamos\"! Qué cosa tan genial de hacer... De todos modos, hackeamos tu dron y le adjuntamos este comunicador.",
  ui_story_5080_50800302_62_dialog_content = "Si quieres que nosotros <color=#FFB400>lo arreglemos</color>, encuéntranos en la casa de Jeriah la Hechicera.",
  ui_story_5080_50800302_63_dialog_content = "... ¡No me mires! ¿De verdad crees que se me ocurriría un nombre así?",
  ui_story_5080_50800302_64_dialog_content = "El enemigo ha manipulado al Eagle Hunter Three. Necesito repararlo de inmediato—",
  ui_story_5080_50800302_65_dialog_content = "!!!",
  ui_story_5080_50800302_66_dialog_content = "Mi kit de herramientas... ¿Cuándo se incineró?!",
  ui_story_5080_50800302_67_dialog_content = "Estabas tan concentrado en la misión anterior que cuando te lastimaste, tu kit de herramientas también se quemó.",
  ui_story_5080_50800302_68_dialog_content = "Dijeron que nos están esperando en tu casa. ¿Cuál es tu conexión con todo esto, Mensajero?",
  ui_story_5080_50800302_69_dialog_content = "Como dije, solo vine buscando respuestas. No estoy aquí por ninguna otra razón.",
  ui_story_5080_50800302_70_dialog_content = "Sin embargo, siento una presencia muy familiar en ti.",
  ui_story_5080_50800302_71_dialog_content = "¿Por qué no volvemos todos juntos? Incluso podríamos encontrar algunas respuestas más si lo hacemos.",
  ui_story_5080_50800302_72_dialog_content = "...",
  ui_story_5080_50800302_73_dialog_content = "Jeriah es un miembro senior de la Unión de Mensajeros. Podemos confiar en ella.",
  ui_story_5080_50800302_74_dialog_content = "Entonces vamos.",
  ui_story_5080_50800401_1_dialog_content = "Lamento haberte causado molestias así, Jeriah.",
  ui_story_5080_50800401_2_dialog_content = "No te preocupes por eso, ahora toma asiento. De todos modos, no es la primera vez.",
  ui_story_5080_50800401_3_dialog_content = "Mmm...",
  ui_story_5080_50800401_4_dialog_content = "¡Ah! ¡Agáchate! ¡El campamento de Rediesel Wrench está justo adelante!",
  ui_story_5080_50800401_5_dialog_content = "No te preocupes, ellos tienen las manos llenas en este momento.",
  ui_story_5080_50800401_6_dialog_content = "¡Argh, esto está completamente destrozado!!! Zeta, pequeño monstruo... ¡Solo espera a que te ponga las manos encima!!!",
  ui_story_5080_50800401_7_dialog_content = "Oye, ¿no es ese el coche de Jeriah? ¡Oye, Jeriah! La comida está lista, si quieres comer algo con nosotros.",
  ui_story_5080_50800401_8_dialog_content = "¡La próxima vez!",
  ui_story_5080_50800401_9_dialog_content = "¡Haz lo que quieras! Solo iré a preguntarle a Azure entonces.",
  ui_story_5080_50800401_10_dialog_content = "Reduzca la velocidad un poco, Jeriah. Hay muchas trampas más adelante.",
  ui_story_5080_50800401_11_dialog_content = "Gracias por el recordatorio.",
  ui_story_5080_50800401_12_dialog_content = "¡Yo Jeriah, echa un vistazo a este libro! ¿Realmente dice \"Cómo convertirse en el Jefe de Rediesel Wrench\" en la portada? ¡Esos idiotas mejor que no se estén burlando de mí solo porque no puedo leer muy bien!",
  ui_story_5080_50800401_13_dialog_content = "Por supuesto que no dice eso. Si quieres que paren, entonces aprende a leer.",
  ui_story_5080_50800401_14_dialog_content = "Gracias de nuevo por traernos esas herramientas en tu última carrera, Jeriah. Te haré un hueco en algún momento de esta semana para trabajar en tu coche.",
  ui_story_5080_50800401_15_dialog_content = "Suena como un trato.",
  ui_story_5080_50800401_16_dialog_content = "Jeriah... Creo que has cambiado desde la última vez que te vi.",
  ui_story_5080_50800401_17_dialog_content = "Solías vivir en un lugar tan difícil de encontrar, pero ahora te llevas bien con todos en Rediesel Wrench.",
  ui_story_5080_50800401_18_dialog_content = "Jejeje, qué bueno que te diste cuenta, PlayerName.",
  ui_story_5080_50800401_19_dialog_content = "Todos cambian con el tiempo.",
  ui_story_5080_50800401_20_dialog_content = "Gracias a ti, también he empezado a pensar en establecer conexiones con los demás.",
  ui_story_5080_50800401_21_dialog_content = "... O-Oye, Vice? Está un poco apretado aquí atrás—",
  ui_story_5080_50800401_22_dialog_content = "Si quieres que tu música llegue a cada rincón del mundo, entonces deberías reproducirla fuerte, fuerte, ¡FUERTE!",
  ui_story_5080_50800401_23_dialog_content = "¡Adelante, haz lo mejor que puedas! ¡La persona más ruidosa de la habitación siempre es la más tonta!",
  ui_story_5080_50800401_24_dialog_content = "¡El fracaso, la frustración y el miedo te hicieron huir de mí!",
  ui_story_5080_50800401_25_dialog_content = "¡Y nada me enfurece más que un cobarde!",
  ui_story_5080_50800401_26_dialog_content = "¡Zeta aún no es bueno conduciendo! ¡Pero un verdadero amigo nunca se molestaría!",
  ui_story_5080_50800401_27_dialog_content = "¿Sucede algo, Vice? Pareces enfermo...",
  ui_story_5080_50800401_28_dialog_content = "N-No es nada... Capitán, realmente no deberías intentar cambiar tus vendajes en un viaje en coche tan accidentado.",
  ui_story_5080_50800401_29_dialog_content = "Puedo atender tus heridas una vez que lleguemos, así que por favor no te esfuerces.",
  ui_story_5080_50800401_30_dialog_content = "Está bien, estoy acostumbrado a trabajar solo.",
  ui_story_5080_50800401_31_dialog_content = "Esto no es nada... Además, no hay necesidad de ser tan educado. No soy mucho mayor que tú.",
  ui_story_5080_50800401_32_dialog_content = "Solo eres un año menor que yo, sin embargo, ya has logrado convertirte en un capitán sobresaliente. No hay necesidad de ser tan respetuoso.",
  ui_story_5080_50800401_33_dialog_content = "¿Eres un explorador de Illumina, verdad? Por tu ropa, asumo que también eres un soldado de élite.",
  ui_story_5080_50800401_34_dialog_content = "Puedo decir que eres diferente a los demás pajaritos. Eres un verdadero pájaro de presa, ¿verdad?",
  ui_story_5080_50800401_35_dialog_content = "¿Qué tipo de misión requeriría los servicios de alguien como tú?",
  ui_story_5080_50800401_36_dialog_content = "Eso es altamente clasificado, y además no es asunto tuyo.",
  ui_story_5080_50800401_37_dialog_content = "Odio decirlo, pero el destino puede ser tan impredecible a veces.",
  ui_story_5080_50800401_38_dialog_content = "Bueno, estoy seguro de que hay una buena razón para que un cazador como tú aparezca en un lugar como este.",
  ui_story_5080_50800401_39_dialog_content = "Mira, joven Sinsa, esas <color=#FFB400>huellas</color> de nuevo.",
  ui_story_5080_50800401_40_dialog_content = "Son justo como los que Kafka encontró. Estos deben ser las <color=#FFB400>huellas</color> de las que Jeriah hablaba antes.",
  ui_story_5080_50800401_41_dialog_content = "Te dije que no me llamaras así... De todos modos, estas huellas son solo montones de lava, ¿no es así?",
  ui_story_5080_50800401_42_dialog_content = "¿Por qué habría lava en un lugar como este?",
  ui_story_5080_50800401_43_dialog_content = "¿Tal vez descubriremos más si seguimos adelante?",
  ui_story_5080_50800401_44_dialog_content = "¡Oye, Roy! Estos son restos de Eclipsitos, ¿no es así? Han sido destrozados, pero no se puede negar, ¿verdad?",
  ui_story_5080_50800401_45_dialog_content = "Alguien los sacó... Pero lo que es aún más extraño es que sus cuerpos aún no han desaparecido.",
  ui_story_5080_50800401_46_dialog_content = "Échales un buen vistazo, Roy. ¿Son los mismos que <color=#FFB400>el Eclipsite</color> que viste en aquel entonces?",
  ui_story_5080_50800401_47_dialog_content = "Hace quince años, cuando intentábamos escapar... Cuando <color=#FFB400>el jefe</color> intentó comprarnos más tiempo antes de <color=#FFB400>ese Eclipsite</color>...",
  ui_story_5080_50800401_48_dialog_content = "Eres el único que puede confirmarlo.",
  ui_story_5080_50800401_49_dialog_content = "Se parecen a <color=#FFB400>ese Eclipsite</color> pero no son lo mismo. Si acaso, parecen sus <color=#FFB400>descendientes</color>.",
  ui_story_5080_50800401_50_dialog_content = "Maldito monstruo... Así que ha estado reproduciendo todos estos años, ¿eh?",
  ui_story_5080_50800401_51_dialog_content = "¡Hora de ir a cazar! Seguiremos a <color=#FFB400>esa cosa</color> hasta su nido y la destruiremos de una vez por todas!",
  ui_story_5080_50800401_52_dialog_content = "Estamos en las cercanías del volcán y la temperatura definitivamente es mucho más caliente. Parece que el joven Jeriah tenía razón, el volcán realmente está despierto de nuevo.",
  ui_story_5080_50800401_53_dialog_content = "¿Por qué las pistas simplemente desaparecen aquí?",
  ui_story_5080_50800401_54_dialog_content = "Estas huellas pertenecen a diferentes Eclipsites... Tal vez ellos desordenaron las cosas.",
  ui_story_5080_50800401_55_dialog_content = "El Rugiente Volcán en realidad está ubicado profundamente bajo tierra. Podría haber incluso más caminos ocultos justo debajo de nuestros pies.",
  ui_story_5080_50800401_56_dialog_content = "Y sin un objetivo claro a la vista, correr a ciegas sería demasiado peligroso.",
  ui_story_5080_50800401_57_dialog_content = "¡Deja de esconderte ya, gran cobarde! ¡Sal y enfréntame!",
  ui_story_5080_50800401_58_dialog_content = "¡Ya no soy el mismo mocoso de hace quince años, ahora muéstrate! ¡Es hora de poner fin a esto!!!",
  ui_story_5080_50800401_59_dialog_content = "¡¡¡Maldita sea!!!",
  ui_story_5080_50800401_60_dialog_content = "¡Detente, Sinsa! Este lugar podría derrumbarse en cualquier momento—¡Ahhh—!",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>Las paredes tiemblan mientras los golpes de Sinsa resuenan más profundo en la cueva. Pronto, se puede escuchar el ajetreo de innumerables Eclipsites.</color>",
  ui_story_5080_50800401_62_dialog_content = "La cueva está a punto de colapsar, ¡pero parece que nuestro viejo amigo finalmente sale a saludarnos!",
  ui_story_5080_50800401_63_dialog_content = "¡Mira allá, Roy! Son ellos, ¿no es así?",
  ui_story_5080_50800401_64_dialog_content = "¡Les tomó bastante tiempo aparecer! ¡Su nido debe estar cerca!",
  ui_story_5080_50800401_65_dialog_content = "Ten cuidado, joven Sinsa... Hagamos esto rápido.",
  ui_story_5080_50800401_66_dialog_content = "Hmph, no voy a parar hasta que mi llave esté satisfecha. ¡Vamos, Roy!",
  ui_story_5080_50800402_1_dialog_content = "Entra y siéntete como en casa. No tengo mucho, ya que casi nunca tengo visitas—",
  ui_story_5080_50800402_2_dialog_content = "¡Observa! Una obra maestra del único e inigualable Zeta!",
  ui_story_5080_50800402_3_dialog_content = "¡Guau! ¡Es tan realista!",
  ui_story_5080_50800402_4_dialog_content = "¡Ja! ¡Esto no es nada para un guerrero legendario como yo!",
  ui_story_5080_50800402_5_dialog_content = "¿Veo que estás irrumpiendo y colgando un montón de dibujos de nuevo?",
  ui_story_5080_50800402_6_dialog_content = "¡Tu hogar es demasiado anticuado, Encantadora! Toma este maravilloso dibujo para animar tu espacio vital con una sonrisa más grande, ¡es una cortesía del legendario Zeta!",
  ui_story_5080_50800402_7_dialog_content = "...No importa. Solo trata de no romper nada.",
  ui_story_5080_50800402_8_dialog_content = "Y deja de llamarme Encantadora ya. Si alguien merece ese título, es la señorita Naroxel.",
  ui_story_5080_50800402_9_dialog_content = "Nunca la he conocido, pero su nombre suena súper genial! Ah, por cierto, ¡aquí está tu correo!",
  ui_story_5080_50800402_10_dialog_content = "Ordenamos ese desordenado montón de sobres y tiramos la basura por ti.",
  ui_story_5080_50800402_11_dialog_content = "¿En serio? Qué amable de tu parte.",
  ui_story_5080_50800402_12_dialog_content = "Jeje, es justo que te recompense adecuadamente por todas las recompensas de las misiones que me has dado!",
  ui_story_5080_50800402_13_dialog_content = "Claro, ahora podrías por favor dejar de manchar el correo con pintura? En cuanto al resto de ustedes, no se queden ahí parados. Tomen asiento.",
  ui_story_5080_50800402_14_dialog_content = "Realmente has cambiado mucho, Jeriah... Pareces mucho más feliz ahora que has establecido conexiones con tantas otras personas.",
  ui_story_5080_50800402_15_dialog_content = "¡Y no podría estar más feliz por ti!",
  ui_story_5080_50800402_16_dialog_content = "¿En serio? Estos niños pueden ser un puñado a veces, pero al menos mis días ya no son tan aburridos.",
  ui_story_5080_50800402_17_dialog_content = "Eagle Hunter Three es un dron biónico con capacidades de combate y reconocimiento, y es el producto de la tecnología más avanzada de Illumina... ¿Están seguros de que pueden arreglarlo?",
  ui_story_5080_50800402_18_dialog_content = "¡Solo déjaselo a mi Maestro de Armas!",
  ui_story_5080_50800402_19_dialog_content = "Comencemos con una pequeña prueba de toque. Izquierda, derecha, izquierda... Sí, parece que el transmisor fue destrozado por un impacto excesivo.",
  ui_story_5080_50800402_20_dialog_content = "¿Ves? ¡Nada está fuera del alcance de las habilidades de nuestro orgulloso Maestro de Armas!",
  ui_story_5080_50800402_21_dialog_content = "¿Bueno entonces? ¿Puedes hacerlo?",
  ui_story_5080_50800402_22_dialog_content = "¡Definitivamente haré lo mejor que pueda!",
  ui_story_5080_50800402_23_dialog_content = "Préstame tus herramientas. También debería poder ayudar.",
  ui_story_5080_50800402_24_dialog_content = "Estos drones son mis compañeros en combate... No estoy dispuesto a entregarlos tan fácilmente.",
  ui_story_5080_50800402_25_dialog_content = "¡No te preocupes tanto, Eagle Huntershot el Héroe de la Neutralidad!",
  ui_story_5080_50800402_26_dialog_content = "...",
  ui_story_5080_50800402_27_dialog_content = "No te preocupes por Zeta, así es ella.",
  ui_story_5080_50800402_28_dialog_content = "Ahora que sé que estas águilas son tus compañeros preciados, no les pondría un dedo encima.",
  ui_story_5080_50800402_29_dialog_content = "Es mi culpa que este se haya lastimado, ¡así que por favor déjame cuidarlo por ti!",
  ui_story_5080_50800402_30_dialog_content = "Pero estás haciendo que Tiny One haga todo el trabajo...",
  ui_story_5080_50800402_31_dialog_content = "¡N-Nos encontramos de nuevo, el último Celestita! Veo que el destino te ha favorecido con otro poderoso aliado!",
  ui_story_5080_50800402_32_dialog_content = "Podrías hablarme normalmente, ¿sabes?",
  ui_story_5080_50800402_33_dialog_content = "¡Pero yo, el legendario guerrero Zeta, aún no he perdido la esperanza!",
  ui_story_5080_50800402_34_dialog_content = "Como un Héroe de la Neutralidad, si puedes aliarte con el último Caelestite, ¡eso significa que también puedes unirte a mi búsqueda!",
  ui_story_5080_50800402_35_dialog_content = "Si eso significa tener a un guerrero poderoso como tú en mi equipo, ¡incluso pasaré por alto tu malvado pasado!",
  ui_story_5080_50800402_36_dialog_content = "(Yo...)",
  ui_story_5080_50800402_37_dialog_content = "¡No hace falta decir otra palabra! ¡Ya sé exactamente lo que tienes en mente!",
  ui_story_5080_50800402_38_dialog_content = "Estoy seguro de que un guerrero orgulloso como tú no se convence fácilmente.",
  ui_story_5080_50800402_39_dialog_content = "¡Pero eso está bien! Tú y yo podemos luchar en igualdad de condiciones una vez que mi Maestro de Armas repare tu dron.",
  ui_story_5080_50800402_40_dialog_content = "Y después de que te gane de manera justa... Te convertirás en una adición invaluable para mi equipo, ¡y esa bruja nunca tendrá oportunidad contra mí!",
  ui_story_5080_50800402_41_dialog_content = "Tu juramento suena más como una declaración de guerra para mí.",
  ui_story_5080_50800402_42_dialog_content = "No te preocupes demasiado por ella, Capitán. Zeta simplemente tiene una... forma diferente de hablar.",
  ui_story_5080_50800402_43_dialog_content = "Es-Eso es correcto, Capitán. Una vez que el Cazador Águila Tres esté reparado, nos iremos.",
  ui_story_5080_50800402_44_dialog_content = "Está bien.",
  ui_story_5080_50800402_45_dialog_content = "¿Oíste eso, Zeta? Ahora, ¿por qué no te disculpas... Eh?",
  ui_story_5080_50800402_46_dialog_content = "A pesar de tu afiliación con esos bandidos de Rediesel...",
  ui_story_5080_50800402_47_dialog_content = "No pareces consciente del pasado, así que estoy dispuesto a pasarlo por alto esta vez.",
  ui_story_5080_50800402_48_dialog_content = "Aún eres joven, así que no dejes que te corrompan con sus maneras de forajidos del desierto.",
  ui_story_5080_50800402_49_dialog_content = "Jeje, parece que tienes una idea equivocada. ¡Mi sueño es convertirme en un héroe legendario y también en el salvador del desierto!",
  ui_story_5080_50800402_50_dialog_content = "Me alegra escuchar que tienes un objetivo tan noble. No te lastimé antes, ¿verdad?",
  ui_story_5080_50800402_51_dialog_content = "¿Eh? ¡N-No, para nada! ¡Un ataque como ese ni siquiera podría dejarme un rasguño! ¡Y definitivamente no estaba gritando de miedo o algo así!",
  ui_story_5080_50800402_52_dialog_content = "Bien. Realmente eres un guerrero valiente.",
  ui_story_5080_50800402_53_dialog_content = "¿Estoy viendo cosas...?",
  ui_story_5080_50800402_54_dialog_content = "Ella acaba de manejar Zeta perfectamente.",
  ui_story_5080_50800402_55_dialog_content = "... No sabía que ella pudiera ser así.",
  ui_story_5080_50800402_56_dialog_content = "Quizás ella es exactamente como la describiste antes, Carleen. Tiene sentido que una capitana experimentada y madura cuide de sus subordinados.",
  ui_story_5080_50800402_57_dialog_content = "Pero.",
  ui_story_5080_50800402_58_dialog_content = "(¿Es esta la verdadera ella? Si es así, ¿por qué es tan fría con nosotros?)",
  ui_story_5080_50800402_59_dialog_content = "(¿Está reprimiendo sus emociones por el bien de la misión? ¿O... podría estar ocultando un tipo de dolor más profundo?)",
  ui_story_5080_50800402_60_dialog_content = "Interesante. He visto aves de todas formas y tamaños pasar por el desierto en sus rutas migratorias, pero esta es la primera vez que veo un halcón que puede guardar sus garras.",
  ui_story_5080_50800402_61_dialog_content = "Uh, ¿Zeta? Las grietas de este dron están llenas de arena, lo que explica por qué algunos de los circuitos se quemaron.",
  ui_story_5080_50800402_62_dialog_content = "No estoy acostumbrado a trabajar en cosas tan afinadas como esta. Arreglarlo no será fácil.",
  ui_story_5080_50800402_63_dialog_content = "¿Q-Qué?",
  ui_story_5080_50800402_64_dialog_content = "Si no puedes hacerlo, entonces pásame las herramientas para que yo pueda encargarme de ello.",
  ui_story_5080_50800402_65_dialog_content = "¡N-Ahora solo espera un segundo!",
  ui_story_5080_50800402_66_dialog_content = "¡Di mi palabra como un orgulloso guerrero de que asumiría toda la responsabilidad de esto! ¿Cómo más se supone que debemos tener nuestra épica batalla?!",
  ui_story_5080_50800402_67_dialog_content = "No puedes quemarte antes de dar el primer paso. No te vas a rendir, ¿verdad?",
  ui_story_5080_50800402_68_dialog_content = "¿Sabes quién es genial en este tipo de trabajo? ¡Odi la Maniaca de las Máquinas! No quieres perder contra ella, ¿verdad?!",
  ui_story_5080_50800402_69_dialog_content = "¿Qu... Qué dijiste?!",
  ui_story_5080_50800402_70_dialog_content = "¡Retrocedan y observen, todos ustedes! ¡Este trabajo no es nada para alguien como yo!",
  ui_story_5080_50800402_71_dialog_content = "¡Arreglaré esto en un santiamén! ¡Las habilidades de Odi ni siquiera se comparan con las mías!",
  ui_story_5080_50800402_72_dialog_content = "Creo que sé cómo Zeta sigue involucrando a Tiny One en sus planes ahora.",
  ui_story_5080_50800402_73_dialog_content = "Se está haciendo tarde y no parece que las reparaciones se vayan a terminar pronto. Todos deberían quedarse aquí esta noche.",
  ui_story_5080_50800402_74_dialog_content = "No estaríamos entrometiéndonos, ¿verdad?",
  ui_story_5080_50800402_75_dialog_content = "No te preocupes, ya estoy acostumbrado a \"intrusiones\" como esta.",
  ui_story_5080_50800402_76_dialog_content = "Además... creo que tengo mucho que discutir con cierta ave de presa.",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>A medida que la noche desciende sobre el desierto, la temperatura comienza a caer en picado. De repente, una duna de arena se agita en la aparentemente vacía extensión.</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>Con un sonido de farfulla, una figura estalla desde debajo de las arenas!</color>",
  ui_story_5080_50800500_3_dialog_content = "Ach—¡No!",
  ui_story_5080_50800500_4_dialog_content = "¡No, no, no!",
  ui_story_5080_50800500_5_dialog_content = "*tos* R-Roy...! ¿Estás... Estás bien?",
  ui_story_5080_50800500_6_dialog_content = "Uf... Soy demasiado viejo para este tipo de cosas, joven Sinsa. La próxima vez que decidas hacer caer una montaña sobre nuestras cabezas, ¡al menos avísame!",
  ui_story_5080_50800500_7_dialog_content = "Jeje—Hace tiempo que no nos soltamos así, ¿eh?",
  ui_story_5080_50800500_8_dialog_content = "Sí, pero dejando de lado las diversiones y juegos, todavía no sabemos la ubicación exacta de su nido... Y su número tampoco es para tomarlo a la ligera.",
  ui_story_5080_50800500_9_dialog_content = "Está bien, ahora volvamos al campamento. Si alguien pregunta, solo diles que eliminamos el nido de los Eclipsites y lo dejamos así.",
  ui_story_5080_50800500_10_dialog_content = "¿Pero realmente está bien? Matamos a muchos Eclipsites, pero claramente no fueron todos.",
  ui_story_5080_50800500_11_dialog_content = "Con todos los pasajes subterráneos que atraviesan este lugar, es posible que esos monstruos fundidos estén anidando dentro del volcán.",
  ui_story_5080_50800500_12_dialog_content = "¡Entonces, vamos a lanzarnos a ese volcán!",
  ui_story_5080_50800500_13_dialog_content = "¿Es realmente la mejor idea que tenemos?",
  ui_story_5080_50800500_14_dialog_content = "Me preocupa que el mismo tipo de Eclipsite que mató a nuestro líder todavía esté acechando en algún lugar del volcán, uno que es más fuerte que cualquier cosa a la que nos hayamos enfrentado.",
  ui_story_5080_50800500_15_dialog_content = "Necesitamos decirle a todos inmediatamente y asegurarnos de que estén listos para pelear cuando llegue el momento.",
  ui_story_5080_50800500_16_dialog_content = "Si las cosas se ponen peligrosas, por supuesto, les avisaré. Pero si nos enfrentamos a <color=#FFB400>esa cosa</color>, no puedo permitir que esos pequeños traviesos corran peligro.",
  ui_story_5080_50800500_17_dialog_content = "¿Qué es tan diferente ahora? También eras solo un mocoso entonces, pero ahora eres nuestro líder.",
  ui_story_5080_50800500_18_dialog_content = "Entiendo ese sentimiento, ¡pero de ninguna manera se lo diré a todos! ¿Nuestro problema con <color=#FFB400>ese monstruo</color>? Nah, no tiene nada que ver con los pequeños en casa!",
  ui_story_5080_50800500_19_dialog_content = "Esta llave me fue entregada, junto con ese rencor. Como líder, me corresponde vengar a nuestro antiguo jefe y a nuestros hermanos caídos. Por eso...",
  ui_story_5080_50800500_20_dialog_content = "Prométeme que no dirás nada, Roy.",
  ui_story_5080_50800500_21_dialog_content = "Entonces, ¿lo haces por los niños, eh? El jefe también dijo algo así en el pasado.",
  ui_story_5080_50800500_22_dialog_content = "Aunque tuvimos la suerte de escapar, mi corazón ha estado lleno de arrepentimiento desde entonces.",
  ui_story_5080_50800500_23_dialog_content = "Si dejamos que los niños luchen contra <color=#FFB400>esa cosa</color>, y terminan sintiendo la misma impotencia y desesperación que sentimos en aquel entonces, terminarán igual que...",
  ui_story_5080_50800500_24_dialog_content = "No lo harán, joven Sinsa. Después de todo por lo que hemos pasado, ¿no me digas que no has visto cuánto han crecido?",
  ui_story_5080_50800500_25_dialog_content = "Sí, algunos de ellos son inexpertos o no recuerdan lo que pasó en aquel entonces, pero esos niños ya son miembros orgullosos y plenamente capacitados de Rediesel Wrench.",
  ui_story_5080_50800500_26_dialog_content = "Zeta tenía solo dos años cuando perdió a sus padres. No era más alta que una llanta en aquel entonces, pero ahora es lo suficientemente fuerte para recorrer el desierto sola.",
  ui_story_5080_50800500_27_dialog_content = "¿Realmente vas a privarla de la oportunidad de enfrentar su pasado?",
  ui_story_5080_50800500_28_dialog_content = "Eso no es lo que quise decir. Me conoces mejor que eso.",
  ui_story_5080_50800500_29_dialog_content = "Lo hago, y también sé que eres demasiado dominante para soltar sus manos.",
  ui_story_5080_50800500_30_dialog_content = "¿Recuerdas lo que solía decir nuestra antigua jefa? Ella creía que deberíamos respetar cada decisión que un niño toma, ya que toda persona tiene derecho a la libertad.",
  ui_story_5080_50800500_31_dialog_content = "Ahora que los niños están todos crecidos, los viejos como nosotros necesitamos aprender a dejar ir.",
  ui_story_5080_50800500_32_dialog_content = "Cuando llegue la tormenta, tendremos que enfrentarla juntos en lugar de intentar protegerlos de ella.",
  ui_story_5080_50800500_33_dialog_content = "La tormenta, eh...",
  ui_story_5080_50800500_34_dialog_content = "Sinsa! Roy!",
  ui_story_5080_50800500_35_dialog_content = "¿Eve? Justo estábamos hablando de ti. ¿Qué haces aquí, eh?",
  ui_story_5080_50800500_36_dialog_content = "Estaba tan preocupado por ustedes dos, así que salimos aquí para buscarlos.",
  ui_story_5080_50800500_37_dialog_content = "¡Vamos, Sinsa! ¡Vamos a casa!",
  ui_story_5080_50800500_38_dialog_content = "Roy... Cuando la tormenta llegó en aquel entonces, no quería soltar a Eve... Porque tenía miedo de perderla...",
  ui_story_5080_50800500_39_dialog_content = "Pero al final, ella fue la que nos salvó a ambos...",
  ui_story_5080_50800500_40_dialog_content = "Pase lo que pase, nunca dejaré a mi familia. Pero... creo que podrías tener razón acerca de estos niños. Son mucho más fuertes de lo que podríamos imaginar.",
  ui_story_5080_50800500_41_dialog_content = "Sí, pero eso no significa que tenga que llevarlos conmigo. Pueden ayudar defendiendo nuestro hogar.",
  ui_story_5080_50800500_42_dialog_content = "De todos modos, podemos discutir los arreglos de trabajo después de que volvamos... Oye, ¿qué pasa con el pañuelo?",
  ui_story_5080_50800500_43_dialog_content = "Estoy tan conmovido, joven Sinsa... Has crecido tanto en los últimos quince años.",
  ui_story_5080_50800500_44_dialog_content = "¡Deja eso, idiota! He sido el líder de Wrench durante años, ¡así que deja de agruparme con los otros niños!",
  ui_story_5080_50800500_45_dialog_content = "¿Por qué tardaron tanto? Ah, no importa. Es hora de comer, así que no me estorben! ¡Espérenme, Rabbie!",
  ui_story_5080_50800500_46_dialog_content = "¿Qué pasó ahí fuera? Parece que los dos estuvieron revolcándose en un horno.",
  ui_story_5080_50800500_47_dialog_content = "No pasó nada, solo fuimos a ver el volcán.",
  ui_story_5080_50800500_48_dialog_content = "Tch—Escuché que Azure volverá pronto. La próxima vez que ustedes se vayan por su cuenta, recuerden traernos algo de alcohol.",
  ui_story_5080_50800500_49_dialog_content = "¡Vamos a comer ya! ¡Estoy a punto de morir de hambre aquí!",
  ui_story_5080_50800500_50_dialog_content = "¿Eh? ¿Dónde están Zeta y Tiny One?",
  ui_story_5080_50800500_51_dialog_content = "No tengo idea, ¡pero esta cecina de lagarto es lo máximo! Tal vez se encontraron con algún problema y tuvieron que escapar por un túnel secreto.",
  ui_story_5080_50800500_52_dialog_content = "Estoy un poco preocupado, considerando lo tarde que es.",
  ui_story_5080_50800500_53_dialog_content = "Hola Barbara, estabas causando un alboroto con ellos antes. ¿Tienes idea de dónde se fueron?",
  ui_story_5080_50800500_54_dialog_content = "Hmm... Fue demasiado caótico para recordar algo claramente, pero creo que se fueron con Jeriah.",
  ui_story_5080_50800500_55_dialog_content = "Dijo algo sobre reclutar a un nuevo miembro para su partido. ¿Se referirá a esa mujer de antes?",
  ui_story_5080_50800500_56_dialog_content = "Ella se fue con Jeriah, eh... Si quieren buscar a ese soldado de Illumina, entonces digo que los dejen ser.",
  ui_story_5080_50800500_57_dialog_content = "Pero apenas sabemos algo sobre esa mujer. Y con toda esta actividad volcánica, es demasiado peligroso dejarlos solos allí...",
  ui_story_5080_50800500_58_dialog_content = "Iremos a buscarlos. Casi hemos termino de comer.",
  ui_story_5080_50800500_59_dialog_content = "Necesitarás un buen conductor. ¡Yo también voy!",
  ui_story_5080_50800500_60_dialog_content = "Sugiero que nosotros...",
  ui_story_5080_50800500_61_dialog_content = "¿Estás seguro de que puedes conducir de noche sin volcar el coche?",
  ui_story_5080_50800500_62_dialog_content = "¡Cuenta conmigo! Además, ya no necesito comer mucho últimamente.",
  ui_story_5080_50800500_63_dialog_content = "Todavía creo que deberíamos...",
  ui_story_5080_50800500_64_dialog_content = "¡Yo también iré! ¡Mi apasionado canto guiará a nuestros pequeños a través de la noche!",
  ui_story_5080_50800500_65_dialog_content = "Eso es simplemente porque será demasiado ruidoso y molesto para ignorar.",
  ui_story_5080_50800500_66_dialog_content = "¿Quieres decirme eso a la cara?!",
  ui_story_5080_50800500_67_dialog_content = "¡Basta!",
  ui_story_5080_50800500_68_dialog_content = "Iré a buscarlos, así que todos ustedes simplemente cállense y coman!",
  ui_story_5080_50800500_69_dialog_content = "¡A comer, todos! ¿Eh? ¿Hay algo malo con la comida?",
  ui_story_5080_50800500_70_dialog_content = "Perdóname si estoy siendo grosero, pero ¿esto realmente cuenta como comida... Eh?!",
  ui_story_5080_50800500_71_dialog_content = "¡Guau! ¡Este gusano de arena frito está mucho más crujiente que antes!",
  ui_story_5080_50800500_72_dialog_content = "¡Y esta cola de serpiente a la parrilla es tan tierna y fresca!",
  ui_story_5080_50800500_73_dialog_content = "¿Por qué no estás comiendo, Carleen? No te preocupes, Vice y yo sentíamos lo mismo antes, ¡pero esto es totalmente delicioso!",
  ui_story_5080_50800500_74_dialog_content = "A-Aprecio tu preocupación... Pero, ¿podrías por favor sostener esa brocheta un poco más lejos de mí?",
  ui_story_5080_50800500_75_dialog_content = "¡Este sabor...!!!",
  ui_story_5080_50800500_76_dialog_content = "¡Es incluso mejor que las mejores raciones enlatadas de nuestro ejército!",
  ui_story_5080_50800500_77_dialog_content = "Parece que la Federación Illumina podría tratar un poco mejor a sus soldados...",
  ui_story_5080_50800500_78_dialog_content = "No pensé que disfrutarías tanto de la comida del Desierto Rediesel, Capitán.",
  ui_story_5080_50800500_79_dialog_content = "Para ser honesto, no estoy particularmente interesado en los placeres culinarios.",
  ui_story_5080_50800500_80_dialog_content = "¡Ahh, eso me ha sentado bien! Es hora de volver al trabajo, ¡así que no me molestes!",
  ui_story_5080_50800500_81_dialog_content = "Entonces te gustan las ratas de arena asadas con miel igual que a mí, ¿eh?",
  ui_story_5080_50800500_82_dialog_content = "Jeje, incluso un siniestro soldado de Illumina no está más allá de la gracia salvadora de la comida deliciosa!",
  ui_story_5080_50800500_83_dialog_content = "Si alguien es siniestro, es Rediesel Wrench. Me niego a aceptar... que tengamos algo en común.",
  ui_story_5080_50800500_84_dialog_content = "(¿Eh? ¿Por qué está siendo tan mala de repente?)",
  ui_story_5080_50800500_85_dialog_content = "¿En serio? ¡Porque creo que es genial que tengamos algo en común! ¡No temas, el legendario salvador del mundo te rescatará también de tu malvada organización!",
  ui_story_5080_50800500_86_dialog_content = "¡Siempre habrá un asiento para ti en mi vehículo!",
  ui_story_5080_50800500_87_dialog_content = "Suena bastante genial, ¿verdad? ¡Siempre he querido decir eso!",
  ui_story_5080_50800500_88_dialog_content = "La Rediesel Wrench... no es más que una vergonzosa banda de desertores de Illumina.",
  ui_story_5080_50800500_89_dialog_content = "No solo olvidaron su identidad y honor, sino que también cayeron en el bandolerismo y apuntaron sus armas a los civiles.",
  ui_story_5080_50800500_90_dialog_content = "Nadie podría aprobar jamás sus acciones. Ni siquiera... un niño como tú.",
  ui_story_5080_50800500_91_dialog_content = "¡No soy un niño, y no nos parecemos en nada a eso! Debes estar confundiéndonos con algún otro grupo!",
  ui_story_5080_50800500_92_dialog_content = "Y permitir que niños inocentes como tú caigan en sus manos es culpa de Illumina, por eso haremos todo lo posible para corregir las cosas.",
  ui_story_5080_50800500_93_dialog_content = "Y con eso, ¿te refieres a entregarlos a los <color=#FFB400>Ejecutores</color> de Illumina?",
  ui_story_5080_50800500_94_dialog_content = "¿¡Qué?! Nunca había oído hablar de algo así antes...!",
  ui_story_5080_50800500_95_dialog_content = "Antes de que este desierto tuviera un nombre, cuando la <color=#FFB400>Rediesel Wrench</color> aún no existía, Illumina tenía su buena cantidad de desertores que llegaron a este lugar.",
  ui_story_5080_50800500_96_dialog_content = "Su deseo de libertad los llevó a abandonar Illumina y refugiarse en esta tierra dura y desolada.",
  ui_story_5080_50800500_97_dialog_content = "Pero al final, los <color=#FFB400>Ejecutores</color> de Illumina los persiguieron hasta el desierto y los derribaron.",
  ui_story_5080_50800500_98_dialog_content = "De ninguna manera...",
  ui_story_5080_50800500_99_dialog_content = "Illumina es la razón por la que los colonos originales de este desierto tomaron las armas y por qué desconfiaban tanto el uno del otro.",
  ui_story_5080_50800500_100_dialog_content = "... Pero eso quedó en el pasado. El Gran Mariscal de hoy no aprueba estos métodos, sino que aboga por un nuevo sistema.",
  ui_story_5080_50800500_101_dialog_content = "¡Illumina ya no persigue a sus desertores! Siempre que los bandidos de Rediesel depongan sus armas y regresen pacíficamente, nadie será—",
  ui_story_5080_50800500_102_dialog_content = "Durante la Crisis de Darkover, Sinsa y los demás incluso fueron a Gannon City para proporcionar refuerzos... Es una lástima que nunca se les recompensó adecuadamente por su bondad.",
  ui_story_5080_50800500_103_dialog_content = "Debe haber habido algún tipo de malentendido. Estoy seguro de que ambas partes podrían llegar a un acuerdo si simplemente discuten las cosas de manera razonable.",
  ui_story_5080_50800500_104_dialog_content = "Si es posible... Preferiría no lastimar a ninguno de ustedes. Pero como extraños, es imposible que comprendan el significado de la deserción.",
  ui_story_5080_50800500_105_dialog_content = "La decisión egoísta de una persona podría dañar a innumerables otras personas... Podría arruinar todo, así como a sus familias.",
  ui_story_5080_50800500_106_dialog_content = "(Parece extrañamente agitada en este momento... ¿Qué podría estar recordando?)",
  ui_story_5080_50800500_107_dialog_content = "¿Es eso así? ¿Por qué deberían atarse las alas de un pájaro solo porque nace en Illumina?",
  ui_story_5080_50800500_108_dialog_content = "Nací en Rediesel Wrench, aunque nunca encajé realmente con ellos. Aun así, pude ver que eran solo un grupo de tontos amantes de la libertad.",
  ui_story_5080_50800500_109_dialog_content = "Se me permitió irme y construir una vida para mí mismo cuando quisiera. Todos ellos también tienen sus propias decisiones que tomar.",
  ui_story_5080_50800500_110_dialog_content = "Pedirles que regresen a Illumina y sean controlados por el sistema, despojados de su individualidad. No puedo imaginar que alguna vez estuvieran de acuerdo con eso.",
  ui_story_5080_50800500_111_dialog_content = "¡No es justo decir eso, no siento eso por Illumina en absoluto!",
  ui_story_5080_50800500_112_dialog_content = "¿Entonces no podemos hacer lo que queramos en Illumina? ¿Qué pasa con las carreras de resistencia? ¿Todavía se permiten las carreras de resistencia?",
  ui_story_5080_50800500_113_dialog_content = "Bueno, las Ciudades Subterráneas tienen mucha maquinaria delicada e invaluable, así que... no.",
  ui_story_5080_50800500_114_dialog_content = "¡Eso suena horrible! ¡Nunca querría ir allí!",
  ui_story_5080_50800500_115_dialog_content = "¡R-Realmente no está tan mal! ¡Tenemos todo tipo de otras competencias también! ¡Y siempre podrías solicitar el deber de transporte!",
  ui_story_5080_50800500_116_dialog_content = "La misión de Illumina es proteger a todos los Aurorianos. Los sacrificios individuales son necesarios por el bien del conjunto.",
  ui_story_5080_50800500_117_dialog_content = "Oh, mi pequeño ave de presa. Illumina debe haber hecho todo lo posible para entrenar a un soldado tan firme.",
  ui_story_5080_50800500_118_dialog_content = "No hay necesidad de oscurecer las cosas. Vengo de una larga línea de orgullosos héroes y la fe de mi familia en Illumina es más fuerte de lo que podrías imaginar.",
  ui_story_5080_50800500_119_dialog_content = "¡Ningún sacrificio es demasiado grande para el esplendor de Illumina! Nuestras vidas son efímeras, ¡pero la gloria es eterna!",
  ui_story_5080_50800500_120_dialog_content = "Y cuando todos hayan sido sacrificados, ¿quién quedará para recordar a los héroes?",
  ui_story_5080_50800500_121_dialog_content = "Dices que vienes de una larga línea de héroes, pero ¿recuerdas lo que logró el abuelo de tu abuelo? ¿O lo que disfrutaba en la vida?",
  ui_story_5080_50800500_122_dialog_content = "Estoy seguro de que desde pequeño te contaron sobre la grandeza de tus antepasados... Pero, ¿qué sabes realmente sobre su existencia?",
  ui_story_5080_50800500_123_dialog_content = "(Yo...)",
  ui_story_5080_50800500_124_dialog_content = "... Aunque sus actos de valor puedan ser olvidados con el tiempo, los frutos de los logros de un héroe siempre permanecerán.",
  ui_story_5080_50800500_125_dialog_content = "En un mundo dominado por los Eclipsites, debemos continuar viviendo, creciendo y transmitiendo nuestra voluntad... Tal como lo han hecho innumerables héroes caídos antes que nosotros. ",
  ui_story_5080_50800500_126_dialog_content = "Aunque puede que no conozca a todos ellos por su nombre, sus sacrificios y logros perduran a través de nosotros, los herederos de Astra.",
  ui_story_5080_50800500_127_dialog_content = "Esos héroes me han influenciado, dándome la determinación para cruzar miles de caminos para llegar aquí... ¡No tengo arrepentimientos!",
  ui_story_5080_50800500_128_dialog_content = "¡Sus cuentos y sus existencias nunca desaparecerán realmente! Continuarán llegando a los corazones y vidas de otras personas de más formas de las que podemos imaginar!",
  ui_story_5080_50800500_129_dialog_content = "Carleen...",
  ui_story_5080_50800500_130_dialog_content = "La princesa de Lumopolis realmente sabe cómo dar un excelente discurso.",
  ui_story_5080_50800500_131_dialog_content = "Lancer Blanco... Tienes toda la razón.",
  ui_story_5080_50800500_132_dialog_content = "Ey jefe, ¿no vas a entrar? ¡Has estado espiándonos todo este tiempo!",
  ui_story_5080_50800500_133_dialog_content = "¡Shhh! Tranquilo, Tiny One. Todavía estoy intentando escuchar...",
  ui_story_5080_50800500_134_dialog_content = "¡Lancer Blanco hace un excelente punto! Yo... una vez pertenecí a un escuadrón de soldados leales que dieron sus vidas en nombre de la justicia. Me honraron con su bondad, y siempre estaré orgulloso de ello.",
  ui_story_5080_50800500_135_dialog_content = "Su ejemplo es uno que merece ser seguido.",
  ui_story_5080_50800500_136_dialog_content = "Así es... Porque si no lo hago, yo...",
  ui_story_5080_50800500_137_dialog_content = "¿Eh? ¿A dónde vas, Capitán—",
  ui_story_5080_50800500_138_dialog_content = "Solo dale un poco de espacio.",
  ui_story_5080_50800500_139_dialog_content = "Hmph... Zeta, Tiny One, vamos a casa.",
  ui_story_5080_50800500_140_dialog_content = "¿¡E-El líder de los bandidos de Rediesel?! ¿Cuándo tú...",
  ui_story_5080_50800500_141_dialog_content = "¡Está hecho! ¡Lo arreglé! ¡Ohhh, espera hasta que Odi descubra que arreglé algo en lo que ella nunca ha trabajado antes!!!",
  ui_story_5080_50800500_142_dialog_content = "Pero <color=#FFB400>Guerrero Maldito</color>... Realmente me gustaría quedarme...",
  ui_story_5080_50800500_143_dialog_content = "... Entonces adelante. Después de todo, ya eres todo un adulto. ¿Podrías vigilar a estos mocosos, Jeriah?",
  ui_story_5080_50800500_144_dialog_content = "¡Espera! Tú... Tú sabes sobre ese Eclipsite, ¿no es así?",
  ui_story_5080_50800500_145_dialog_content = "Después de todos estos años deambulando por el desierto, Rediesel Wrench debe saber más sobre su existencia. ¿Podrías decirme dónde encontrar su nido?",
  ui_story_5080_50800500_146_dialog_content = "No eres el primer soldado de Illumina que viene a buscarlo, ni mucho menos... Pero desafortunadamente, ninguno de esos chicos volvió nunca.",
  ui_story_5080_50800500_147_dialog_content = "No eres nada especial comparado con ellos, así que simplemente ríndete ya. No hay razón para que te maten por tu misión.",
  ui_story_5080_50800500_148_dialog_content = "Me enfurece saber que después de todos estos años, todavía están enviando personas a su muerte.",
  ui_story_5080_50800500_149_dialog_content = "¡No entiendes! Estas son nuestras órdenes como soldados, ¡y los inimaginables tesoros escondidos dentro de los Territorios Secretos valen cada noble sacrificio!",
  ui_story_5080_50800500_150_dialog_content = "Sigues diciendo esa palabra una y otra vez, pero ¿realmente sabes lo que significa \"sacrificio\"?",
  ui_story_5080_50800500_151_dialog_content = "¡Adelante, dime lo que crees que significa!",
  ui_story_5080_50800500_152_dialog_content = "¡Es la disposición a dar la propia vida por el esplendor de Illumina y el bien mayor!",
  ui_story_5080_50800500_153_dialog_content = "¡Así como... la determinación de cumplir la misión a cualquier precio!",
  ui_story_5080_50800500_154_dialog_content = "Jajajaja—",
  ui_story_5080_50800500_155_dialog_content = "¿Por qué te ríes? ¿Crees que esto es una broma?!",
  ui_story_5080_50800500_156_dialog_content = "Sí, lo hago. Realmente no eres diferente a las personas que vinieron antes que tú, así que solo vete a casa. Este desierto ya ha cobrado demasiadas vidas.",
  ui_story_5080_50800500_157_dialog_content = "Vamos, Tiny One.",
  ui_story_5080_50800500_158_dialog_content = "No sabes nada... No somos iguales... No tienes idea de qué tipo de resolución me trajo aquí...",
  ui_story_5080_50800500_159_dialog_content = "Ya no deshonraré a mi familia... Tengo que... lavar nuestra vergüenza...",
  ui_story_5080_50800601_1_dialog_content = "¿No vas a dormir un poco, Vice?",
  ui_story_5080_50800601_2_dialog_content = "Bostezo—Todavía necesito terminar el informe de la misión de hoy... ¡Pero no te preocupes por mí! Adelante, ve a descansar.",
  ui_story_5080_50800601_3_dialog_content = "Me pareces bastante cansado.",
  ui_story_5080_50800601_4_dialog_content = "Es una gran oportunidad trabajar con el Capitán... Esta es una experiencia tan rara...",
  ui_story_5080_50800601_5_dialog_content = "Tengo que... escribir todo...",
  ui_story_5080_50800601_6_dialog_content = "Aquí, déjame ayudarte con eso.",
  ui_story_5080_50800601_7_dialog_content = "Nng... Eso no... va a funcionar...",
  ui_story_5080_50800601_8_dialog_content = "Está bien. Solo queda un poco por escribir. Lo terminaré por ti.",
  ui_story_5080_50800601_9_dialog_content = "Después de pasar tanto tiempo con Vice, incluso PlayerName se ha acostumbrado a hacer esto por ella.",
  ui_story_5080_50800601_10_dialog_content = "No estoy seguro de cuándo ocurrió, pero probablemente sea por todas las conferencias que me da... No te preocupes, esto no tomará mucho tiempo. Ve a dormir un poco, Carleen.",
  ui_story_5080_50800601_11_dialog_content = "Parece que todavía tienes algo en mente... Pero si insistes. Buenas noches.",
  ui_story_5080_50800601_12_dialog_content = "(Solo necesito agregar una última parte, y su informe estará terminado.)",
  ui_story_5080_50800601_13_dialog_content = "¡Pero espera, hay más... Y esta es también la mejor parte!",
  ui_story_5080_50800601_14_dialog_content = "(¿Es esa la voz de Zeta? Puedo escucharla desde aquí... ¿Cómo es que todavía tiene tanta energía?)",
  ui_story_5080_50800601_15_dialog_content = "¡Y así la niña bruja y yo saltamos a nuestro coche de carreras!",
  ui_story_5080_50800601_16_dialog_content = "(¿Con quién está hablando ella? Ya terminé de escribir... Supongo que no haría daño echar un vistazo.)",
  ui_story_5080_50800601_17_dialog_content = "¡Whoosh! Mi auto avanzó rápidamente y evitamos por poco las garras del dragón. ¡Bang! ¡Choque!",
  ui_story_5080_50800601_18_dialog_content = "¡Embistí al dragón con mi coche y lo mandé a volar! ¡Incluso la bruja no tuvo más remedio que reconocer mi poder!",
  ui_story_5080_50800601_19_dialog_content = "(Suena como si estuviera exagerando un poco... ¿Eh? ¿Es eso... Rachel? ¿Está Zeta molestandola mientras está de guardia?)",
  ui_story_5080_50800601_20_dialog_content = "¡Oh, y apuesto a que no sabías esto! ¡Cuando acelero mi motor, montones de lagartos comienzan a salir de la arena!",
  ui_story_5080_50800601_21_dialog_content = "¡Esos lagartos saben mejor! ¡Son incluso más tiernos que los que comimos hoy!",
  ui_story_5080_50800601_22_dialog_content = "Todos somos bastante buenos cocinando por aquí, ¡así que apuesto a que también te gustarían!",
  ui_story_5080_50800601_23_dialog_content = "... ¿Te gustaría probar una de mis galletas militares comprimidas?",
  ui_story_5080_50800601_24_dialog_content = "No, gracias, esos se ven horribles.",
  ui_story_5080_50800601_25_dialog_content = "¡Lo que me recuerda! ¿Alguna vez te dije que organizo rallies todo por mí mismo?",
  ui_story_5080_50800601_26_dialog_content = "A diferencia de esa malvada chica bruja, ¡no dependo del Último Caelestite para llegar a la meta!",
  ui_story_5080_50800601_27_dialog_content = "¡La gloria de atravesar el implacable desierto ardiendo me pertenece solo a mí!",
  ui_story_5080_50800601_28_dialog_content = "Eso es impresionante. Nunca lo hubiera sabido solo con mirarte.",
  ui_story_5080_50800601_29_dialog_content = "Jeje, ¿bastante genial, verdad? ¡La legendaria guerrera Zeta y sus gloriosos logros son suficientes para convencer a cualquier malhechor de abandonar sus malvados caminos! ¡Por eso deberías quedarte conmigo!",
  ui_story_5080_50800601_30_dialog_content = "¡Tu habilidad para sobrevivir solo en el desierto durante tanto tiempo te convertiría en un excelente navegante en mis rallies!",
  ui_story_5080_50800601_31_dialog_content = "¡Súbete a mi coche y podemos compartir la gloria de ganar nuestra próxima carrera!",
  ui_story_5080_50800601_32_dialog_content = "¿Gloria, eh...? Realmente solo soy bueno con las máquinas. ¿Realmente soy una buena elección para tu equipo?",
  ui_story_5080_50800601_33_dialog_content = "¡Por supuesto! Solo déjame a mí el entrenamiento, ¡y te convertiré en un miembro legendario de mi tripulación!",
  ui_story_5080_50800601_34_dialog_content = "Puedes encargarte de... ¿Cómo se llamaba eso de nuevo? Es como un mapa, pero con mucha más información... ¡El libro de ruta! Te enseñaré cómo hacer un libro de ruta adecuado para nuestras carreras!",
  ui_story_5080_50800601_35_dialog_content = "Por supuesto. Eso me parece bastante interesante.",
  ui_story_5080_50800601_36_dialog_content = "(¿Es esto real? Esos dos realmente están teniendo una conversación...)",
  ui_story_5080_50800601_37_dialog_content = "¡Hay muchas otras cosas interesantes aquí en el desierto también! A partir de mañana, ¡te enseñaré todo sobre ellas!",
  ui_story_5080_50800601_38_dialog_content = "Y después de entrenarte... finalmente podré derrotar a esa bruja...",
  ui_story_5080_50800601_39_dialog_content = "Pero en este momento, es hora de que me vaya a la cama... Buenas noches...",
  ui_story_5080_50800601_40_dialog_content = "<color=#828282>¡Ruido!</color>",
  ui_story_5080_50800601_41_dialog_content = "Honestamente... ¿No duele eso?",
  ui_story_5080_50800601_42_dialog_content = "Descansa mucho entonces... Buenas noches.",
  ui_story_5080_50800601_43_dialog_content = "(Un minuto es fría y distante, y al siguiente es cálida y amable... ¿Cuál es la verdadera tú, Rachel?)",
  ui_story_5080_50800601_44_dialog_content = "(Quizás ahora sea un buen momento para hablar con ella... ¿Eh? Esas emociones poderosas... Han vuelto de nuevo...)",
  ui_story_5080_50800601_45_option_content = "Sentido Rachel",
  ui_story_5080_50800601_46_dialog_content = "El objetivo ha sido adquirido y nuestra misión ahora está completa. ¡Lo hicimos, Capitán!",
  ui_story_5080_50800601_47_dialog_content = "Bien hecho... Pero no bajes la guardia todavía, no mientras las ruinas aún estén llenas de Eclipsites. Necesitamos salir de aquí.",
  ui_story_5080_50800601_48_dialog_content = "Búho Verde, Cernícalo Rojo, tomen el núcleo de datos y retírense por nuestra ruta de infiltración.",
  ui_story_5080_50800601_49_dialog_content = "Esta cosa es bastante pesada, Capitán. Permíteme llevarla en su lugar.",
  ui_story_5080_50800601_50_dialog_content = "Está bien, solo mantén la vigilancia. Necesitamos reagruparnos con los demás en el punto de exfiltración.",
  ui_story_5080_50800601_51_dialog_content = "Capitán, parece haber una perturbación dentro de las filas de Eclipsite.",
  ui_story_5080_50800601_52_dialog_content = "Se están moviendo en una dirección diferente... ¿Por qué se están reuniendo así?",
  ui_story_5080_50800601_53_dialog_content = "No... ¡Están empezando a avanzar hacia nosotros!",
  ui_story_5080_50800601_54_dialog_content = "¡Corre!",
  ui_story_5080_50800601_55_dialog_content = "Búho Verde, Cernícalo Rojo, ¡entren! ¿Cuál es la situación en el punto de extracción?",
  ui_story_5080_50800601_56_dialog_content = "Los Eclipsites parecen estar convergiendo en un solo punto... ¡Esto es malo, Capitán! Se están acercando a tu posición!",
  ui_story_5080_50800601_57_dialog_content = "Solo mantén la calma y sigue el plan. Pronto estaremos allí, ¡así que asegúrate de que nuestra ruta de escape permanezca abierta!",
  ui_story_5080_50800601_58_dialog_content = "¡No te molestes con esos Eclipsites, Ganso Blanco! ¡Vamos!",
  ui_story_5080_50800601_59_dialog_content = "¡Escolta al Capitán fuera de aquí, Ala Gris! ¡Yo atraeré su atención lejos de ti!",
  ui_story_5080_50800601_60_dialog_content = "¿De qué estás hablando? ¡Vamos a salir de aquí juntos! Capitán, tienes que deshacerte del núcleo de datos, o no podremos escapar de esos Eclipsites!",
  ui_story_5080_50800601_61_dialog_content = "¿Cómo esas cosas saben de nuestra posición? Es como si estuvieran tratando de proteger el núcleo...",
  ui_story_5080_50800601_62_dialog_content = "¡Sigue el ritmo, White Goose! ¡No más escapadas por tu cuenta!",
  ui_story_5080_50800601_63_dialog_content = "Pero Capitán... A este ritmo, nunca lo lograremos...",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang—!</color>",
  ui_story_5080_50800601_65_dialog_content = "¡Por aquí, Capitán!",
  ui_story_5080_50800601_66_dialog_content = "¡Es el Búho Verde y el Cernícalo Rojo!",
  ui_story_5080_50800601_67_dialog_content = "¡Tontos! Les di órdenes claras de vigilar la salida, ¿¡entonces qué están haciendo aquí?!",
  ui_story_5080_50800601_68_dialog_content = "No lo habrías logrado si no hubiéramos desobedecido tus órdenes, Capitán.",
  ui_story_5080_50800601_69_dialog_content = "¡Si vas a disciplinarnos, al menos espera hasta que lleguemos a un lugar seguro!",
  ui_story_5080_50800601_70_dialog_content = "Idiotas...",
  ui_story_5080_50800601_71_dialog_content = "¡Me preguntaba qué estaba tomando tanto tiempo! ¿Has estado cargando esta cosa pesada todo este tiempo, Capitán?",
  ui_story_5080_50800601_72_dialog_content = "Así que este es el núcleo, ¿eh? Esta cosa no es exactamente portátil, Capitán. Deberíamos...",
  ui_story_5080_50800601_73_dialog_content = "¡No! ¡La misión es lo primero! Los datos en este núcleo tienen el poder de cambiar todo Illumina... El Escuadrón Eagleeye no puede permitirse fallar, incluso si pone nuestras vidas en riesgo!",
  ui_story_5080_50800601_74_dialog_content = "Si fallamos, nos convertirá a todos en desertores... No... Permitiré que hagas pasar a tus familias por ese tipo de vergüenza.",
  ui_story_5080_50800601_75_dialog_content = "La salida está justo adelante y yo cubriré la retaguardia. ¡Ahora ve! Asegúrate de que el núcleo de datos regrese a Illumina!",
  ui_story_5080_50800601_76_dialog_content = "¡No puedo, Capitán!",
  ui_story_5080_50800601_77_dialog_content = "¿Estás desobedeciendo órdenes de nuevo, Ala Gris?!",
  ui_story_5080_50800601_78_dialog_content = "Según el Capítulo 6, Subsección 31 del Decreto de Finalización de Misión de Illumina, un vice-capitán de escuadrón puede reemplazar las órdenes del capitán siempre que el resto del escuadrón esté de acuerdo!",
  ui_story_5080_50800601_79_dialog_content = "Nunca ha habido un explorador mejor que tú, Capitán. Incluso si logramos pasar por la salida, no hay garantía de que regresemos a salvo a la superficie.",
  ui_story_5080_50800601_80_dialog_content = "Como vice-capitán, ¡inició una votación! Todos a favor de apoyar al Capitán y cubrir su escape, digan \"¡sí\"!",
  ui_story_5080_50800601_81_dialog_content = "¡Sí!",
  ui_story_5080_50800601_82_dialog_content = "Sí.",
  ui_story_5080_50800601_83_dialog_content = "Hermana, tu...",
  ui_story_5080_50800601_84_dialog_content = "\"La misión viene antes que todo\", ¿recuerdas? Lo siento, Capitán... Pero tu misión ahora es diferente.",
  ui_story_5080_50800601_85_dialog_content = "Lleva el núcleo y regresa a Illumina. Tu familia todavía te está esperando, ¿no es así?",
  ui_story_5080_50800601_86_dialog_content = "No te preocupes, estaremos justo detrás de ti.",
  ui_story_5080_50800601_87_dialog_content = "¡Ahora ponte en marcha, Capitán!",
  ui_story_5080_50800601_88_dialog_content = "Yo...",
  ui_story_5080_50800601_89_dialog_content = "¡Solo espera, Cazadores de Águilas! ¡Pediré refuerzos tan pronto como llegue a la superficie!",
  ui_story_5080_50800601_90_dialog_content = "Los Eclipsites están llegando. ¿Alguien ya siente miedo?",
  ui_story_5080_50800601_91_dialog_content = "El Capitán salió a salvo. ¿De qué hay que tener miedo ahora?",
  ui_story_5080_50800601_92_dialog_content = "Haz explotar la salida. No podemos dejar que ninguno de estos monstruos nos supere.",
  ui_story_5080_50800601_93_dialog_content = "¿¡Qué?! ¡No, Ala Gris! ¡No lo hagas—!",
  ui_story_5080_50800601_94_dialog_content = "Siempre llevas tanto peso sobre tus hombros, Capitán... Realmente lo siento... Por hacerte llevar un poco más.",
  ui_story_5080_50800601_95_dialog_content = "¡¡¡Enciéndelo!!!",
  ui_story_5080_50800602_1_dialog_content = "(Eso fue Rachel... ¿Es por eso que siempre insiste en trabajar sola? Entonces, cuando nos asignaron para ayudarla...)",
  ui_story_5080_50800602_2_dialog_content = "(La razón por la que sigue ocultando sus emociones y tratándonos tan fríamente... ¿Es porque tiene miedo de perdernos?)",
  ui_story_5080_50800602_3_dialog_content = "(Después de ver su doloroso pasado, ¿debería realmente seguir intentando hablar con ella sobre eso?)",
  ui_story_5080_50800602_4_dialog_content = "Ala Gris, Ganso Blanco, Búho Verde, Cernícalo Rojo... ¿Sigues... vigilándome?",
  ui_story_5080_50800602_5_dialog_content = "<color=#828282>¡Ruido!</color>",
  ui_story_5080_50800602_6_dialog_content = "¿Quién está ahí? ¿Cómo te atreves a escuchar a escondidas—",
  ui_story_5080_50800602_7_dialog_content = "¡Miau!",
  ui_story_5080_50800602_8_dialog_content = "¿Gato?",
  ui_story_5080_50800602_9_dialog_content = "... Ven aquí, pequeño gatito.",
  ui_story_5080_50800602_10_dialog_content = "¿Te gustaría un poco de pescado seco?",
  ui_story_5080_50800602_11_dialog_content = "Buen gatito... ¿Eres la mascota del mensajero?",
  ui_story_5080_50800602_12_dialog_content = "Tu pelaje es tan suave y liso. Qué hermoso gatito pequeño.",
  ui_story_5080_50800602_13_dialog_content = "¿El tintineo de estas placas de identificación de perro llamó tu atención? También quieres hablar con ellos, ¿verdad?",
  ui_story_5080_50800602_14_dialog_content = "Ese gato fue acogido por Roy hace un tiempo y criado en la base de Rediesel Wrench. A veces puede ser bastante consentido.",
  ui_story_5080_50800602_15_dialog_content = "¡Gah!",
  ui_story_5080_50800602_16_dialog_content = "¡Miau—!",
  ui_story_5080_50800602_17_dialog_content = "¿C-Cuándo hiciste eso... Tú... no viste nada, ¿verdad?!",
  ui_story_5080_50800602_18_dialog_content = "No te preocupes, he conocido a todo tipo de personas durante mis viajes. No siento una cosa u otra acerca de tus preferencias.",
  ui_story_5080_50800602_19_dialog_content = "Además, hace mucho tiempo que sé que no eres tan duro de corazón como pareces.",
  ui_story_5080_50800602_20_dialog_content = "Pero si no te importa que lo diga, creo que tu apariencia fría solo está lastimando aún más a tus aliados.",
  ui_story_5080_50800602_21_dialog_content = "... ¿Qué te hace tan diferente? Alejaste la Rediesel Wrench, ¿no es así?",
  ui_story_5080_50800602_22_dialog_content = "¿Los alejé? Para nada. Simplemente me moví un poco más lejos de todo el ruido y la conmoción.",
  ui_story_5080_50800602_23_dialog_content = "Como sospechaba, eres justo como <color=#FFB400>esa persona</color>. No es de extrañar que me dieras una sensación tan familiar.",
  ui_story_5080_50800602_24_dialog_content = "\"¿Esa persona\"?",
  ui_story_5080_50800602_25_dialog_content = "Hay muchos ex soldados de Illumina en la Rediesel Wrench, pero uno de ellos es especialmente diferente.",
  ui_story_5080_50800602_26_dialog_content = "Al igual que tú, ella era una soldata dedicada y de élite en una misión especial, quien lideró a su equipo al desierto a una edad muy temprana.",
  ui_story_5080_50800602_27_dialog_content = "¿Ella... Sobrevivió a su exploración de los Territorios Secretos aquí?",
  ui_story_5080_50800602_28_dialog_content = "¿Recuerdas su nombre o el nombre de su escuadrón? Es posible que yo la conozca.",
  ui_story_5080_50800602_29_dialog_content = "¿Su nombre...? Cuando la conocí por primera vez, ya había abandonado su pasado. No estoy seguro si el nombre que está usando es incluso su verdadero nombre.",
  ui_story_5080_50800602_30_dialog_content = "Pero sí recuerdo el nombre de su equipo: el Escuadrón Freebird. Es el mismo nombre que me hizo sentir tanta envidia de los pájaros y su capacidad para volar libremente por el cielo.",
  ui_story_5080_50800602_31_dialog_content = "¿\"Escuadrón Freebird\"?!",
  ui_story_5080_50800602_32_dialog_content = "(¿No es ese el nombre del escuadrón que Rachel está buscando en este momento?)",
  ui_story_5080_50800602_33_dialog_content = "¿Esa persona... también escapó al desierto? Entonces, no solo se convirtió en una traidora, sino que también se unió a Rediesel Wrench—",
  ui_story_5080_50800602_34_dialog_content = "Estás equivocado, Jeriah: No soy nada como esa persona. Ella puede ser una desertora sin vergüenza, ¡pero yo no!",
  ui_story_5080_50800602_35_dialog_content = "Lo siento, mi pequeño ave de presa, pero me temo que eres tú el que está equivocado.",
  ui_story_5080_50800602_36_dialog_content = "Esa mujer no era ni descarada ni desertora. Hasta el final, fue una de las personas más orgullosas que he conocido.",
  ui_story_5080_50800602_37_dialog_content = "Su ardiente pasión era tan roja como la llave inglesa que empuñaba en sus manos. Incluso después de pasársela a Sinsa, no ha perdido nada de su color.",
  ui_story_5080_50800602_38_dialog_content = "Si eso es lo que crees... Entonces tengo una historia para compartir contigo.",
  ui_story_5080_50800602_39_dialog_content = "Fue la primera vez que <color=#FFB400>mi tía</color> me lo contó, quien una vez fue miembro del Escuadrón Freebird—",
  ui_story_5080_50800602_40_dialog_content = "Hace treinta años, Illumina formó un equipo de fuerzas especiales conocido como el Escuadrón Freebird.",
  ui_story_5080_50800602_41_dialog_content = "Los miembros de élite y seleccionados a mano de este equipo fueron encargados de llevar a cabo misiones que eran imposibles para cualquier otro escuadrón.",
  ui_story_5080_50800602_42_dialog_content = "A pesar de los desafíos incomparables a los que se enfrentaban en cada operación, el Escuadrón Freebird mantuvo una tasa de éxito de misión perfecta. Unirse a su escuadrón era la mayor aspiración de cada soldado.",
  ui_story_5080_50800602_43_dialog_content = "Si ese escuadrón todavía existiera, estoy seguro de que habrías sido el candidato perfecto para él.",
  ui_story_5080_50800602_44_dialog_content = "Pero luego fueron asignados a una misión altamente clasificada, que terminó siendo la última. Mi tía y sus camaradas arriesgaron sus vidas por ello...",
  ui_story_5080_50800602_45_dialog_content = "El precio que pagaron fue inimaginable pero al final... Su capitana los traicionó. Abandonó la misión sin autorización y llevó al resto de los supervivientes de vuelta a Illumina como una <color=#FFB400>desertora</color>.",
  ui_story_5080_50800602_46_dialog_content = "No mucho después, ella desertó completamente de Illumina, lo que sumió a mi tía en las profundidades de la desesperación.",
  ui_story_5080_50800602_47_dialog_content = "La tildaron de traidora y la acusaron de ser separatista. Despojada de su honor y degradada innumerables veces, ¡todos a su alrededor la despreciaban!",
  ui_story_5080_50800602_48_dialog_content = "Se negó a volver a casa por miedo a ser una carga para nuestra familia, y su relación con mi padre se desmoronó—",
  ui_story_5080_50800602_49_dialog_content = "Pero a pesar de todos los sacrificios de mi tía, el honor de nuestra familia todavía estaba...",
  ui_story_5080_50800602_50_dialog_content = "(Rachel...)",
  ui_story_5080_50800602_51_option_content = "Sentir las Memorias de Rachel",
  ui_story_5080_50800602_52_dialog_content = "¡Mira! ¡La hija de ese traidor está aquí otra vez!",
  ui_story_5080_50800602_53_dialog_content = "No me digas que está intentando entrar al Museo. ¡Ese lugar es donde honramos a nuestros verdaderos héroes! ¡Los traidores no tienen permitido entrar allí!",
  ui_story_5080_50800602_54_dialog_content = "Dada la historia de traición de su familia, es difícil imaginar que ella fue criada de manera diferente.",
  ui_story_5080_50800602_55_dialog_content = "¿Realmente podemos confiar en alguien como ella para cuidar nuestras espaldas, capitán?",
  ui_story_5080_50800602_56_dialog_content = "Rachel? ¿Esa niña de aspecto delgado? No creo que tenga la determinación para esto...",
  ui_story_5080_50800602_57_dialog_content = "¡De ninguna manera! ¡Ella no es buena! Deshazte de ella—",
  ui_story_5080_50800602_58_dialog_content = "¡No soy ese tipo de persona! Lo demostraré... ¡Se lo demostraré a todos!",
  ui_story_5080_50800602_59_dialog_content = "Sé que no lo eres, Rachel. Ya eres una mujer joven maravillosa y una soldado excepcional. No tienes nada que demostrarle a nadie.",
  ui_story_5080_50800602_60_dialog_content = "No, tía... Yo... No quise decir eso...",
  ui_story_5080_50800602_61_dialog_content = "Está bien, Rachel. No me importa lo que digan los demás, y a ti tampoco debería importarte.",
  ui_story_5080_50800602_62_dialog_content = "Solo mantén esa pasión en tu corazón y demuéstrales que eres mejor que tu tía sin valor.",
  ui_story_5080_50800602_63_dialog_content = "Tía... lo siento mucho...",
  ui_story_5080_50800602_64_dialog_content = "Levántate y mírame, Rachel. Nada de esto es tu culpa.",
  ui_story_5080_50800602_65_dialog_content = "Es mi culpa por traer tantos problemas a tu vida. Vas a tener que soportar muchas más críticas en el futuro.",
  ui_story_5080_50800602_66_dialog_content = "Pero no puedes dejar que te derribe. Nunca cedas a lo que dicen de ti. Lucha en voz alta y con todo tu corazón, justo como ahora.",
  ui_story_5080_50800602_67_dialog_content = "Sé que serás incluso más grande de lo que jamás podría esperar ser.",
  ui_story_5080_50800602_68_dialog_content = "Cree en ti mismo, Rachel. No importa qué decisiones tomes, mantente firme hasta el amargo final, ¡Y no escuches lo que nadie diga sobre ti!",
  ui_story_5080_50800602_69_dialog_content = "Mi tía se vio obligada a vivir fuera por su cuenta, pero siempre me trató como a su propia hija... Y por eso... Nunca podré perdonar a esa persona por lo que le hizo.",
  ui_story_5080_50800602_70_dialog_content = "Así que decidí volverse más fuerte, superar mis límites y vencer las ataduras del pasado de mi familia... No quería que esa tragedia se repitiera nunca más.",
  ui_story_5080_50800602_71_dialog_content = "Ella proviene de una familia de desertores, así que está destinada a rendirse a veces, ¿verdad?",
  ui_story_5080_50800602_72_dialog_content = "¡De ninguna manera! Creo que ella es súper genial por ser tan persistente, así que deja de hablar de ella a sus espaldas.",
  ui_story_5080_50800602_73_dialog_content = "Entonces, ¿alguno de los nuevos reclutas te llamó la atención, Hiiro?",
  ui_story_5080_50800602_74_dialog_content = "Para nada. Ninguno de ellos siquiera se acercó a seguir mi régimen de entrenamiento.",
  ui_story_5080_50800602_75_dialog_content = "Creo que estás siendo demasiado duro con ellos... Espera, ¿qué pasa con <color=#FFB400>ella</color>? No me digas que <color=#FFB400>ella</color> tampoco estuvo a la altura?",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>Esa chica</color>... Espera demasiado de sí misma, considerando que no está tan en forma físicamente como sus compañeros. Esforzarse así nunca funcionará para ella.",
  ui_story_5080_50800602_77_dialog_content = "He estado intentando descalificarla antes de que se haga algún daño permanente. Sin embargo, no importa cuánto dificulte las cosas para ella, se niega obstinadamente a rendirse.",
  ui_story_5080_50800602_78_dialog_content = "En términos de forma física, ella es completamente normal, pero al final... Ella fue la única que pudo seguir mi ritmo.",
  ui_story_5080_50800602_79_dialog_content = "La Academia está llena de rumores sobre ella y su familia, pero poco a poco, sus compañeros están empezando a respetarla.",
  ui_story_5080_50800602_80_dialog_content = "No estoy seguro si debería alabarla o no.",
  ui_story_5080_50800602_81_dialog_content = "Un soldado que nunca deja de levantarse después de ser derribado innumerables veces... Me suena a que ella tiene lo necesario para ser una heroína, Hiiro.",
  ui_story_5080_50800602_82_dialog_content = "Ya no puedes seguir negándola, así que simplemente reconoce su determinación y cuídala bien.",
  ui_story_5080_50800602_83_dialog_content = "No hay forma de que ella se deje descalificar.",
  ui_story_5080_50800602_84_dialog_content = "¡Cadete Rachel! En reconocimiento a tu rendimiento ejemplar y tu espíritu indomable, has sido especialmente elegido por el Comandante Hiiro para unirte a las filas de la 3ra Legión!",
  ui_story_5080_50800602_85_dialog_content = "(Así que esto es Rachel... Así es como ella luchó para ascender en los rangos... Y se convirtió en una capitana de élite digna del respeto de todos.)",
  ui_story_5080_50800602_86_dialog_content = "Entiendo... Has sufrido tanto para convertirte en el ave de presa que eres hoy.",
  ui_story_5080_50800602_87_dialog_content = "Je, entonces eres libre de verla como una traidora si lo deseas. Después de todo, solo intercambiamos unas pocas palabras antes de que desapareciera de nuestras vidas para siempre.",
  ui_story_5080_50800602_88_dialog_content = "Con lo astuta que era, realmente deseo que hubiera logrado escapar en aquel entonces... Tal vez entonces podría darme las respuestas que estoy buscando.",
  ui_story_5080_50800602_89_dialog_content = "¿Qué respuestas?",
  ui_story_5080_50800602_90_dialog_content = "Este desierto es vasto, ¿no crees? Podrías hacer guardia durante la noche interminable y aún así solo verías una pequeña fracción de este lugar.",
  ui_story_5080_50800602_91_dialog_content = "Su vastedad es también lo que lo hace tan vacío.",
  ui_story_5080_50800602_92_dialog_content = "Esta vacío... ¿Es por eso que nunca pudiste encajar con esas personas?",
  ui_story_5080_50800602_93_dialog_content = "Dijiste que viajaste a innumerables lugares, y sin embargo, nunca encontraste un lugar al que realmente pertenecieras, ¿verdad? Así que volviste a este lugar en su lugar...",
  ui_story_5080_50800602_94_dialog_content = "Es cierto que el desierto siempre me ha parecido extrañamente desconocido, y que nunca he estado de acuerdo con los tontos apasionados de Rediesel Wrench.",
  ui_story_5080_50800602_95_dialog_content = "Son tan ruidosos y salvajes todos los días, pero ¿realmente están buscando el sentido de la vida?",
  ui_story_5080_50800602_96_dialog_content = "Me preocupa que algún día recuperen la cordura y se den cuenta de cuánto de sus vidas han desperdiciado. Solo pensar en ello es aterrador.",
  ui_story_5080_50800602_97_dialog_content = "Las personas están destinadas a seguir caminos separados, y la fiesta tiene que terminar algún día. No importa cuánto brillamos en la vida, todos volveremos a la nada. Da miedo, ¿no es así?",
  ui_story_5080_50800602_98_dialog_content = "Así que te demoras en este desierto, un lugar que no es ni tu hogar ni una tierra desconocida.",
  ui_story_5080_50800602_99_dialog_content = "Eres solo otro pájaro solitario en el Desierto de Rediesel, igual que yo.",
  ui_story_5080_50800602_100_dialog_content = "Realmente eres muy bueno entendiendo los puntos de vista de otras personas, ¿sabes? Y esa es la marca de un verdadero gran capitán.",
  ui_story_5080_50800602_101_dialog_content = "(¡Si solo Vice estuviera despierto para ver esto! Tendré que encontrar una oportunidad para contarle sobre esto mañana.)",
  ui_story_5080_50800602_102_dialog_content = "Era solo un niño cuando esa persona aún estaba viva. Ella me enseñó muchas cosas y me abrió los ojos a la inmensidad del mundo.",
  ui_story_5080_50800602_103_dialog_content = "Ella también me motivó a buscar una vida de libertad con todo mi corazón. Quería encontrar el significado de mi vida y lanzarme de cabeza hacia un futuro de infinitas posibilidades.",
  ui_story_5080_50800602_104_dialog_content = "Pero luego murió sin decir otra palabra. Su figura orgullosa y poderosa se convirtió en solo otra imagen borrosa en nuestras memorias.",
  ui_story_5080_50800602_105_dialog_content = "Entonces, ¿a qué podría llegar? Después de alejarme de mis padres y la llave Rediesel, no queda lugar para mí en este mundo.",
  ui_story_5080_50800602_106_dialog_content = "Y mientras estoy atrapado en este profundo vacío, esos tontos siguen adelante sin una sola preocupación en el mundo. Suspiro... Realmente desearía saber qué hacer.",
  ui_story_5080_50800602_107_dialog_content = "¿Por qué me estás diciendo todo esto?",
  ui_story_5080_50800602_108_dialog_content = "Porque no estoy seguro de que pueda hablar con alguien más sobre esto.",
  ui_story_5080_50800602_109_dialog_content = "Supongo que debe haber una mejor razón para compartir mis pensamientos contigo. Tal vez es porque me recuerdas mucho a ella... ¿O quizás me recuerdas a mí mismo?",
  ui_story_5080_50800602_110_dialog_content = "¿Estás seguro de que no eres solo... Un pequeño pájaro perdido que se desvió al desierto?",
  ui_story_5080_50800602_111_dialog_content = "Parte de mí desea que estuvieras aquí para buscar a los desertores. De esa manera, podrías encontrar a esa persona y darle una lección por desaparecer de nuestras vidas así.",
  ui_story_5080_50800602_112_dialog_content = "Si no fuera por ella, quizás no estaría tan frustrado en la vida. Después de todo, ella transformó a Rediesel Wrench de un grupo de idiotas deshonrosos a un grupo de despreocupados...",
  ui_story_5080_50800602_113_dialog_content = "¿Entonces por qué no puedo ser como ellos?",
  ui_story_5080_50800602_114_dialog_content = "Jeriah, tú...",
  ui_story_5080_50800602_115_dialog_content = "Llevaré a Zeta a la cama. Deberías bajar y también dormir un poco.",
  ui_story_5080_50800602_116_dialog_content = "Dices que todo debe volver a la nada... Y sin embargo, aún estás dispuesto a sostenerla y cargarla.",
  ui_story_5080_50800602_117_dialog_content = "No se puede evitar. Después de cubrir mi casa con su \"arte\", es imposible ignorarlos.",
  ui_story_5080_50800602_118_dialog_content = "El desierto se vuelve frío por la noche. Dejaré que Speaker te releve, así que descansa un poco.",
  ui_story_5080_50800602_119_dialog_content = "Además... Nuestro pobre amigo Caelestite morirá congelado si nos quedamos aquí más tiempo.",
  ui_story_5080_50800602_120_dialog_content = "(¡Ella sabía que estaba aquí todo el tiempo!)",
  ui_story_5080_50800602_121_dialog_content = "(Tengo que salir de aquí... ¡Ay!)",
  ui_story_5080_50800602_122_dialog_content = "¿Q-Quién dejó este balde lleno de agua aquí?!",
  ui_story_5080_50800701_1_dialog_content = "Despierta. La misión aún no ha terminado.",
  ui_story_5080_50800701_2_dialog_content = "Bostezo... Buenos días, Capitán.",
  ui_story_5080_50800701_3_dialog_content = "... ¡Buenos días, ahora ve a salpicarte agua en la cara y despierta!",
  ui_story_5080_50800701_4_dialog_content = "¡S-Sí, señora!",
  ui_story_5080_50800701_5_dialog_content = "¡Continuamos nuestro trabajo de reconocimiento hoy! ¡Despierta y nos encontramos en diez minutos!",
  ui_story_5080_50800701_6_dialog_content = "Déjame unirme a ti.",
  ui_story_5080_50800701_7_dialog_content = "Si estás buscando un cierto Eclipsite, puede que tenga información que podría ser útil.",
  ui_story_5080_50800701_8_dialog_content = "¿Por qué de repente te interesa venir con nosotros? No puede ser solo por curiosidad, ¿verdad?",
  ui_story_5080_50800701_9_dialog_content = "Aunque todo deba volver a la nada, aún quiero ver cómo termina esto.",
  ui_story_5080_50800701_10_dialog_content = "No me rechazarías, ¿verdad?",
  ui_story_5080_50800701_11_dialog_content = "Además, si logramos encontrar el lugar de descanso de esa persona, me gustaría presentar mis respetos.",
  ui_story_5080_50800701_12_dialog_content = "... ¿Ya están todos despiertos? ¡Prepárense para salir!",
  ui_story_5080_50800701_13_dialog_content = "Zeta sigue durmiendo profundamente.",
  ui_story_5080_50800701_14_dialog_content = "Deja que el niño duerma. Nos vamos.",
  ui_story_5080_50800701_15_dialog_content = "Aquí está el mapa que estamos utilizando para nuestra investigación, Jeriah.",
  ui_story_5080_50800701_16_dialog_content = "Por lo que descubrí ayer, es muy probable que el nido de los Eclipsites esté en algún lugar alrededor del cinturón volcánico.",
  ui_story_5080_50800701_17_dialog_content = "He marcado varios lugares en el mapa. ¿Podrías ayudarnos a descartar alguno de estos lugares?",
  ui_story_5080_50800701_18_dialog_content = "Desafortunadamente, mi pequeño pájaro de presa, no encontrarás tu respuesta en ninguna de estas ubicaciones.",
  ui_story_5080_50800701_19_dialog_content = "Lo que tú y la mayoría de los forasteros no saben es que un enorme volcán inactivo está oculto bajo las arenas del desierto de Rediesel.",
  ui_story_5080_50800701_20_dialog_content = "¿Un volcán inactivo?",
  ui_story_5080_50800701_21_dialog_content = "Sí, aunque supongo que eso ya no es exactamente el caso. Justo ayer, confirmé que el volcán está activo de nuevo.",
  ui_story_5080_50800701_22_dialog_content = "Aunque se ha visto a ese tipo de Eclipsite vagando por todo el desierto, me temo que su nido solo puede estar en ese lugar.",
  ui_story_5080_50800701_23_dialog_content = "Después de todo, es el único lugar que generalmente evita Rediesel Wrench.",
  ui_story_5080_50800701_24_dialog_content = "¿Por qué es eso?",
  ui_story_5080_50800701_25_dialog_content = "La última vez que el volcán subterráneo entró en erupción fue durante la Crisis de Darkover. En aquel entonces, innumerables Eclipsites surgieron de las fisuras en el suelo y atacaron a Rediesel Wrench.",
  ui_story_5080_50800701_26_dialog_content = "Su líder en ese momento murió durante esa batalla, junto con los padres de Zeta y muchos otros.",
  ui_story_5080_50800701_27_dialog_content = "Desde entonces, Rediesel Wrench ha hecho de todo el desierto su hogar, pero siempre evitan ese lugar.",
  ui_story_5080_50800701_28_dialog_content = "Pero si saben que esos Eclipsites salieron del volcán, ¿por qué no han intentado investigarlo después de todos estos años?",
  ui_story_5080_50800701_29_dialog_content = "Lo hicieron, pero nunca encontraron nada.",
  ui_story_5080_50800701_30_dialog_content = "El volcán ha estado completamente inactivo desde aquel día, y ahora solo los Eclipsites regulares habitan ese lugar.",
  ui_story_5080_50800701_31_dialog_content = "La Rediesel Wrench ha ido a despejarlos varias veces, pero nunca se ha descubierto ninguna señal de esos Eclipsites.",
  ui_story_5080_50800701_32_dialog_content = "Al principio, todos pensaban que eran los únicos de su tipo y habían perecido en esa batalla junto con el líder de Rediesel Wrench y los demás.",
  ui_story_5080_50800701_33_dialog_content = "Después de tantas campañas de exterminio, incluso los Eclipsites regulares en el volcán han disminuido en número.",
  ui_story_5080_50800701_34_dialog_content = "La gente tiende a evitar sus recuerdos más dolorosos. Con el tiempo, dejaron de ir a ese lugar por completo.",
  ui_story_5080_50800701_35_dialog_content = "Pero ese solía ser su hogar... ¿Cómo pudieron simplemente abandonarlo así?",
  ui_story_5080_50800701_36_dialog_content = "¡No te veas tan triste, PlayerName! Hemos hecho un gran trabajo reconstruyendo Eraveil, ¿recuerdas? ¡Todo lo que tenemos que hacer ahora es encontrar a más de tu gente!",
  ui_story_5080_50800701_37_dialog_content = "Jeje, Vice puede tener razón. Quizás algunos de tus compatriotas Caelestite eligieron viajar por el mundo tan libremente como los pájaros mismos.",
  ui_story_5080_50800701_38_dialog_content = "Y quizás algún día... Esos pájaros volverán a anidar una vez más.",
  ui_story_5080_50800701_39_dialog_content = "...",
  ui_story_5080_50800701_40_dialog_content = "En cualquier caso, soy la única persona que todavía visita su antigua casa de vez en cuando.",
  ui_story_5080_50800701_41_dialog_content = "Y aunque mis investigaciones no han sido fructíferas, aún conozco el camino allí.",
  ui_story_5080_50800701_42_dialog_content = "Entonces te dejaremos la navegación a ti, Jeriah. Aquí está el mapa.",
  ui_story_5080_50800701_43_dialog_content = "Entendido, ahora vamos.",
  ui_story_5080_50800701_44_dialog_content = "¡E-El suelo está temblando!",
  ui_story_5080_50800701_45_dialog_content = "¡Mira! ¡El volcán está en erupción!",
  ui_story_5080_50800701_46_dialog_content = "No te alarmes tanto. Deberíamos seguir nuestro camino.",
  ui_story_5080_50800701_47_dialog_content = "La actividad volcánica no es nada nueva en el Desierto de Rediesel, pero ese no es el lugar que estamos buscando.",
  ui_story_5080_50800701_48_dialog_content = "El volcán en cuestión ha estado inactivo durante años. Incluso en el borde de su cráter, no encontré señales de actividad hasta hace poco.",
  ui_story_5080_50800701_49_dialog_content = "Pero ahora... Los rugidos han comenzado a surgir desde lo más profundo del volcán. Los rugidos de los Eclipsites.",
  ui_story_5080_50800701_50_dialog_content = "Y si ese tipo de Eclipsite ha regresado al volcán, entonces algo extraño debe estar sucediendo en este momento.",
  ui_story_5080_50800701_51_dialog_content = "¡Tenemos que darnos prisa!",
  ui_story_5080_50800701_52_dialog_content = "Por aquí. Podemos llegar al cráter del volcán descendiendo desde aquí.",
  ui_story_5080_50800701_53_dialog_content = "Vaya... ¡Este lugar está cubierto de marcas de quemaduras de lava!",
  ui_story_5080_50800701_54_dialog_content = "¿Podrían estos haber sido dejados por los Eclipsites? ¿O quizás es solo del volcán?",
  ui_story_5080_50800701_55_dialog_content = "No estoy seguro... Estaba tan ocupado con mi investigación ayer que no me aventuré muy lejos.",
  ui_story_5080_50800701_56_dialog_content = "Pero una cosa es segura: este volcán está activo ahora.",
  ui_story_5080_50800701_57_dialog_content = "Espera, ¿no significa eso que es peligroso bajar allí?",
  ui_story_5080_50800701_58_dialog_content = "Carleen, ¿puedes quedarte aquí y vigilar la entrada y nuestro coche?",
  ui_story_5080_50800701_59_dialog_content = "Entendido. Déjamelo a mí.",
  ui_story_5080_50800701_60_dialog_content = "Un poder inimaginable está haciendo que el suelo tiemble ligeramente.",
  ui_story_5080_50800701_61_dialog_content = "Este volcán es todo menos extinto.",
  ui_story_5080_50800701_62_dialog_content = "Estas huellas en el suelo... ¿Fueron dejadas por los Eclipsites?",
  ui_story_5080_50800701_63_dialog_content = "Parece que están yendo más profundo en el volcán. Vamos.",
  ui_story_5080_50800701_64_dialog_content = "¡Espera, Rachel!",
  ui_story_5080_50800701_65_dialog_content = "¡Echa un vistazo a esto!",
  ui_story_5080_50800701_66_dialog_content = "Este pasaje parece que fue excavado recientemente.",
  ui_story_5080_50800701_67_dialog_content = "¡Mira! El cráter está justo adelante!",
  ui_story_5080_50800701_68_dialog_content = "¿Por qué hay un túnel tan grande y recientemente excavado tan cerca del cráter...?",
  ui_story_5080_50800701_69_dialog_content = "Echa un vistazo a esa pared, joven Caelestite.",
  ui_story_5080_50800701_70_dialog_content = "¿Marcas de garras? Son realmente profundas, como si las hubiera dejado algo gigantesco...",
  ui_story_5080_50800701_71_dialog_content = "No hay duda. Estas marcas de garras pertenecen a ese dragón de aquel entonces.",
  ui_story_5080_50800701_72_dialog_content = "Parece que este lugar es su guarida, o quizás su zona de caza.",
  ui_story_5080_50800701_73_dialog_content = "No es de extrañar que Azure no haya podido encontrarlo todo este tiempo.",
  ui_story_5080_50800701_74_dialog_content = "Es porque el dragón tiene múltiples guaridas, y una de ellas está en un lugar que la mayoría de las personas evitan en el Desierto de Rediesel...",
  ui_story_5080_50800701_75_dialog_content = "Pero Jeriah... ¿Cómo sabías que Azure lo estaba buscando?",
  ui_story_5080_50800701_76_dialog_content = "Je, como dije, me han asignado a todo este desierto después de todo.",
  ui_story_5080_50800701_77_dialog_content = "(Por favor... Es tan claro como el día, Jeriah... Realmente te importan todos en Rediesel Wrench.)",
  ui_story_5080_50800701_78_dialog_content = "Ahora que lo pienso, las apariciones del dragón parecen corresponder con las erupciones del volcán.",
  ui_story_5080_50800701_79_dialog_content = "¿Quizás tenga que evacuar el volcán y buscar otra guarida cada vez que entra en erupción?",
  ui_story_5080_50800701_80_dialog_content = "Pero si le tiene miedo a la lava, ¿por qué eligió vivir en un volcán?",
  ui_story_5080_50800701_81_dialog_content = "No tiene sentido.",
  ui_story_5080_50800701_82_dialog_content = "Porque se estaba escondiendo de una cierta persona.",
  ui_story_5080_50800701_83_dialog_content = "En aquel entonces, esa persona estaba peinando el desierto en busca de su peligrosa presa. Para evitarla, el dragón no tuvo más opción que esconderse profundamente bajo tierra...",
  ui_story_5080_50800701_84_dialog_content = "¡El suelo está temblando de nuevo!",
  ui_story_5080_50800701_85_dialog_content = "Algo no está bien... ¡La fuente del terremoto parece estar justo debajo de nosotros! ¿Podría ser que el volcán está a punto de entrar en erupción?!",
  ui_story_5080_50800701_86_dialog_content = "La misión se ha encontrado con un obstáculo imposible, ¡Capitán! Necesitamos retirarnos por ahora!",
  ui_story_5080_50800701_87_dialog_content = "... El resto de ustedes pueden seguir sin mí. Voy a continuar con la misión.",
  ui_story_5080_50800701_88_dialog_content = "¡Pero Capitán... Es demasiado peligroso quedarse aquí abajo!",
  ui_story_5080_50800701_89_dialog_content = "La misión viene antes que todo.",
  ui_story_5080_50800701_90_dialog_content = "Es completamente natural que un depredador persiga a su presa con tanta implacabilidad.",
  ui_story_5080_50800701_91_dialog_content = "Sin embargo, tu disposición a sacrificar tu vida por algo tan ilusorio me confunde. Dime, ¿estás siendo demasiado obstinado con esto, o en realidad estás dudando?",
  ui_story_5080_50800701_92_dialog_content = "¡No hay necesidad de arriesgar nuestras vidas en este tipo de situación, Capitán! ¡Siempre podemos volver más tarde!",
  ui_story_5080_50800701_93_dialog_content = "Eso no servirá. Si el volcán entra en erupción, todo este lugar se inundará de magma, y cuando se enfríe...",
  ui_story_5080_50800701_94_dialog_content = "¡Solo vamos!",
  ui_story_5080_50800701_95_dialog_content = "¡Nos vamos de aquí juntos, Capitán!",
  ui_story_5080_50800701_96_dialog_content = "Cría Dos... ¿Por qué tenías que decirlo así...?",
  ui_story_5080_50800701_97_dialog_content = "¿Ah?",
  ui_story_5080_50800701_98_dialog_content = "(Ella está hablando de antes... El antiguo compañero de escuadrón de Rachel dijo exactamente lo mismo...)",
  ui_story_5080_50800701_99_dialog_content = "No puedo huir... No lo haré...",
  ui_story_5080_50800701_100_dialog_content = "¡Cuidado! ¡Siento que los Eclipsites vienen hacia nosotros!",
  ui_story_5080_50800701_101_dialog_content = "¡Podemos hablar de escapar más tarde! ¡Todos, prepárense para luchar!",
  ui_story_5080_50800702_1_dialog_content = "P-Por fin ha terminado.",
  ui_story_5080_50800702_2_dialog_content = "Los temblores también se detuvieron... ¿Eso significa que el volcán está estable ahora?",
  ui_story_5080_50800702_3_dialog_content = "¿Por qué esos Eclipsites eran tan poderosos? En todas mis investigaciones, nunca he visto nada como ellos aquí abajo.",
  ui_story_5080_50800702_4_dialog_content = "Sus cuerpos... ¿Son estas mutaciones?",
  ui_story_5080_50800702_5_dialog_content = "¡Está pasando de nuevo!",
  ui_story_5080_50800702_6_dialog_content = "¡Es demasiado peligroso aquí, Capitán! ¡Deberíamos al menos retirarnos al túnel de antes!",
  ui_story_5080_50800702_7_dialog_content = "Estamos demasiado cerca del cráter del volcán aquí.",
  ui_story_5080_50800702_8_dialog_content = "Bien... Haremos lo que el Polluelo Dos sugiere y buscaremos otra ruta—",
  ui_story_5080_50800702_9_dialog_content = "Espera, este temblor... ¡Esto no es el volcán en absoluto!",
  ui_story_5080_50800702_10_dialog_content = "¡Cuidado, todos! El túnel está a punto de derrumbarse—!!!",
  ui_story_5080_50800702_11_dialog_content = "El Rediesel Wrench siempre ha sido un grupo de personas tan indisciplinado.",
  ui_story_5080_50800702_12_dialog_content = "¡Oye Jeriah, ven a construir este coche con nosotros! Apuesto a que podemos terminarlo hoy si trabajamos duro.",
  ui_story_5080_50800702_13_dialog_content = "Sí, y luego podemos usarlo para atrapar montones de lagartos de arena!",
  ui_story_5080_50800702_14_dialog_content = "No, gracias.",
  ui_story_5080_50800702_15_dialog_content = "Aww, ¿pero por qué? Nunca quieres pasar el rato, Jeriah!",
  ui_story_5080_50800702_16_dialog_content = "No te preocupes, simplemente lo intentaremos de nuevo mañana!",
  ui_story_5080_50800702_17_dialog_content = "Incluso cuando les dije que no, no hizo ninguna diferencia. Aún así, nunca pude encajar con los demás.",
  ui_story_5080_50800702_18_dialog_content = "¡Ajá! ¡Parece que te encontré de nuevo!",
  ui_story_5080_50800702_19_dialog_content = "No estaba jugando al escondite contigo.",
  ui_story_5080_50800702_20_dialog_content = "Entonces eso significa que me estabas esperando, ¿verdad?",
  ui_story_5080_50800702_21_dialog_content = "¿Ves? ¡Solo te sonrojas porque tengo razón!",
  ui_story_5080_50800702_22_dialog_content = "N-De ninguna manera.",
  ui_story_5080_50800702_23_dialog_content = "Aquí tienes. No fue fácil, pero logré encontrar algunos materiales de enseñanza adicionales de Illumina.",
  ui_story_5080_50800702_24_dialog_content = "¿Saliste allí de nuevo?",
  ui_story_5080_50800702_25_dialog_content = "¡Sí! Tenía negocios que hacer con algunos comerciantes del mercado negro en Umbraton.",
  ui_story_5080_50800702_26_dialog_content = "¿Quieres saber algo más? Hay un increíble conjunto de ruinas antiguas justo en las afueras de Umbraton, y está construido con materiales que ni siquiera conocemos.",
  ui_story_5080_50800702_27_dialog_content = "Está lleno de gángsters y personas vendiendo cosas en el mercado negro. Han convertido todo el lugar en una especie de laberinto loco.",
  ui_story_5080_50800702_28_dialog_content = "Todos están buscando cualquier cosa que pueda generar ganancias. ¡Ni siquiera se dan cuenta de que las propias ruinas son lo más valioso que hay!",
  ui_story_5080_50800702_29_dialog_content = "¿A qué te refieres? ¿Qué otro valor pueden tener unas viejas ruinas, aparte de ser un lugar turístico?",
  ui_story_5080_50800702_30_dialog_content = "¡¿Estás preguntando eso en serio?!",
  ui_story_5080_50800702_31_dialog_content = "¿De qué crees que están hechas esas ruinas? ¿Por qué fueron construidas? ¿Y quién exactamente las construyó?",
  ui_story_5080_50800702_32_dialog_content = "¿Qué tipo de tecnología podemos encontrar allí? ¿Y qué puede hacer esa tecnología por nosotros?",
  ui_story_5080_50800702_33_dialog_content = "¿Cómo era la civilización antigua? ¿Qué tipo de mundo crearon para sí mismos y por qué desapareció?",
  ui_story_5080_50800702_34_dialog_content = "Esas ruinas pueden responder a todas esas preguntas y más.",
  ui_story_5080_50800702_35_dialog_content = "¿Realmente pueden decirte tanto unos viejos pasillos?",
  ui_story_5080_50800702_36_dialog_content = "¡Con un poco de tiempo y persuasión, seguro!",
  ui_story_5080_50800702_37_dialog_content = "¿Te refieres a... Esa vez de la que me hablaste antes?",
  ui_story_5080_50800702_38_dialog_content = "¿Qué hora?",
  ui_story_5080_50800702_39_dialog_content = "Cuando estabas explorando el Territorio Secreto en Northland.",
  ui_story_5080_50800702_40_dialog_content = "¡Oh, te refieres a esa vez que te enseñé a volar una cometa!",
  ui_story_5080_50800702_41_dialog_content = "Así es, esas ruinas describían una especie de máquina voladora. Cuando Illumina descubrió eso, comenzaron a invertir toneladas de recursos en investigarlo.",
  ui_story_5080_50800702_42_dialog_content = "Pero para una persona solitaria como yo, todo lo que pude hacer fue hacerte una cometa.",
  ui_story_5080_50800702_43_dialog_content = "¿Entonces qué viste en esas otras ruinas?",
  ui_story_5080_50800702_44_dialog_content = "Había demasiada gente merodeando, así que no tuve la oportunidad de hacer ninguna investigación.",
  ui_story_5080_50800702_45_dialog_content = "Pero me aseguraré de echar un buen vistazo alrededor la próxima vez que vaya.",
  ui_story_5080_50800702_46_dialog_content = "¡Incluso podría encontrar algo bonito para traerte, Jeriah!",
  ui_story_5080_50800702_47_dialog_content = "... ¿Puedo preguntarte algo?",
  ui_story_5080_50800702_48_dialog_content = "¿Eh? Claro, adelante.",
  ui_story_5080_50800702_49_dialog_content = "Básicamente has visto todo Astra, entonces, ¿por qué todavía te emocionas tanto por todo?",
  ui_story_5080_50800702_50_dialog_content = "Nada en este mundo debería sorprenderte ya. Si acaso, deberías estar totalmente aburrido a estas alturas...",
  ui_story_5080_50800702_51_dialog_content = "Oye Jeriah, ¿has leído todos los libros que te he traído?",
  ui_story_5080_50800702_52_dialog_content = "Sip. Todos los cinco mil seiscientos ochenta y tres.",
  ui_story_5080_50800702_53_dialog_content = "Pero incluso esa cantidad de libros no podría comenzar a contar toda la historia de Astra.",
  ui_story_5080_50800702_54_dialog_content = "¿También sabías que hay otros continentes en el mundo además del nuestro? Me pregunto qué tipo de personas y lugares habrá allí, ¿te lo imaginas?",
  ui_story_5080_50800702_55_dialog_content = "No tengo idea, pero siempre he tenido curiosidad por saber.",
  ui_story_5080_50800702_56_dialog_content = "He estado en la mayoría de los lugares en Astra, pero aún no puedo recordar todas las carreteras por las que he viajado.",
  ui_story_5080_50800702_57_dialog_content = "Puede que no te des cuenta ahora mismo, Jeriah, pero también tienes un ardiente deseo de explorar el mundo.",
  ui_story_5080_50800702_58_dialog_content = "No eres como yo, pasando rápidamente por todas las vistas del mundo sin detenerte a apreciarlas. Por eso creo que aprenderás más sobre este mundo de lo que yo jamás aprenderé.",
  ui_story_5080_50800702_59_dialog_content = "Deja de acariciar mi cabeza...",
  ui_story_5080_50800702_60_dialog_content = "¡De acuerdo! Querías una respuesta, ¡así que aquí está! Aunque he estado en muchos lugares diferentes, rara vez hago recuerdos cuando estoy allí.",
  ui_story_5080_50800702_61_dialog_content = "Y cuando cae la noche sobre el desierto, me doy cuenta de que apenas recuerdo alguna de las cosas hermosas que he visto en mi vida.",
  ui_story_5080_50800702_62_dialog_content = "Eso es porque... Como soldado de Illumina, siempre te envían a misiones.",
  ui_story_5080_50800702_63_dialog_content = "¡Aunque también podría estar equivocado! ¡Jajaja!",
  ui_story_5080_50800702_64_dialog_content = "Eres un niño inteligente, Jeriah. Sé que tienes muchas preguntas y sé que se siente terrible cuando no encuentras las respuestas que estás buscando.",
  ui_story_5080_50800702_65_dialog_content = "Pero no hay remedio. ¡Después de todo, todavía eres un niño!",
  ui_story_5080_50800702_66_dialog_content = "¡Así que madura y aprende todo lo que puedas, Jeriah! Estoy seguro de que podrás resolver cualquier pregunta que se te presente en el futuro!",
  ui_story_5080_50800702_67_dialog_content = "Y no desperdicies tu vida corriendo como lo hice yo. Siempre recuerda detenerte y oler las rosas.",
  ui_story_5080_50800702_68_dialog_content = "Estoy seguro de que encontrarás el significado de tu vida y harás un montón de maravillosos recuerdos en el camino.",
  ui_story_5080_50800702_69_dialog_content = "Abre tus alas y vive libremente, Jeriah. Solo entonces encontrarás... Las respuestas que estás tan desesperado por conocer.",
  ui_story_5080_50800702_70_dialog_content = "No entiendo.",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>Ella</color> y yo deberíamos ser iguales. Ambos nacimos en lugares a los que no pertenecíamos.",
  ui_story_5080_50800702_72_dialog_content = "Quería abandonar el desierto y dejar mi huella en el mundo dondequiera que fuera. Pero después de liberarse de Illumina, eligió venir aquí de todos los lugares.",
  ui_story_5080_50800702_73_dialog_content = "¿Por qué...? ¿Por qué elegiste quedarte?",
  ui_story_5080_50800702_74_dialog_content = "¿Todavía recuerdas <color=#FFB400>esa historia</color> que te conté, Jeriah?",
  ui_story_5080_50800702_75_dialog_content = "Ajá.",
  ui_story_5080_50800702_76_dialog_content = "Y al final de esa historia, encontraste <color=#FFB400>esta llave inglesa</color> y un grupo de personas que dependían de ti. Ya no estabas solo.",
  ui_story_5080_50800702_77_dialog_content = "Así que por el bien de todos, uniste a todos los nómadas del desierto y formaste el Rediesel Wrench.",
  ui_story_5080_50800702_78_dialog_content = "Nunca fuiste responsable de ninguno de ellos... Entonces, ¿por qué elegiste quedarte por ellos? ¿No quieres seguir...",
  ui_story_5080_50800702_79_dialog_content = "¿Qué tiene de malo querer volver a casa? Después de todo, nací y crecí en este desierto. Además, quiero que ellos también tengan su libertad.",
  ui_story_5080_50800702_80_dialog_content = "Vivir sin autoconciencia nos hace no diferentes de los Eclipsites, ¿no crees? Quiero liberar sus almas y darles el poder de tomar sus propias decisiones.",
  ui_story_5080_50800702_81_dialog_content = "Ya he desperdiciado la mayor parte de mi vida.",
  ui_story_5080_50800702_82_dialog_content = "Entonces, deseo que comprendan su viaje y vivan una vida de libertad.",
  ui_story_5080_50800702_83_dialog_content = "¿Convertirnos en espíritus libres que viven el momento, haciendo travesuras alegremente, es eso lo que es la libertad?",
  ui_story_5080_50800702_84_dialog_content = "No entiendo...",
  ui_story_5080_50800702_85_dialog_content = "Es por tus historias que descubrí que había mucho más esperándome para descubrir.",
  ui_story_5080_50800702_86_dialog_content = "En ese momento, estaba completamente absorto en explorar este mundo.",
  ui_story_5080_50800702_87_dialog_content = "¿Oh? Eso es bastante impresionante, Jeriah.",
  ui_story_5080_50800702_88_dialog_content = "Pero este mundo no es tan increíble como lo describiste. Me mentiste.",
  ui_story_5080_50800702_89_dialog_content = "Los nobles de Lumopolis son arrogantes, la Federación Illumina es muy aburrida y la gente de Northland sigue atrapada en sus propios cuentos de hadas.",
  ui_story_5080_50800702_90_dialog_content = "El Pasillo Susurrante de Umbraton se ha convertido en el tesoro de Istvan. Esas supuestas ruinas de leyenda son solo las indiferentes paredes internas de sus cofres.",
  ui_story_5080_50800702_91_dialog_content = "Todo parece tan vacío...",
  ui_story_5080_50800702_92_dialog_content = "Incluso los Caelestitas, quienes crearon tantos milagros científicos, finalmente se han convertido en recuerdos de los que rara vez se habla.",
  ui_story_5080_50800702_93_dialog_content = "Los Eclipsites atacan, nosotros contraatacamos... Toda vida en este mundo está atrapada en un desesperado ciclo vicioso por la supervivencia.",
  ui_story_5080_50800702_94_dialog_content = "Todo volverá a la nada.",
  ui_story_5080_50800702_95_dialog_content = "El pequeño Jeriah finalmente ha crecido, pero te preocupas demasiado.",
  ui_story_5080_50800702_96_dialog_content = "No entiendo... ¿Debería dejar de hacer preguntas?",
  ui_story_5080_50800702_97_dialog_content = "Si la inteligencia solo invita al vacío de la soledad, ¿debería elegir unirme a esos tontos despreocupados?",
  ui_story_5080_50800702_98_dialog_content = "Pero Jeriah, el último Caelestita está aquí.",
  ui_story_5080_50800702_99_dialog_content = "Deberías saber que desde el momento en que él regrese, Eraveil nunca más será un recuerdo olvidado. Su historia comenzará de nuevo con un heredero para llevar adelante esos recuerdos.",
  ui_story_5080_50800702_100_dialog_content = "¿El paisaje del mundo siempre permanece igual?",
  ui_story_5080_50800702_101_dialog_content = "La caprichosidad del destino no solo trae aburrimiento o dolor.",
  ui_story_5080_50800702_102_dialog_content = "Esas conexiones, como firmes cuerdas, te sostienen a ti, la cometa indomable...",
  ui_story_5080_50800702_103_dialog_content = "¡Espera! ¿A dónde vas? ¡No te vayas!",
  ui_story_5080_50800702_104_dialog_content = "Debes haberlo sentido, te están llamando.",
  ui_story_5080_50800702_105_dialog_content = "En tus ojos, ciertamente no soy un muy buen maestro. Pero en los míos, Jeriah... Estoy muy contento de haberte conocido.",
  ui_story_5080_50800702_106_dialog_content = "¡Espera! ¡Regresa! ¡No te vayas! ¡No te vayas—<color=#FFB400>Attar</color>—!",
  ui_story_5080_50800702_107_dialog_content = "Jeriah!",
  ui_story_5080_50800702_108_dialog_content = "...?",
  ui_story_5080_50800702_109_dialog_content = "Genial, estás despierto.",
  ui_story_5080_50800702_110_dialog_content = "Este pequeño punk estaba alucinando... Ha estado aquí sentado intentando usar sus \"movimientos especiales\" contigo todo este tiempo.",
  ui_story_5080_50800702_111_dialog_content = "¿Sinsa?",
  ui_story_5080_50800702_112_dialog_content = "Y nosotros también.",
  ui_story_5080_50800702_113_dialog_content = "... ¿Por qué siento como si la mitad de la llave Rediesel estuviera aquí?",
  ui_story_5080_50800702_114_dialog_content = "¡Hechicera! ¡Vaya, finalmente te has despertado! ¿Dónde te duele?",
  ui_story_5080_50800702_115_dialog_content = "¿Por qué dejaste atrás a tu héroe legendario favorito?! ¡Me desperté tan pronto como escuché que llegaste!",
  ui_story_5080_50800702_116_dialog_content = "Estaba luchando contra los Eclipsites cuando ella me persiguió frenéticamente, justo a tiempo para romper el asedio.",
  ui_story_5080_50800702_117_dialog_content = "Pero ella estaba demasiado emocionada, no me escuchó ni un segundo. Mi única opción fue traerla aquí para encontrarte...",
  ui_story_5080_50800702_118_dialog_content = "¡Y entonces la cueva se derrumbó repentinamente! ¿No parece algo sacado directamente de una historia de aventuras?",
  ui_story_5080_50800702_119_dialog_content = "En cuanto al derrumbe de la cueva, sentí en ese momento que era algo diferente a los temblores de un volcán...",
  ui_story_5080_50800702_120_dialog_content = "Todo es culpa de Sinsa, balanceando esa llave inglesa como un bruto... Te dije que la cueva era inestable.",
  ui_story_5080_50800702_121_dialog_content = "No te pedí que me siguieras.",
  ui_story_5080_50800702_122_dialog_content = "Eso es otra cosa, ¿por qué llamaste a tantas personas y no a mí? Debes tener algo contra mí, ¿verdad...",
  ui_story_5080_50800702_123_dialog_content = "Oye, no culpes a Sinsa. Solo estábamos buscando el tipo de ayuda adecuada, eso es todo.",
  ui_story_5080_50800702_124_dialog_content = "¿Eh? ¿Quieres decir que Jona es más útil que yo?",
  ui_story_5080_50800702_125_dialog_content = "También es peligroso en la naturaleza. Jona necesitaba quedarse en casa y mantener la fortaleza.",
  ui_story_5080_50800702_126_dialog_content = "No te preocupes, una vez que Azure regrese, Jona vendrá a ponerse al día.",
  ui_story_5080_50800702_127_dialog_content = "Tienes razón, Dawn. Jona puede rastrear a los Eclipsites. Y tú... no te subestimes, grandullón. Sabes que confío en ti.",
  ui_story_5080_50800702_128_dialog_content = "¡No, esto está todo mal! Los roles de todos son bastante claros, ¿cuál de ustedes no puede mantener la boca cerrada?! ¿Por qué aparecieron tanto tú como Eve?",
  ui_story_5080_50800702_129_dialog_content = "Lo siento... Es porque noté que tú y Dawn estaban desaparecidos, así que pregunté por ahí...",
  ui_story_5080_50800702_130_dialog_content = "¡Aaaaah!!! ¿Esos chicos ni siquiera pueden guardar un secreto de la pequeña Eve?!",
  ui_story_5080_50800702_131_dialog_content = "¿Estabas planeando dejarme a mí y a Eve atrás, eh? ¡Inaceptable! ¿Me oyes?! ¡Lo di todo solo para alcanzaros!",
  ui_story_5080_50800702_132_dialog_content = "Brock, deberías llevar a Eve de vuelta, es demasiado peligroso aquí.",
  ui_story_5080_50800702_133_dialog_content = "La carretera se ha derrumbado, sería demasiado peligroso intentar encontrar otro camino de regreso ahora. Sugiero que los dejemos quedarse.",
  ui_story_5080_50800702_134_dialog_content = "¡Basta de discusiones! Vaya... ¿Cómo terminaron las cosas así...?",
  ui_story_5080_50800702_135_dialog_content = "Bueno, ya que realmente no tenemos otra opción... Eve, Brock—ustedes dos pueden quedarse. Pero Eve, ¡asegúrate de quedarte cerca!",
  ui_story_5080_50800702_136_dialog_content = "¡De acuerdo!",
  ui_story_5080_50800702_137_dialog_content = "¡Unámonos y enfrentemos valientemente lo desconocido!",
  ui_story_5080_50800702_138_dialog_content = "He organizado una pequeña celebración de victoria por mi cuenta. Nadie puede faltar, ¿entendido, gente?",
  ui_story_5080_50800702_139_dialog_content = "Recuerda esto, ¡no intentes ser un héroe! Si los problemas te encuentran, escóndete detrás de mí, eso también va para ustedes, PlayerName.",
  ui_story_5080_50800702_140_dialog_content = "La llave Rediesel... Así que finalmente ha llegado a esto. Bueno...",
  ui_story_5080_50800702_141_dialog_content = "Tú, Chica Piruleta, puedes seguirme detrás, yo...",
  ui_story_5080_50800702_142_dialog_content = "Te protegeré.",
  ui_story_5080_50800802_1_dialog_content = "Dado que hemos llegado tan lejos juntos, supongo que hay algunas cosas que ya no necesito ocultarte.",
  ui_story_5080_50800802_2_dialog_content = "Roy, solo voy a decírselo. El terreno aquí se está volviendo más y más bajo... Podríamos encontrar el premio gordo en cualquier momento.",
  ui_story_5080_50800802_3_dialog_content = "No hay objeciones aquí. Si hay algo que te pierdas, lo explicaré.",
  ui_story_5080_50800802_4_dialog_content = "¿Por qué de repente todo esto parece tan formal...?",
  ui_story_5080_50800802_5_dialog_content = "Permíteme llevarte quince años atrás. La crisis de Darkover ya había estallado por todo Astra, habíamos estado resistiendo desesperadamente el brote durante un tiempo.",
  ui_story_5080_50800802_6_dialog_content = "Nadie habría adivinado que había un volcán oculto debajo del campamento. Hizo erupción sin previo aviso, y una inundación de Eclipsites comenzó a salir a raudales de la enorme fisura que creó.",
  ui_story_5080_50800802_7_dialog_content = "Nos pillaron desprevenidos y tuvimos que luchar mientras nos retirábamos del campamento.",
  ui_story_5080_50800802_8_dialog_content = "Solo tenía dieciséis años, ordenado a evacuar por los jefes. No era lo suficientemente fuerte... Solo pude proteger a Eve y a los demás mientras huíamos.",
  ui_story_5080_50800802_9_dialog_content = "También seguía a los líderes en ese momento. Estábamos cubriendo la retaguardia juntos... pero al final, me dijeron que corriera adelante.",
  ui_story_5080_50800802_10_dialog_content = "Nuestros líderes... Se sacrificaron en esa última batalla.",
  ui_story_5080_50800802_11_dialog_content = "Ese malvado dragón también estaba allí. Al principio, parecía que el jefe podía manejarlo, pero—",
  ui_story_5080_50800802_12_dialog_content = "Las erupciones se intensificaron y un Eclipsite goteando magma emergió desde debajo de la tierra.",
  ui_story_5080_50800802_13_dialog_content = "Ese Eclipsite goteando magma, no hay duda de ello, ese es nuestro objetivo.",
  ui_story_5080_50800802_14_dialog_content = "El jefe parecía tener algún tipo de conexión con eso. Se sorprendió y... tuvo miedo cuando lo vio.",
  ui_story_5080_50800802_15_dialog_content = "Dijo que sabía cuán fuerte era esa cosa. Por eso nos dijo a todos que saliéramos de ahí.",
  ui_story_5080_50800802_16_dialog_content = "La forma en que dio esa última orden... todo lo que pude hacer fue correr. Al final, ella se lanzó hacia adelante con algunos otros miembros mayores de la pandilla.",
  ui_story_5080_50800802_17_dialog_content = "Mmm...",
  ui_story_5080_50800802_18_dialog_content = "(Estoy percibiendo una fuerte ola de emoción... ¿Es eso... Rachel?)",
  ui_story_5080_50800802_19_option_content = "(¿Está perdiendo la compostura?)",
  ui_story_5080_50800802_20_dialog_content = "(Correcto. Ese líder es el mismo desertor que arruinó la reputación de su tía.)",
  ui_story_5080_50800802_21_option_content = "(¿Se niega a creer todo esto?)",
  ui_story_5080_50800802_22_dialog_content = "(Debe ser difícil para ella creer que la líder de aquel entonces era del tipo que se sacrificaba tan noblemente...)",
  ui_story_5080_50800802_23_dialog_content = "(¡En su corazón, esa líder siempre ha sido una desertora, temerosa de la muerte, pero para la Rediesel Wrench, claramente es una heroína!)",
  ui_story_5080_50800802_24_dialog_content = "No hay mucho que decir sobre lo que pasó después de eso.",
  ui_story_5080_50800802_25_dialog_content = "Gracias al pequeño Sinsa, aunque era joven, su mando era claro como el día. Más importante aún, tenía el coraje de un verdadero jefe.",
  ui_story_5080_50800802_26_dialog_content = "Bajo su liderazgo, comenzamos a lanzar operaciones de guerrilla y finalmente encontramos Lepidoz.",
  ui_story_5080_50800802_27_dialog_content = "No solo logramos sacudirnos el polvo, sino que incluso salvamos a un montón de nómadas del desierto perdidos en el proceso, y nuestros números comenzaron a crecer.",
  ui_story_5080_50800802_28_dialog_content = "Nuestro antiguo líder había muerto, pero la crisis no había terminado. Todos los demás estaban ocupados llorando nuestras pérdidas, ¿qué más podía hacer sino pensar en formas de animarlos?",
  ui_story_5080_50800802_29_dialog_content = "Eve y yo éramos forasteros. La jefa hizo todo lo posible por cuidarnos, y todos nos ayudaron mucho.",
  ui_story_5080_50800802_30_dialog_content = "¡Nadie quería ser el malo! Nadie quería tener que decir las duras verdades que la gente necesitaba escuchar, ¡así que lo hice todo! El jefe se había ido, no podíamos permitirnos perder a nadie más.",
  ui_story_5080_50800802_31_dialog_content = "No me importaba quién me llamara grosero o irrazonable, siempre y cuando todos sobrevivieran, sentía que estaba haciendo lo correcto por el jefe.",
  ui_story_5080_50800802_32_dialog_content = "Realmente no pensé en mucho más en ese momento.",
  ui_story_5080_50800802_33_dialog_content = "No seas modesto, no te queda bien, grandote.",
  ui_story_5080_50800802_34_dialog_content = "¡Basta de cursilerías! ¡Todo esto es irrelevante!",
  ui_story_5080_50800802_35_dialog_content = "Después de que el volcán se calmó, gradualmente eliminamos a todos los Eclipsites.",
  ui_story_5080_50800802_36_dialog_content = "Y después de que se enfrió la magma, todo lo que encontramos en lo que quedaba del campamento fue esa llave inglesa.",
  ui_story_5080_50800802_37_dialog_content = "El dragón malvado, el jefe, ese Eclipsite... no pudimos encontrar ni una sola pista de ninguno de ellos.",
  ui_story_5080_50800802_38_dialog_content = "Aunque nadie lo dijo en voz alta, todos asumimos que el jefe debió haber caído con esos monstruos, y que todos murieron en la lava.",
  ui_story_5080_50800802_39_dialog_content = "Hasta que el malvado dragón asomó su fea cabeza una vez más...",
  ui_story_5080_50800802_40_dialog_content = "Ahora ese Eclipsite también ha vuelto... Tal vez el antiguo jefe simplemente fue devorado por esas cosas en aquel entonces.",
  ui_story_5080_50800802_41_dialog_content = "¡De ninguna manera! ¡Ella era demasiado buena para eso!",
  ui_story_5080_50800802_42_dialog_content = "Bueno, al menos finalmente podemos vengarnos. Este lugar que nunca logramos encontrar antes resulta que había una ruta oculta aquí todo el tiempo...",
  ui_story_5080_50800802_43_dialog_content = "En el pasado, el volcán retumbaba y rugía de vez en cuando.",
  ui_story_5080_50800802_44_dialog_content = "Aunque todos sabían que eran los Eclipsites los que hacían todo ese ruido, no importaba cuántos de ellos matáramos, simplemente no podíamos acabar con todos. Siempre parecía que debía haber algún pasaje no descubierto por el que estaban entrando.",
  ui_story_5080_50800802_45_dialog_content = "Ja, bueno, finalmente lo encontramos. Pero aún tuvimos que volver a este maldito lugar para hacerlo.",
  ui_story_5080_50800802_46_dialog_content = "Yo... me gustaba seguirla bastante cuando era pequeño.",
  ui_story_5080_50800802_47_dialog_content = "Vi su poder. No era menos que la cuenta exagerada de Sinsa. No debería haber perdido contra ese dragón.",
  ui_story_5080_50800802_48_dialog_content = "Y... podía sentir que ella estaba soportando algo que aún no podía entender.",
  ui_story_5080_50800802_49_dialog_content = "Ella estaba ocultando desesperadamente algún secreto, reprimiendo alguna parte de sí misma.",
  ui_story_5080_50800802_50_dialog_content = "Ahora que lo mencionas, sí... el jefe y yo éramos de Illumina. Había escuchado su nombre más veces de las que puedo recordar.",
  ui_story_5080_50800802_51_dialog_content = "Pero cuando la conocí en realidad, ella era diferente de cómo la había imaginado.",
  ui_story_5080_50800802_52_dialog_content = "Pero siempre sentí que ella estaba ocultando su verdadero yo. No importa contra qué enemigo nos enfrentáramos, tenía la sensación de que siempre se estaba conteniendo.",
  ui_story_5080_50800802_53_dialog_content = "Solo parecía dejar salir lo que tenía dentro al final. Fue entonces cuando vi por primera vez desatado el lado salvaje de nuestro líder.",
  ui_story_5080_50800802_54_dialog_content = "Ella era más salvaje que Sinsa en un mal día.",
  ui_story_5080_50800802_55_dialog_content = "Es una comparación bastante extraña para hacer.",
  ui_story_5080_50800802_56_dialog_content = "Si incluso una mujer como ella podría perder contra <color=#FFB400>ese Eclipsite</color>, ¿qué oportunidad tenemos?",
  ui_story_5080_50800802_57_dialog_content = "Parece que el Rugiente Volcán está a punto de entrar en erupción, y el Darkover puede atacar de nuevo. ¿Realmente puede el Rediesel Wrench resistir a tales adversidades?",
  ui_story_5080_50800802_58_dialog_content = "¿Realmente tienes que preguntar?",
  ui_story_5080_50800802_59_dialog_content = "¡Solo tráelo!",
  ui_story_5080_50800802_60_dialog_content = "No importa contra qué tipo de Eclipsite estemos. ¡Los mandaré a volar con esta confiable llave mía!",
  ui_story_5080_50800802_61_dialog_content = "Si ese Eclipsite tiene el valor de enfrentarme de nuevo, ¡oh chico, no dejaré que se escape esta vez! ¡De ninguna manera!",
  ui_story_5080_50800802_62_dialog_content = "Caelestite Uno, Cría Dos, escucha.",
  ui_story_5080_50800802_63_dialog_content = "¿Qué pasa? ¿Por qué la repentina rutina de misterio y secretismo?",
  ui_story_5080_50800802_64_dialog_content = "Nuestra misión es... capturar a ese Eclipsite vivo, si es posible.",
  ui_story_5080_50800802_65_dialog_content = "Cuando llegue el momento, evita que Sinsa lo mate.",
  ui_story_5080_50800901_1_dialog_content = "¿Otro camino nuevo, eh? ¿Qué está pasando realmente aquí abajo?",
  ui_story_5080_50800901_2_dialog_content = "Se está abriendo. Parece que hemos llegado al camino verdadero.",
  ui_story_5080_50800901_3_dialog_content = "El mundo bajo el desierto es un lugar complejo para navegar, pero al mirar esta estructura... ¿podría haber sido parte de la pared del Corredor Ley?",
  ui_story_5080_50800901_4_dialog_content = "Cuando el volcán entró en erupción, la lava quemó todo a su paso, y los Eclipsites cavaron a través de estos agujeros para hacer un camino.",
  ui_story_5080_50800901_5_dialog_content = "Por la apariencia de estas paredes, definitivamente fueron excavadas, pero con herramientas, no con garras.",
  ui_story_5080_50800901_6_dialog_content = "Entonces, ¿esto no es obra de Eclipsite?",
  ui_story_5080_50800901_7_dialog_content = "La gente ha vivido en el desierto durante mucho tiempo. Quizás esto fue obra de la antigua civilización que desarrolló el Corredor de Leyline.",
  ui_story_5080_50800901_8_dialog_content = "Mira aquí... Las vibraciones intensas han agrietado la estratificación.",
  ui_story_5080_50800901_9_dialog_content = "Hay piedras cortadas aquí abajo. Este era un suelo, lo que significa que este lugar fue construido por alguien.",
  ui_story_5080_50800901_10_dialog_content = "¿Qué? ¿Justo al lado de un conducto volcánico subterráneo?!",
  ui_story_5080_50800901_11_dialog_content = "Eso explica las marcas de herramientas en las paredes, no estaban desarrollando la línea ley sin razón, estaban construyendo algo.",
  ui_story_5080_50800901_12_dialog_content = "Oye, ¿qué hace el soldado de Illumina cavando en la tierra en un momento como este?",
  ui_story_5080_50800901_13_dialog_content = "Espera, ella está desenterrando los restos más profundos en las grietas de estos materiales de construcción, buscando cualquier historia que puedan contar.",
  ui_story_5080_50800901_14_dialog_content = "Esta piedra tiene evidentes hendiduras de tres puntos, y hay ceniza carbonizada en las grietas.",
  ui_story_5080_50800901_15_dialog_content = "No hay duda. Alguien colocó una olla y cocinó algo aquí hace mucho tiempo.",
  ui_story_5080_50800901_16_dialog_content = "Desde aquí hasta donde entramos, es aproximadamente del tamaño de una habitación, este era un refugio subterráneo.",
  ui_story_5080_50800901_17_dialog_content = "Hace mucho tiempo, probablemente no había Eclipsites aquí, pero lo más probable es que fuera un refugio para un grupo de personas.",
  ui_story_5080_50800901_18_dialog_content = "Se escondieron aquí hasta que la erupción volcánica enterró todo.",
  ui_story_5080_50800901_19_dialog_content = "Muy impresionante. Con solo unas pocas palabras, has desenterrado las historias antiguas enterradas aquí.",
  ui_story_5080_50800901_20_dialog_content = "Nunca había visto algo así antes... No es de extrañar que te hayan hecho capitán de exploradores a una edad tan temprana.",
  ui_story_5080_50800901_21_dialog_content = "Sinsa, ¿alguna vez has oído hablar de gente viviendo bajo tierra aquí?",
  ui_story_5080_50800901_22_dialog_content = "Eve y yo también somos básicamente forasteros. No conocemos todas esas viejas historias.",
  ui_story_5080_50800901_23_dialog_content = "Roy y yo somos de Illumina, y aunque ciertamente ha estado por aquí, probablemente tampoco sabe sobre este tipo de cosas.",
  ui_story_5080_50800901_24_dialog_content = "¿Por qué me miras? Soy demasiado joven para saber sobre estas cosas. Además, si Sinsa no sabe sobre ello, ¿por qué yo sí?",
  ui_story_5080_50800901_25_dialog_content = "Si solía haber gente aquí, ¿cómo es que nunca has escuchado nada al respecto?",
  ui_story_5080_50800901_26_dialog_content = "¡Incluso yo no había oído hablar de eso! ¿Podría ser esto alguna reliquia súper antigua? ¡Quizás haya algún poder épico enterrado aquí, como un gigante de Lumina mega poderoso!?",
  ui_story_5080_50800901_27_dialog_content = "Mis disculpas... Debería haberme asegurado de que los niños estudiaran su historia, pero a nadie parecía importarle el pasado.",
  ui_story_5080_50800901_28_dialog_content = "Me hiciste organizar y enviar libros cada mes, y solo han estado acumulando polvo.",
  ui_story_5080_50800901_29_dialog_content = "Lo siento, Jeriah.",
  ui_story_5080_50800901_30_dialog_content = "¡Tenemos peces más grandes para freír ahora mismo!",
  ui_story_5080_50800901_31_dialog_content = "¡Correcto! ¡Un guerrero legendario como yo no tiene tiempo para historias antiguas!",
  ui_story_5080_50800901_32_dialog_content = "Ah... Lo esperaba, pero escucharlos a todos decirlo... Realmente no hay esperanza para este mundo.",
  ui_story_5080_50800901_33_dialog_content = "Todos realmente solo se preocupan por el presente en lugar de explorar lo que realmente significa la tierra bajo sus pies y el legado de sus predecesores.",
  ui_story_5080_50800901_34_dialog_content = "Señorita Jeriah, debes saber algo, ¿verdad? ¡Por favor cuéntanos!",
  ui_story_5080_50800901_35_dialog_content = "Mi investigación sobre el desierto no es exactamente extensa, pero cuando se trata de refugios, una cierta leyenda viene a la mente.",
  ui_story_5080_50800901_36_dialog_content = "También es la historia de origen de Rediesel Wrench.",
  ui_story_5080_50800901_37_dialog_content = "¿No fue porque nuestro antiguo jefe conquistó a los bandidos que se formó la Rediesel Wrench?",
  ui_story_5080_50800901_38_dialog_content = "Hace mucho tiempo, el desierto era hogar de nómadas y forajidos, viviendo sin ninguna apariencia real de orden.",
  ui_story_5080_50800901_39_dialog_content = "Quizás tenían miedo del mundo exterior, o estaban cansados de él, prefiriendo vivir en el duro entorno del desierto.",
  ui_story_5080_50800901_40_dialog_content = "Creían que este lugar era su libertad.",
  ui_story_5080_50800901_41_dialog_content = "Libertad...",
  ui_story_5080_50800901_42_dialog_content = "Un día, una joven noble de Lumopolis, perseguida por su familia, fue llevada al desierto por su sirvienta.",
  ui_story_5080_50800901_43_dialog_content = "La sirvienta quería llevarla a su ciudad natal, lejos de todo conflicto.",
  ui_story_5080_50800901_44_dialog_content = "La lucha de Lumópolis... Ya veo.",
  ui_story_5080_50800901_45_dialog_content = "Se envió un guardia de la ciudad tras ellos. Creía en el honor de un caballero por encima de todo lo demás.",
  ui_story_5080_50800901_46_dialog_content = "Curiosamente, un soldado de Illumina también se aventuró en el desierto en ese momento, buscando en los pueblos a desertores de Illumina.",
  ui_story_5080_50800901_47_dialog_content = "Estaba tras un desilusionado ingeniero de Illumina que había perdido su voluntad de servir.",
  ui_story_5080_50800901_48_dialog_content = "Un soldado Illumina desilusionado...",
  ui_story_5080_50800901_49_dialog_content = "Durante la persecución, el agente de Illumina, debido a una confusión, pensó erróneamente que el Guardia Lumo estaba tras la misma persona que él.",
  ui_story_5080_50800901_50_dialog_content = "La joven y su sirvienta, al encontrarse con el ingeniero, lo confundieron con un cazador de recompensas.",
  ui_story_5080_50800901_51_dialog_content = "Se temían mutuamente y comenzaron a perseguirse, pero estaban estrechamente conectados por la inconstancia del destino.",
  ui_story_5080_50800901_52_dialog_content = "Con la intervención del ingeniero, la mujer joven y su sirvienta lograron escapar del caballero.",
  ui_story_5080_50800901_53_dialog_content = "Y gracias al error del caballero, el agente perdió a su desertor, terminando rastreándolo solo hasta el pueblo de Saltstone.",
  ui_story_5080_50800901_54_dialog_content = "Parece que esta leyenda trata sobre tontos.",
  ui_story_5080_50800901_55_dialog_content = "De hecho, pero como eran tontos, nunca realmente se lastimaron el uno al otro.",
  ui_story_5080_50800901_56_dialog_content = "Todos se aferraron a sus creencias, teniendo claramente la oportunidad de atacar, pero sin querer hacerse daño mutuamente.",
  ui_story_5080_50800901_57_dialog_content = "Creo que me gustan historias como esta.",
  ui_story_5080_50800901_58_dialog_content = "En la última etapa de su viaje, se encontraron con una rara tormenta de arena. Todo en su camino fue devorado por las furiosas arenas.",
  ui_story_5080_50800901_59_dialog_content = "Justo a tiempo, la presa ayudó a los cazadores, y los cazadores abandonaron su persecución.",
  ui_story_5080_50800901_60_dialog_content = "Después de todo lo que había ocurrido, las misiones de los cazadores estaban muy atrasadas, y ellos mismos serían considerados desertores.",
  ui_story_5080_50800901_61_dialog_content = "Atrapados en el mismo barco, el apoyo mutuo finalmente los llevó a entenderse y confiar el uno en el otro.",
  ui_story_5080_50800901_62_dialog_content = "Hicieron un pacto para llegar juntos al pueblo de Saltstone, para establecerse y vivir en paz allí.",
  ui_story_5080_50800901_63_dialog_content = "¿Consiguieron su final de cuento de hadas?",
  ui_story_5080_50800901_64_dialog_content = "No. Cuando llegaron a la ciudad natal de la sirvienta, el supuesto oasis de la aldea de Saltstone, descubrieron que había sido destruido por una erupción volcánica.",
  ui_story_5080_50800901_65_dialog_content = "Los sobrevivientes también eran objetivo de los bandidos y estaban atrapados en un infierno viviente.",
  ui_story_5080_50800901_66_dialog_content = "El oasis no existía. Estaban condenados a nunca encontrar la paz.",
  ui_story_5080_50800901_67_dialog_content = "Los forasteros perdieron la esperanza, al darse cuenta de que este lugar no era diferente del mundo que habían dejado atrás...",
  ui_story_5080_50800901_68_dialog_content = "...",
  ui_story_5080_50800901_69_dialog_content = "Los supervivientes, liderados por el oráculo del pueblo, huyeron hacia las puertas del pueblo, justo a tiempo para encontrarse con estos forasteros.",
  ui_story_5080_50800901_70_dialog_content = "Aquellos que buscaban un refugio de repente se convirtieron en un refugio para otros.",
  ui_story_5080_50800901_71_dialog_content = "Desconcertados, ni el caballero resuelto ni el soldado intransigente podían comprender lo que se les pedía en ese momento.",
  ui_story_5080_50800901_72_dialog_content = "Ante una cuestión de vida o muerte, nadie esperaba que el ingeniero levantara la llave inglesa en su mano y se lanzara contra los bandidos.",
  ui_story_5080_50800901_73_dialog_content = "Su valiente acto inspiró a los demás, y finalmente los bandidos fueron expulsados.",
  ui_story_5080_50800901_74_dialog_content = "¡Qué historia tan heroica! Déjame adivinar, esa llave es la legendaria Rediesel Wrench, ¿verdad?",
  ui_story_5080_50800901_75_dialog_content = "No te adelantes, esta historia aún no ha terminado.",
  ui_story_5080_50800901_76_dialog_content = "Gracias a ese ingeniero, la gente encontró esperanza una vez más. Y así, se embarcaron una vez más, buscando un nuevo oasis en el desierto.",
  ui_story_5080_50800901_77_dialog_content = "En el camino, gradualmente absorbieron a más nómadas en el grupo, convirtiéndose en una fuerza formidable sin siquiera darse cuenta.",
  ui_story_5080_50800901_78_dialog_content = "Finalmente, encontraron un pequeño oasis rico en redesel y se establecieron allí.",
  ui_story_5080_50800901_79_dialog_content = "Esa es la leyenda que Attar... no, el líder anterior me contó.",
  ui_story_5080_50800901_80_dialog_content = "Demuestra que hace mucho tiempo, este desierto estaba habitado por Aurorianos.",
  ui_story_5080_50800901_81_dialog_content = "Esas personas, al igual que nosotros, estaban luchando por encontrar su propia forma de vida.",
  ui_story_5080_50800901_82_dialog_content = "Estos refugios subterráneos probablemente eran lugares para escapar de perseguidores o bandidos, ¿correcto?",
  ui_story_5080_50800901_83_dialog_content = "Pero si estas personas fueron engullidas por el volcán en erupción o abandonadas al descubrir el volcán en lo profundo de los túneles... No lo sé.",
  ui_story_5080_50800901_84_dialog_content = "Tsk, me estoy poniendo un poco celoso aquí... ¡No es justo! ¿Por qué el viejo jefe te contó todo eso a ti y no a nosotros?",
  ui_story_5080_50800901_85_dialog_content = "Bueno, eso es solo porque no mostraste el más mínimo interés.",
  ui_story_5080_50800901_86_dialog_content = "Estaba lleno de curiosidad y muy interesado en sus historias, siempre la molestaba para que me contara más.",
  ui_story_5080_50800901_87_dialog_content = "Pero al reflexionar, parece que cuanto más sabes, más te envuelves en una sensación de nada, una sensación de que el pasado eventualmente se desvanecerá...",
  ui_story_5080_50800901_88_dialog_content = "Sabes, Sinsa, eras solo un novato en aquel entonces, siempre ocupado cuidando a tu hermana.",
  ui_story_5080_50800901_89_dialog_content = "La vida no era todo sol y arcoíris en aquel entonces, estábamos buscando comida día tras día.",
  ui_story_5080_50800901_90_dialog_content = "También tenías las manos ocupadas, enseñando a Azure a conducir, ¿recuerdas?",
  ui_story_5080_50800901_91_dialog_content = "Simplemente estar vivo era increíble... Siempre pensé que vivir en el presente era lo único que importaba.",
  ui_story_5080_50800901_92_dialog_content = "En aquel entonces, no teníamos los medios para desenterrar el pasado.",
  ui_story_5080_50800901_93_dialog_content = "¡Pero oye, los tiempos han cambiado!",
  ui_story_5080_50800901_94_dialog_content = "Ahora, la vida en Rediesel Wrench es todo sol y arcoíris... ¡y estoy destinado a convertirme en la llave más afilada de la caja de herramientas!",
  ui_story_5080_50800901_95_dialog_content = "Solo espera, Sinsa. ¡Voy a estudiar duro cuando volvamos y me convertiré en un líder mejor que tú algún día!",
  ui_story_5080_50800901_96_dialog_content = "Pequeño punk... ¿No es nuestra cómoda vida gracias a mi sangre, sudor y lágrimas?",
  ui_story_5080_50800901_97_dialog_content = "¿Quieres decir que en la historia, esa persona que levantó su llave inglesa se convirtió en algún tipo de símbolo espiritual?",
  ui_story_5080_50800901_98_dialog_content = "Pero una llave de ingeniero de Illumina no es un arma, y nunca ha poseído dimensiones tan exageradas.",
  ui_story_5080_50800901_99_dialog_content = "La llave en las manos de Sinsa probablemente pesa una tonelada ahora, ¿verdad?",
  ui_story_5080_50800901_100_dialog_content = "Así es. Aparte de mí, no encontrarás a muchos que puedan simplemente girarlo en el aire como si no fuera nada.",
  ui_story_5080_50800901_101_dialog_content = "¿Qué tipo de ingeniero llevaría una llave inglesa así?",
  ui_story_5080_50800901_102_dialog_content = "Pajarito de presa, ¿estás diciendo que esta historia no es cierta?",
  ui_story_5080_50800901_103_dialog_content = "Esta leyenda puede haber sido inventada por tu líder para embellecer el pasado de Rediesel Wrench.",
  ui_story_5080_50800901_104_dialog_content = "Según los registros de Illumina, este desierto siempre ha estado plagado de bandidos, causando problemas e incitando a muchos a convertirse en desertores.",
  ui_story_5080_50800901_105_dialog_content = "Estas personas se autodenominaban la Banda Rediesel, y constantemente amenazaban a otros Aurorianos.",
  ui_story_5080_50800901_106_dialog_content = "Esa persona... primero convirtió a mi tía en una desertora, luego se unió a la Pandilla Rediesel después de huir aquí. Más tarde se convirtió en su líder.",
  ui_story_5080_50800901_107_dialog_content = "Obligó a los nómadas a unirse a ella para aumentar su poder, expandiendo lentamente su dominio sobre el desierto y convirtiéndolo en la Rediesel Wrench.",
  ui_story_5080_50800901_108_dialog_content = "Estas historias son solo invenciones que ella creó para presentar la historia de Rediesel Wrench en una luz positiva.",
  ui_story_5080_50800901_109_dialog_content = "¡Oye, pequeño mocoso de Illumina! ¿Acaso nadie te enseñó a no decir tonterías sobre alguien a quien la gente admira?",
  ui_story_5080_50800901_110_dialog_content = "Solo porque seamos amigos por ahora, ¡eso no significa que puedas hablar sin pensar!",
  ui_story_5080_50800901_111_dialog_content = "Espera, ¿por qué dirías eso, Capitán? Si, como dices, ella gobernaba el desierto, ¿por qué tendría que molestarse en embellecer el pasado?",
  ui_story_5080_50800901_112_dialog_content = "No puedo imaginar que el líder Sinsa y los demás crean en ser ese tipo de persona.",
  ui_story_5080_50800901_113_dialog_content = "¿Ella... realmente quería proteger a todos?",
  ui_story_5080_50800901_114_dialog_content = "Y así, ella quería protegerte de la verdad.",
  ui_story_5080_50800901_115_dialog_content = "...",
  ui_story_5080_50800901_116_dialog_content = "Tsk, así que puedes entender a las personas, ¿eh?",
  ui_story_5080_50800901_117_dialog_content = "Espera... ¿Es eso otro terremoto?",
  ui_story_5080_50800901_118_dialog_content = "No, ese es el sonido de la horda de Eclipsites.",
  ui_story_5080_50800901_119_dialog_content = "Mira aquí, Señorita Hormiga Soldado de Illumina. Así es como nos manejamos en Rediesel Wrench, este es el juramento que todos hicimos para mantener a nuestra familia segura!",
  ui_story_5080_50800901_120_dialog_content = "Ahora, presta atención, estamos a punto de mostrarte exactamente cómo se ve nuestra marca de valentía.",
  ui_story_5080_50801000_1_dialog_content = "Mira todas estas quemaduras... Te emocionaste demasiado.",
  ui_story_5080_50801000_2_dialog_content = "Je, un rasguño aquí y allá... ¡He visto peores!",
  ui_story_5080_50801000_3_dialog_content = "Oye, Roy, ¿ya es hora de comer? La pandilla debe estar muriéndose de hambre!",
  ui_story_5080_50801000_4_dialog_content = "¿Qué hay en el menú?",
  ui_story_5080_50801000_5_dialog_content = "¡Así es, hora de cenar, hora de cenar! Niños, preparen la olla!",
  ui_story_5080_50801000_6_dialog_content = "¡Vamos, Dawn! ¡Es hora de conseguirnos algunas delicias volcánicas!",
  ui_story_5080_50801000_7_dialog_content = "¿Qué haces?",
  ui_story_5080_50801000_8_dialog_content = "Trabaja duro, juega duro, pequeña dama de Illumina.",
  ui_story_5080_50801000_9_dialog_content = "No te veas tan sorprendido. Siempre son así. Nunca se relajan cuando se trata de comida.",
  ui_story_5080_50801000_10_dialog_content = "Si no te gusta su cocina exótica, también trajimos algo de comida.",
  ui_story_5080_50801000_11_dialog_content = "¡Pero, estamos en una misión ahora mismo!",
  ui_story_5080_50801000_12_dialog_content = "¿Cómo puedes simplemente comer así...? ¿Y si nos hacen una emboscada?",
  ui_story_5080_50801000_13_dialog_content = "Cría Dos, Caelestite Uno, Lancer Blanco, continúa tu misión.",
  ui_story_5080_50801000_14_dialog_content = "¡Sí, Capitán!",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5080_50801000_16_dialog_content = "Vaya... Mi error... Me salté el desayuno esta mañana...",
  ui_story_5080_50801000_17_dialog_content = "...",
  ui_story_5080_50801000_18_dialog_content = "Capitán, un experimentado Soldado Illumina solía decirnos, \"¡A comer! Un vientre lleno te da la fuerza para luchar hasta la próxima comida!\"",
  ui_story_5080_50801000_19_dialog_content = "Juró por esta regla, y todos estuvieron de acuerdo.",
  ui_story_5080_50801000_20_dialog_content = "Zeta y Vice han estado ocupados luchando y viajando desde que se levantaron...",
  ui_story_5080_50801000_21_dialog_content = "Esos viejos soldados de Illumina saben todo sobre luchar con el estómago vacío.",
  ui_story_5080_50801000_22_dialog_content = "Sin embargo, aún perseveraron.",
  ui_story_5080_50801000_23_dialog_content = "Por eso esperan que la generación más joven pueda comer mejor de lo que ellos lo hicieron.",
  ui_story_5080_50801000_24_dialog_content = "Supongo que no podemos seguir adelante sin reponer nuestra energía. Para asegurar que se complete la misión, te daré tiempo para comer.",
  ui_story_5080_50801000_25_dialog_content = "Haré guardia. No todos pueden permitirse relajarse...",
  ui_story_5080_50801000_26_dialog_content = "¡Capitán, al menos come algunas de estas raciones comprimidas! ¡Capitán...!",
  ui_story_5080_50801000_27_dialog_content = "Déjala ser, solo quiere asegurarse de que esta misión se ejecute a la perfección.",
  ui_story_5080_50801000_28_dialog_content = "¡Hemos vuelto—Oye, empezaste sin nosotros!",
  ui_story_5080_50801000_29_dialog_content = "¡Los héroes se tratan de eficiencia! ¡Voy a hacer guardia!",
  ui_story_5080_50801000_30_dialog_content = "... La velocidad con la que comes es encomiable. Con entrenamiento, podrías convertirte en un buen soldado.",
  ui_story_5080_50801000_31_dialog_content = "No quiero ser un soldado de Illumina. ¡Estoy destinado a salvar el mundo!",
  ui_story_5080_50801000_32_dialog_content = "¡Prueba esto! ¡Esta cecina de insecto asado está deliciosa! Lo traje especialmente para ti.",
  ui_story_5080_50801000_33_dialog_content = "Gracias... Chica Piruleta.",
  ui_story_5080_50801000_34_dialog_content = "¡Soy el Salvador del Mundo, no algún personaje secundario!",
  ui_story_5080_50801000_35_dialog_content = "Eres genial y todo, pero tu gusto necesita trabajo! Debe ser porque fuiste criado por el Rey Demonio, ¿verdad?",
  ui_story_5080_50801000_36_dialog_content = "¡Duro golpe, Salvadora del Mundo, Hermana Archienemiga Perdida hace mucho tiempo!",
  ui_story_5080_50801000_37_dialog_content = "¿Hermana?",
  ui_story_5080_50801000_38_dialog_content = "¡Sí! ¡Ahora somos Hermanas Guerreras! No te preocupes, encontraré una forma de liberarte de esas cadenas mentales tuyas!",
  ui_story_5080_50801000_39_dialog_content = "¿Eh? ¿Estás sonriendo? Es la primera vez que te veo sonreír... ¡Debe ser el poder de la familia, verdad?!",
  ui_story_5080_50801000_40_dialog_content = "No le hagas caso; a ella simplemente le gusta jugar a la fantasía, inventar historias, y así sucesivamente.",
  ui_story_5080_50801000_41_dialog_content = "Hermanas... Hmm...",
  ui_story_5080_50801000_42_dialog_content = "Parece que te han recordado algo. ¿Tienes una hermana, por casualidad?",
  ui_story_5080_50801000_43_dialog_content = "Sí... ella es muy inteligente, más fuerte que yo, y... simplemente adorable.",
  ui_story_5080_50801000_44_dialog_content = "Una vez que termine sus estudios, se convertirá en una soldado ejemplar.",
  ui_story_5080_50801000_45_dialog_content = "Estoy orgulloso de ella.",
  ui_story_5080_50801000_46_dialog_content = "¿Qué...? Uf...",
  ui_story_5080_50801000_47_dialog_content = "Zeta, no pareces convencido.",
  ui_story_5080_50801000_48_dialog_content = "Ella me está poniendo celoso... ¡Quiero decir! ¡No celoso! Solo...",
  ui_story_5080_50801000_49_dialog_content = "Tener una hermana como tú, tu hermanita debe estar muy feliz.",
  ui_story_5080_50801000_50_dialog_content = "Porque Eagleshot es mucho más agradable que esa bruja.",
  ui_story_5080_50801000_51_dialog_content = "No, todavía estoy muy lejos de ser lo suficientemente bueno.",
  ui_story_5080_50801000_52_dialog_content = "Seguiré intentando... intentando... no causar más problemas a mi familia.",
  ui_story_5080_50801000_53_dialog_content = "¡Oh, la, la, la!",
  ui_story_5080_50801000_54_dialog_content = "¿Qué pasa con la serenata repentina? ¡Ni siquiera puedo escucharme pensar!",
  ui_story_5080_50801000_55_dialog_content = "¿No has oído? Barbara le dijo que tiene más potencial que tú, así que ha estado entrenando como loco últimamente.",
  ui_story_5080_50801000_56_dialog_content = "¡¿Qué?!",
  ui_story_5080_50801000_57_dialog_content = "\"El primer tenor de Rediesel, más emocionante que Sinsa\"—palabras de Barbara.",
  ui_story_5080_50801000_58_dialog_content = "Así que está entrenando como loco, preparándose para encantar a todos con su estilo vocal.",
  ui_story_5080_50801000_59_dialog_content = "Vaya, entonces supongo que también tengo que practicar. Les prometí que me uniría a la banda.",
  ui_story_5080_50801000_60_dialog_content = "¿Dónde están esas baquetas... No esto... tampoco eso... ¡Bingo!",
  ui_story_5080_50801000_61_dialog_content = "¡Bien, estoy aquí para seguir el ritmo. ¡Vamos a ello!",
  ui_story_5080_50801000_62_dialog_content = "Estas personas...",
  ui_story_5080_50801000_63_dialog_content = "Sube el volumen, Fleur! ¡Pon tu corazón y alma en esas baquetas!",
  ui_story_5080_50801000_64_dialog_content = "¿Estás en armonía conmigo? ¿Ya te has sincronizado con mi voz?",
  ui_story_5080_50801000_65_dialog_content = "A menos que bajes la voz, incluso los Eclipsites van a alcanzar tu voz.",
  ui_story_5080_50801000_66_dialog_content = "¡No golpees las paredes, Fleur! ¡Ten cuidado de no alertar a los Eclipsites!",
  ui_story_5080_50801000_67_dialog_content = "Es bueno que Sinsa tenga algo de sentido común, Rediesel Wrench...",
  ui_story_5080_50801000_68_dialog_content = "Toma la llave inglesa. Si quieres practicar, ¡empieza a golpear con esto! Adelante, noqueate a ti mismo.",
  ui_story_5080_50801000_69_dialog_content = "¿No tienes miedo de atraer a los Eclipsites?",
  ui_story_5080_50801000_70_dialog_content = "Eso realmente no es un gran problema, ¿verdad? De todos modos, estamos ansiosos por encontrarlos. ¡Sube el tono, más alto! ¡Más alto!",
  ui_story_5080_50801000_71_dialog_content = "Ah... Verdaderamente incorregible.",
  ui_story_5080_50801000_72_dialog_content = "Viviendo en este vasto desierto, nunca han desarrollado un espíritu de investigación. Todo lo que hacen es perder el tiempo todos los días...",
  ui_story_5080_50801000_73_dialog_content = "Pero Jeriah, ¿qué es exactamente el espíritu de investigación?",
  ui_story_5080_50801000_74_dialog_content = "Pequeña Caelestite, ¿también estás empezando a tener dudas?",
  ui_story_5080_50801000_75_dialog_content = "No, solo pienso que... aunque viven en un ambiente tan duro, nunca escuchas a Sinsa y a los demás quejarse.",
  ui_story_5080_50801000_76_dialog_content = "Siempre están tratando de encontrar la alegría en la vida, y parecen ser bastante buenos en ello.",
  ui_story_5080_50801000_77_dialog_content = "Siempre tengo la sensación de que ya están llenos del espíritu de investigación, cuando se trata de explorar sus propias vidas.",
  ui_story_5080_50801000_78_dialog_content = "Sí, señorita Jeriah. Sabes tanto, pero parece que eres un poco demasiado negativa sobre la vida en general...",
  ui_story_5080_50801000_79_dialog_content = "Sin ofender, por supuesto, pero... ¿es realmente así como quieres ser?",
  ui_story_5080_50801000_80_dialog_content = "Viniendo de un soldado de Illumina como Vice, no estoy del todo seguro de cómo responder.",
  ui_story_5080_50801000_81_dialog_content = "Quizás creas que las personas de Illumina no tienen derecho a dar lecciones a otros sobre la vida y la libertad.",
  ui_story_5080_50801000_82_dialog_content = "Pero crecí allí y lo sé muy bien: el propósito de Illumina es servir como un escudo, para proteger a todos los que están detrás de nosotros.",
  ui_story_5080_50801000_83_dialog_content = "Podemos tener que hacer sacrificios, pero sé que las personas detrás de ese escudo pueden vivir felices.",
  ui_story_5080_50801000_84_dialog_content = "Las sonrisas en sus rostros son lo que me esfuerzo por proteger.",
  ui_story_5080_50801000_85_dialog_content = "Me alegra verlos haciendo todo lo posible para vivir sus vidas. Verlos tan libres es suficiente para mí.",
  ui_story_5080_50801000_86_dialog_content = "¿El significado de... protección...?!",
  ui_story_5080_50801000_87_dialog_content = "Entonces, todos ustedes tienen diferentes puntos de vista sobre la vida.",
  ui_story_5080_50801000_88_dialog_content = "¿Vivir para los demás? En mi opinión, no es exactamente lo que yo llamaría ser completamente libre, pero aún así es admirable.",
  ui_story_5080_50801000_89_dialog_content = "Hmm, ¿cómo debería entender esto? Se supone que debes explorar la vida en tus propios términos, pero estás tan estrechamente conectado con los demás...",
  ui_story_5080_50801000_90_dialog_content = "Todavía creo que los vínculos que existen entre las personas no pueden ser cortados.",
  ui_story_5080_50801000_91_dialog_content = "Incluso tú, Jeriah, no puedes borrar los lazos que has formado con nosotros... incluso si no quieres convertirte en un tonto despreocupado.",
  ui_story_5080_50801000_92_dialog_content = "... Correcto, la casa es ahora un lienzo de garabatos, una montaña de regalos y libros para los niños.",
  ui_story_5080_50801000_93_dialog_content = "No importa cuán sigiloso intente ser, esos niños aún logran atraparme, e incluso han sacado mi auto para dar un paseo por diversión.",
  ui_story_5080_50801000_94_dialog_content = "Lo abollaron bastante bien, ¡pero lo arreglé muy bien!",
  ui_story_5080_50801000_95_dialog_content = "También algunos parches bastante únicos.",
  ui_story_5080_50801000_96_dialog_content = "Después de todo esto, Jeriah, ¿todavía crees que estás completamente solo?",
  ui_story_5080_50801000_97_dialog_content = "¿Qué es esto, pequeña Caelestite? ¿Estás realmente tan preocupada por mis conexiones sociales? ¿Estás tan preocupada por mí?",
  ui_story_5080_50801000_98_dialog_content = "Incluso si intento mezclarme con estas personas, no disminuirá mi ansia de viajar.",
  ui_story_5080_50801000_99_dialog_content = "¡Está bien, ese es el ritmo!",
  ui_story_5080_50801000_100_dialog_content = "Puedo sentir tu fuego, siento tu vibra, ¡ahora vamos a cantarlo a todo pulmón!",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>Bajo el mando de Sinsa, Rediesel Wrench canta su canción como locos.</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>Es un coro totalmente discordante, pero todos lo dan todo, nunca piensan en detenerse, es su propio tipo especial de armonía.</color>",
  ui_story_5080_50801000_103_dialog_content = "Sus personalidades son simplemente demasiado distintas y prominentes, no son del tipo que se mezclan.",
  ui_story_5080_50801000_104_dialog_content = "Sin embargo, este variopinto grupo de personajes únicos se ha convertido en familia.",
  ui_story_5080_50801000_105_dialog_content = "Sigue cantando, solo observa la olla de sopa.",
  ui_story_5080_50801000_106_dialog_content = "Oh, Jeriah, vi algo increíble que tenían allí llamado olla caliente cuando estaba en Longzhou.",
  ui_story_5080_50801000_107_dialog_content = "Preparas un caldo picante, agregas la comida que quieras y simplemente la sacas cuando quieras comerla.",
  ui_story_5080_50801000_108_dialog_content = "No importa lo que eches en esa olla picante, los sabores no se mezclan.",
  ui_story_5080_50801000_109_dialog_content = "Todos los que viven en el desierto ahora son como una olla caliente.",
  ui_story_5080_50801000_110_dialog_content = "Rediesel es increíble. El desierto es tan vasto, con suficiente espacio para que todos se estiren y exploren el viaje de su vida...",
  ui_story_5080_50801000_111_dialog_content = "¿Olla caliente... dices?",
  ui_story_5080_50801000_112_dialog_content = "Jeriah, escucha, ¿oyes eso? Ese halcón está cantando.",
  ui_story_5080_50801000_113_dialog_content = "Es solo el grito de un pájaro, nada más.",
  ui_story_5080_50801000_114_dialog_content = "Jajaja... Jeriah, ¿cómo sabes que no está cantando una canción para su propio viaje?",
  ui_story_5080_50801000_115_dialog_content = "... ¿Por qué me contaste esa leyenda?",
  ui_story_5080_50801000_116_dialog_content = "¿No es increíble? Los extraños nacidos en Rediesel, Lumopolis e Illumina eventualmente se convierten en una gran familia a pesar de las diferencias de todos.",
  ui_story_5080_50801000_117_dialog_content = "Aunque viven en este mundo de calamidades interminables, las almas solitarias aún están dispuestas a compartir sus emociones.",
  ui_story_5080_50801000_118_dialog_content = "Algunos están dispuestos a levantar una llave para proteger a otros y convertirse en líderes. Otros están dispuestos a seguir a esas personas y trabajar juntos.",
  ui_story_5080_50801000_119_dialog_content = "El desierto se ha convertido en nuestro hogar.",
  ui_story_5080_50801000_120_dialog_content = "Simplemente pasando por el cielo en su viaje, se agrupan en bandadas, encontrando su propio oasis.",
  ui_story_5080_50801000_121_dialog_content = "Jeriah, esfuerza por explorar la amplitud de tu propia vida, vuela alto y canta con todo tu corazón!",
  ui_story_5080_50801000_122_dialog_content = "¿Cómo puedes seguir vagando para siempre? Ya hay un lugar para ti aquí—",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>El sonido de la guitarra, ardiendo como el sol, atraviesa el calor del desierto, calmando el suelo tembloroso.</color>",
  ui_story_5080_50801101_2_dialog_content = "¡Adelante, adelante! ¡Mi espíritu nunca morirá!",
  ui_story_5080_50801101_3_dialog_content = "Hace mucho calor aquí afuera, y ella sigue practicando nuevas melodías. Bien por ella.",
  ui_story_5080_50801101_4_dialog_content = "¡No seré superado! Tiny One, ¡es nuestro turno!",
  ui_story_5080_50801101_5_dialog_content = "El escenario está listo. Tengo cosas que hacer, tú continúa.",
  ui_story_5080_50801101_6_dialog_content = "¿Hola? Este es el Rediesel Wrench...",
  ui_story_5080_50801101_7_dialog_content = "Bopper, Jona me está apurando para que vuelva. ¿Qué está pasando?",
  ui_story_5080_50801101_8_dialog_content = "¡Cuidado! ¡El ídolo siempre brillante está aquí! ¡La Dulce Diesel, Barbara!",
  ui_story_5080_50801101_9_dialog_content = "¿Hola? Este es Rediesel Wrench... Azure, ¿eres tú?",
  ui_story_5080_50801101_10_dialog_content = "Vaya, está zumbando por allá.",
  ui_story_5080_50801101_11_dialog_content = "¡El sol feroz está ardiendo! ¡El sol feroz sigue enfurecido!!!",
  ui_story_5080_50801101_12_dialog_content = "¿Hola? Este es el Rediesel Wrench...",
  ui_story_5080_50801101_13_dialog_content = "¿Hola? No puedo escuchar nada. Olvídalo, simplemente esperaré a que hermana regrese.",
  ui_story_5080_50801101_14_dialog_content = "Oye, Maggie, ¿colocaste correctamente esas minas terrestres?",
  ui_story_5080_50801101_15_dialog_content = "Hace tanto calor, aunque... Lo tengo, lo tengo, ¡lo haré ahora!",
  ui_story_5080_50801101_16_dialog_content = "¡Cubramos todo el perímetro del campamento antes del atardecer!",
  ui_story_5080_50801101_17_dialog_content = "¿Realmente necesitamos todas estas trampas?",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>Los temblores del desierto continúan. El volcán distante ruge, desahogando su ira.</color>",
  ui_story_5080_50801101_19_dialog_content = "Los líderes se han ido hace mucho tiempo...",
  ui_story_5080_50801101_20_dialog_content = "No hay respuesta a las comunicaciones.",
  ui_story_5080_50801101_21_dialog_content = "Tiny One, Fleur está fuera ahora mismo, ven a ayudarme a arreglar el camión.",
  ui_story_5080_50801101_22_dialog_content = "Hmph, ¿es eso un desafío? ¿Todavía no admitirás que soy mejor?",
  ui_story_5080_50801101_23_dialog_content = "¡¿De qué estás hablando?!",
  ui_story_5080_50801101_24_dialog_content = "¿Deberíamos partir a bordo de Lepidoz?",
  ui_story_5080_50801101_25_dialog_content = "Oye, Bopper, ¿era Azure en la línea?",
  ui_story_5080_50801101_26_dialog_content = "No lo sé...",
  ui_story_5080_50801101_27_dialog_content = "¿Cómo puedes no saber si tomaste la llamada?",
  ui_story_5080_50801101_28_dialog_content = "Vuelve a salir de patrulla, y luego...",
  ui_story_5080_50801101_29_dialog_content = "Olvídalo, tiene que ser Azure. ¿Quién más podría ser?",
  ui_story_5080_50801101_30_dialog_content = "No puedo perder esta rara oportunidad. Tengo que invitarla a tomar algo después de todo esto.",
  ui_story_5080_50801101_31_dialog_content = "... Escúchame.",
  ui_story_5080_50801101_32_dialog_content = "Estamos aquí, justo al lado de la boca del volcán.",
  ui_story_5080_50801101_33_dialog_content = "Todo lo que tenemos que hacer es saltar aquí abajo, y estaremos dentro del volcán—",
  ui_story_5080_50801101_34_dialog_content = "El nivel de actividad de este volcán... Eagle Hunter One, ¡activa el modo de detección!",
  ui_story_5080_50801101_35_dialog_content = "... Como se esperaba, este volcán es extremadamente activo.",
  ui_story_5080_50801101_36_dialog_content = "¿Por qué aún no ha llegado a la erupción?",
  ui_story_5080_50801101_37_dialog_content = "Esto no es un volcán dormido despertando. Siempre ha estado tan activo.",
  ui_story_5080_50801101_38_dialog_content = "No ha hecho erupción en todos estos años.",
  ui_story_5080_50801101_39_dialog_content = "Extraño...",
  ui_story_5080_50801101_40_dialog_content = "¡Guau, es esto real? ¡Los Eclipsites están saliendo de la boca del volcán!",
  ui_story_5080_50801101_41_dialog_content = "Esos Eclipsites... su energía de lava debe venir de aquí.",
  ui_story_5080_50801101_42_dialog_content = "¡Hora de ir! ¡Salta!",
  ui_story_5080_50801101_43_dialog_content = "Vice... Carleen... ¡Espera por mí! ¡Es tan alto!",
  ui_story_5080_50801102_1_dialog_content = "Los Eclipsites cuentan como criaturas vivientes, ¿verdad?",
  ui_story_5080_50801102_2_dialog_content = "¿Cómo es posible que sean capaces de vivir en la boca de este volcán, no solo utilizando la energía de la lava sino también sin tenerle miedo?",
  ui_story_5080_50801102_3_dialog_content = "Fleur, ¿nos haces los cálculos, no? ¿Cómo hacemos volar la boca de este volcán por los aires?",
  ui_story_5080_50801102_4_dialog_content = "Si los Eclipsites no tienen miedo de la lava, esta podría ser la única forma de evitar que regresen.",
  ui_story_5080_50801102_5_dialog_content = "Eso no funcionará. Esa dama tiene razón, este es un volcán activo. Cualquier explosión imprudente podría desencadenar una erupción.",
  ui_story_5080_50801102_6_dialog_content = "Los temblores no cesan. Los Eclipsites van a seguir saliendo de las profundidades del volcán...",
  ui_story_5080_50801102_7_dialog_content = "No sabemos qué está pasando afuera, así que necesitamos hacer esto rápido.",
  ui_story_5080_50801102_8_dialog_content = "¿Por qué este volcán ha estado tan activo pero aparentemente inactivo durante tanto tiempo?",
  ui_story_5080_50801102_9_dialog_content = "¿Cuál podría ser la razón?",
  ui_story_5080_50801102_10_dialog_content = "Es probable que la furia del volcán se deba a la energía inestable de la línea ley.",
  ui_story_5080_50801102_11_dialog_content = "Si podemos encontrar la causa, tal vez podamos resolver esta crisis.",
  ui_story_5080_50801102_12_dialog_content = "No importa qué, tenemos que movernos rápido.",
  ui_story_5080_50801102_13_dialog_content = "Si este temblor continúa, incluso los eclipsites se asustarán hasta la superficie.",
  ui_story_5080_50801102_14_dialog_content = "Los Rediesels pueden ser duros de roer, pero ¿qué pasa con los aldeanos?",
  ui_story_5080_50801102_15_dialog_content = "Muy cierto. ¿Algún pensamiento, Sinsa?",
  ui_story_5080_50801102_16_dialog_content = "No queda otra opción. Si estos tipos vienen desde adentro, tendré que entrar.",
  ui_story_5080_50801102_17_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5080_50801102_18_dialog_content = "¿Te sientes bien? Estamos hablando de un volcán, Sinsa.",
  ui_story_5080_50801102_19_dialog_content = "Me siento tan bien como la lluvia, muchas gracias. Por eso no puedo simplemente ignorar esto.",
  ui_story_5080_50801102_20_dialog_content = "Estoy harto de su retumbar. Ya sea por rencillas viejas o nuevas, voy a ajustar cuentas de una vez por todas.",
  ui_story_5080_50801102_21_dialog_content = "¿Por qué... te estás esforzando tanto?",
  ui_story_5080_50801102_22_dialog_content = "¡Ja! Es gracioso escuchar eso de ti.",
  ui_story_5080_50801102_23_dialog_content = "Después de todo, los de Rediesel Wrench son conocidos como desertores, y tú vienes de un trasfondo similar.",
  ui_story_5080_50801102_24_dialog_content = "Todos han sobrevivido tanto tiempo saqueando a los demás, ¿verdad? Simplemente yendo con la corriente, viviendo día a día.",
  ui_story_5080_50801102_25_dialog_content = "¿Por qué arriesgarías tu vida ahora?",
  ui_story_5080_50801102_26_dialog_content = "Está bien, ahora es mi turno de interrogarte. ¿Qué estabas haciendo en Illumina? ¿Por qué viajar hasta este volcán?",
  ui_story_5080_50801102_27_dialog_content = "¡Soy el capitán del Escuadrón Eagleeye! He liderado a mi equipo en más de cuarenta operaciones especiales de alto riesgo.",
  ui_story_5080_50801102_28_dialog_content = "Sin mí, los demás habrían enfrentado un peligro aún mayor.",
  ui_story_5080_50801102_29_dialog_content = "Vine por la gloria. No soy nada como ustedes.",
  ui_story_5080_50801102_30_dialog_content = "Sabes, Fleur y ese otro anciano nacieron ambos en Gannon City.",
  ui_story_5080_50801102_31_dialog_content = "No obtuvieron ninguna gloria allí, en cambio, tuvieron que escapar al desierto porque sentían que se estaban asfixiando.",
  ui_story_5080_50801102_32_dialog_content = "¿Qué es la gloria, de todos modos?",
  ui_story_5080_50801102_33_dialog_content = "La gloria es—",
  ui_story_5080_50801102_34_dialog_content = "Señorita Illumina, ilumíname, ¿realmente comprendes el significado de \"sacrificio\"?",
  ui_story_5080_50801102_35_dialog_content = "¡Por Illumina, por la liberación de todos los Aurorianos, sin importar el costo!",
  ui_story_5080_50801102_36_dialog_content = "¡Estoy listo para sacrificar todo por esa gran causa!",
  ui_story_5080_50801102_37_dialog_content = "...",
  ui_story_5080_50801102_38_dialog_content = "¿Por qué me miras así?",
  ui_story_5080_50801102_39_dialog_content = "¿Es así como te convences?",
  ui_story_5080_50801102_40_dialog_content = "No importa. Es inútil hablar contigo sobre esto ahora mismo.",
  ui_story_5080_50801102_41_dialog_content = "Roy, ella todavía vive en un mundo de sueños.",
  ui_story_5080_50801102_42_dialog_content = "¡Tú!",
  ui_story_5080_50801102_43_dialog_content = "Disculpe, tengo que limpiar un montón de insectos que infestan mi casa. No se interpongan en mi camino.",
  ui_story_5080_50801102_44_dialog_content = "¡Oye, Sinsa, quién dijo que podrías limpiar solo? ¡No te olvides de nosotros!",
  ui_story_5080_50801102_45_dialog_content = "Chicos, no se aglomeren todos. Es peligroso.",
  ui_story_5080_50801102_46_dialog_content = "Eres uno para hablar, tonto!",
  ui_story_5080_50801102_47_dialog_content = "¿Saltar juntos a un volcán? Esto parece una elección poco sabia.",
  ui_story_5080_50801102_48_dialog_content = "Listos, todos... ¡Whoa!",
  ui_story_5080_50801102_49_dialog_content = "¡Es un terremoto! ¡Ten cuidado!",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>De la nada, un terremoto golpea, y aquellos de nosotros que estábamos cerca del borde del volcán caemos en él.</color>",
  ui_story_5080_50801102_51_dialog_content = "¡Sinsa!",
  ui_story_5080_50801102_52_dialog_content = "¡Eve! ¡Todos! ¡Estoy llegando!",
  ui_story_5080_50801102_53_dialog_content = "¡Ni siquiera pienses en quitarme a nadie más!",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>Sinsa desciende como una bola de cañón, utilizando su monstruosa fuerza para lanzar a todos a un lugar seguro.</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>Mientras lo veo acercarse, cada vez más y más cerca—no sé por qué, pero de repente me siento tranquila.</color>",
  ui_story_5080_50801102_56_dialog_content = "¡Toma mi mano, PlayerName!",
  ui_story_5080_50801102_57_dialog_content = "Espera, Sinsa, ¡eso es lava fundida debajo de nosotros! ¿¡Qué estás haciendo!?",
  ui_story_5080_50801102_58_dialog_content = "¡A quién le importa! ¡Solo súbeme allí!",
  ui_story_5080_50801102_59_dialog_content = "¡No te atrevas a pensar en morirte, niño!",
  ui_story_5080_50801102_60_dialog_content = "<size=50>Sinsa¡¡¡</size>",
  ui_story_5080_50801201_1_dialog_content = "¡Misión cumplida! ¡Las contribuciones de Eagleeye fueron significativas!",
  ui_story_5080_50801201_2_dialog_content = "Gracias por tu arduo trabajo, Rachel. Illumina recordará tu sacrificio.",
  ui_story_5080_50801201_3_dialog_content = "Adelante, soldado. ¡El Gran Mariscal te otorgará personalmente la Medalla de Honor!",
  ui_story_5080_50801201_4_dialog_content = "En cuanto a la operación de rescate, hicimos todo lo que pudimos... Lo siento, Rachel, esto es todo lo que tengo para ti. Gracias por tus esfuerzos.",
  ui_story_5080_50801201_5_dialog_content = "¡Aghhh...!",
  ui_story_5080_50801201_6_dialog_content = "Tan pesado...",
  ui_story_5080_50801201_7_dialog_content = "¿Ah?",
  ui_story_5080_50801201_8_dialog_content = "Están justo aquí... en mis manos... tan pesados...",
  ui_story_5080_50801201_9_dialog_content = "Por mi bien... todos mis compañeros de equipo... todos se sacrificaron...",
  ui_story_5080_50801201_10_dialog_content = "¡Alguien ven aquí! ¡Está a punto de desmayarse!",
  ui_story_5080_50801201_11_dialog_content = "Me duele el pecho... No estoy herido, pero el dolor no se detiene... Tía...",
  ui_story_5080_50801201_12_dialog_content = "Gracias, Capitán... Gracias por darlo todo para completar la misión.",
  ui_story_5080_50801201_13_dialog_content = "Ahora, nuestros niños ya no serán recordados como \"fracasos\".",
  ui_story_5080_50801201_14_dialog_content = "Finalmente pueden descansar como héroes.",
  ui_story_5080_50801201_15_dialog_content = "No...",
  ui_story_5080_50801201_16_dialog_content = "Estoy tan triste, tía... Completé la misión, pero... duele tanto...",
  ui_story_5080_50801201_17_dialog_content = "Rachel, mi niño, no llores... no llores...",
  ui_story_5080_50801201_18_dialog_content = "Todo es mi culpa. ¿Por qué todos los adultos me agradecen cuando todo fue por mi error...?",
  ui_story_5080_50801201_19_dialog_content = "Salvaste su último hilo de dignidad.",
  ui_story_5080_50801201_20_dialog_content = "Pero deberían haber regresado sanos y salvos y estar con sus padres.",
  ui_story_5080_50801201_21_dialog_content = "Rachel, mírame. ¿Realmente podrías soportar esa responsabilidad? ¿Convertir a todos en desertores solo para llevarlos a casa a salvo?",
  ui_story_5080_50801201_22_dialog_content = "Yo... no sé... no lo sé...",
  ui_story_5080_50801201_23_dialog_content = "¿Qué está pasando, Rachel? Esta es tu sexta misión fallida.",
  ui_story_5080_50801201_24_dialog_content = "Has descansado lo suficiente, entonces, ¿por qué está sucediendo esto de nuevo?",
  ui_story_5080_50801201_25_dialog_content = "Lo siento, todo es mi culpa. Por favor no culpes a los demás.",
  ui_story_5080_50801201_26_dialog_content = "Los demás se han quejado todos de ti. Ni siquiera puedes recordar sus nombres o caras... ¿Qué pasó?",
  ui_story_5080_50801201_27_dialog_content = "Yo... lo siento... lo siento...",
  ui_story_5080_50801201_28_dialog_content = "Deberías tomarte un descanso de las misiones por ahora. Organizaré un tiempo libre para ti.",
  ui_story_5080_50801201_29_dialog_content = "Lo siento mucho... Comandante...",
  ui_story_5080_50801201_30_dialog_content = "Ala Gris... Su nombre era Louis. Nació en el Norte y siempre soñó con explorar el desierto.",
  ui_story_5080_50801201_31_dialog_content = "Una vez dijo que quería tallar una flauta de una rama de los árboles blancos de Northland para regalar a White Goose.",
  ui_story_5080_50801201_32_dialog_content = "Ganso Blanco... Su nombre era Merry. Siempre hablaba de aprender a tocar un instrumento, pero nunca llegó a hacerlo.",
  ui_story_5080_50801201_33_dialog_content = "Ella prometió jugar para mí en mi cumpleaños, pero lo fue posponiendo, año tras año.",
  ui_story_5080_50801201_34_dialog_content = "Y luego están el Cernícalo Rojo y el Búho Verde...",
  ui_story_5080_50801201_35_dialog_content = "Ahora se han convertido en este collar, colgando de mi cuello para siempre.",
  ui_story_5080_50801201_36_dialog_content = "\"¿Realmente serías capaz de soportar esa responsabilidad? ¿Convertir a todos en desertores solo para llevarlos a casa a salvo?\"",
  ui_story_5080_50801201_37_dialog_content = "¡PlayerName!",
  ui_story_5080_50801201_38_dialog_content = "...!",
  ui_story_5080_50801201_39_dialog_content = "Vice, ¡estoy aquí! Capitán, Fleur, Zeta, ¿están todos bien?",
  ui_story_5080_50801201_40_dialog_content = "Estoy bien.",
  ui_story_5080_50801201_41_dialog_content = "Genial, PlayerName también está seguro.",
  ui_story_5080_50801201_42_dialog_content = "Parece que la boca del volcán se derrumbó. ¿Dónde están los demás?",
  ui_story_5080_50801201_43_dialog_content = "Parece que no estamos en el mismo nivel... Je, esto es como una configuración clásica antes del jefe final en el castillo del Rey Demonio!",
  ui_story_5080_50801201_44_dialog_content = "El líder de Rediesel... pensar que realmente saltó a la lava por nosotros...",
  ui_story_5080_50801201_45_dialog_content = "Vamos a bajar. Necesitamos encontrar Sinsa.",
  ui_story_5080_50801201_46_dialog_content = "Todo es lava aquí... Nuestra única opción es navegar alrededor de estas áreas.",
  ui_story_5080_50801201_47_dialog_content = "La misión es lo primero. Deberíamos evitar zonas de peligro innecesarias.",
  ui_story_5080_50801201_48_dialog_content = "Sinsa nos salvó... así que tengo que encontrarlos. Sígueme, debería poder sentirlos.",
  ui_story_5080_50801201_49_dialog_content = "¡Último Caelestite, tus líneas siempre son tan geniales! ¡Deja de robarme el protagonismo! ¡Yo también voy!",
  ui_story_5080_50801201_50_dialog_content = "Capitán, también quiero ayudar con el rescate.",
  ui_story_5080_50801201_51_dialog_content = "... Tu brazo está herido. ¿Ocurrió cuando caímos?",
  ui_story_5080_50801201_52_dialog_content = "¿Eh? Oh... está sangrando.",
  ui_story_5080_50801201_53_dialog_content = "Toma esto y vendate. Ya no estás en condiciones para el servicio de primera línea. Quédate detrás de mí cuando vayamos.",
  ui_story_5080_50801201_54_dialog_content = "¿Vamos?",
  ui_story_5080_50801201_55_dialog_content = "Ahí abajo. El objetivo podría estar debajo de nosotros.",
  ui_story_5080_50801201_56_dialog_content = "¡Sí, señora!",
  ui_story_5080_50801201_57_dialog_content = "Este lugar está plagado de Eclipsites... ¿Cómo pueden vivir en un volcán activo?",
  ui_story_5080_50801201_58_dialog_content = "Los Eclipsites también son criaturas vivientes. Seguramente deberían evitar áreas tan peligrosas.",
  ui_story_5080_50801201_59_dialog_content = "Esto no se parece en nada a lo que aprendí en la academia.",
  ui_story_5080_50801201_60_dialog_content = "... Estos Eclipsites fueron descubiertos por Illumina hace mucho tiempo.",
  ui_story_5080_50801201_61_dialog_content = "¿Qué? ¿Por qué no había oído hablar de esto?",
  ui_story_5080_50801201_62_dialog_content = "En aquel entonces, el Comité asignó a mi tía y su equipo a una misión igual que la nuestra.",
  ui_story_5080_50801201_63_dialog_content = "Su capitán fue quien fundó oficialmente la Rediesel Wrench.",
  ui_story_5080_50801201_64_dialog_content = "Sabes, tu tía sirvió en el Escuadrón Freebird.",
  ui_story_5080_50801201_65_dialog_content = "Su última misión fue una importante asignada directamente por el Comité, pero no solo fracasó, su capitán también desertó de Illumina después.",
  ui_story_5080_50801201_66_dialog_content = "Muchas personas han dicho que el Escuadrón Freebird abandonó su misión sin permiso para salvarse a sí mismos. ¿Qué opinas sobre esto?",
  ui_story_5080_50801201_67_dialog_content = "¡Me siento avergonzado! Gran Mariscal. Me siento muy... culpable por el fracaso de mi tía.",
  ui_story_5080_50801201_68_dialog_content = "Pero ella siempre fue leal. ¡Solo fue arrastrada por ese capitán!",
  ui_story_5080_50801201_69_dialog_content = "Por favor, dame una oportunidad para restaurar el honor de mi familia.",
  ui_story_5080_50801201_70_dialog_content = "Pero si esa desgracia no hubiera ocurrido, tu tía podría haber muerto como una heroína.",
  ui_story_5080_50801201_71_dialog_content = "¿Habría sido eso más fácil para ti aceptar?",
  ui_story_5080_50801201_72_dialog_content = "Eh... yo... yo...",
  ui_story_5080_50801201_73_dialog_content = "Jajaja... Solo estaba preguntando.",
  ui_story_5080_50801201_74_dialog_content = "Ahora, déjame decirte por qué te llamé aquí, tengo una misión para ti.",
  ui_story_5080_50801201_75_dialog_content = "La última misión de tu tía es la que deseo asignarte.",
  ui_story_5080_50801201_76_dialog_content = "¿Gran Mariscal?",
  ui_story_5080_50801201_77_dialog_content = "En aquel entonces, el Comité ordenó al Escuadrón Freebird que trajera de vuelta a ese Eclipsite observado con vida.",
  ui_story_5080_50801201_78_dialog_content = "Querían un espécimen vivo para fines de experimentación.",
  ui_story_5080_50801201_79_dialog_content = "Todavía tengo dudas sobre si tal investigación tiene implicaciones positivas para Illumina, así que no te obligaré a hacer nada.",
  ui_story_5080_50801201_80_dialog_content = "(Yo...)",
  ui_story_5080_50801201_81_dialog_content = "Por supuesto, capturar a ese Eclipsite vivo podría compensar tu arrepentimiento por tu tía.",
  ui_story_5080_50801201_82_dialog_content = "Sin embargo, Rachel, puedes decidir qué hacer por ti mismo.",
  ui_story_5080_50801201_83_dialog_content = "He elegido un compañero especial para tu misión. Has oído el nombre \"Vice\" antes, ¿supongo?",
  ui_story_5080_50801201_84_dialog_content = "¿La joven capitana de la que se rumorea que trabaja de cerca con un Caelestite? Pero ella ha estado trabajando con Caelestite durante tanto tiempo...",
  ui_story_5080_50801201_85_dialog_content = "Correcto. Si ella fuera contigo, ¿cómo podría su pareja no seguir?",
  ui_story_5080_50801201_86_dialog_content = "Son individuos increíbles. Estoy seguro de que encontrarás algunas respuestas en esta misión.",
  ui_story_5080_50801201_87_dialog_content = "Esta es también una solicitud cuidadosamente emitida por Hiiro. Tienes un superior excelente, Rachel.",
  ui_story_5080_50801201_88_dialog_content = "¡Muchas gracias, y gracias, Comandante Hiiro. Gracias por seguir creyendo en mí y darme esta oportunidad!",
  ui_story_5080_50801201_89_dialog_content = "¡Me prepararé para partir de inmediato!",
  ui_story_5080_50801201_90_dialog_content = "Espera un momento, Rachel.",
  ui_story_5080_50801201_91_dialog_content = "¡Tenga la seguridad, completaré la misión!",
  ui_story_5080_50801201_92_dialog_content = "Solo quiero preguntarte una cosa—",
  ui_story_5080_50801201_93_dialog_content = "¿Todavía puedes encontrar a Illumina en tu corazón?",
  ui_story_5080_50801201_94_dialog_content = "Yo... Yo sé lo que te preocupa, Gran Mariscal.",
  ui_story_5080_50801201_95_dialog_content = "De hecho, cometí errores al mandar, errores que llevaron a la caída de mi equipo. Y parece que no puedo llevarme bien con mis compañeros de equipo en mi estado actual...",
  ui_story_5080_50801201_96_dialog_content = "Pero ten la seguridad, no volveré a cometer los mismos errores.",
  ui_story_5080_50801201_97_dialog_content = "No me refería a eso, pero no importa. Adelante.",
  ui_story_5080_50801201_98_dialog_content = "Tenerlos cerca puede alterar tu forma de pensar.",
  ui_story_5080_50801201_99_dialog_content = "Son socios legendarios, personas increíbles. Sus palabras tienen un gran poder.",
  ui_story_5080_50801201_100_dialog_content = "Prestaré más atención y continuaré manteniendo mi... No me involucraré con ningún compañero de equipo, y no meteré a nadie más en problemas...",
  ui_story_5080_50801201_101_dialog_content = "Tía, tengo buenas noticias.",
  ui_story_5080_50801201_102_dialog_content = "Tengo una nueva misión.",
  ui_story_5080_50801201_103_dialog_content = "¿En serio? Eso es maravilloso. Pero, ¿estás bien? No te esfuerces demasiado.",
  ui_story_5080_50801201_104_dialog_content = "Estoy bien, tía. Y esta vez, podría tener la oportunidad de investigar lo que sucedió en aquel entonces.",
  ui_story_5080_50801201_105_dialog_content = "Limpiaré tu nombre.",
  ui_story_5080_50801201_106_dialog_content = "No pienses así, Rachel.",
  ui_story_5080_50801201_107_dialog_content = "Nunca he lamentado lo que pasó en aquel entonces. Estoy profundamente agradecido al capitán por permitirme sobrevivir.",
  ui_story_5080_50801201_108_dialog_content = "Si no fuera por ella, me estaría perdiendo el placer de tu compañía.",
  ui_story_5080_50801201_109_dialog_content = "¿Por qué sigues defendiéndola...? Ella desertó de Illumina.",
  ui_story_5080_50801201_110_dialog_content = "¡El capitán no es un desertor, ni es una traidora!",
  ui_story_5080_50801201_111_dialog_content = "Debe haber alguna razón para sus acciones que desconocemos, ¡pero creo en ella absolutamente con todo mi corazón!",
  ui_story_5080_50801201_112_dialog_content = "¡Ella los convirtió a todos en traidores y ni una sola vez pensó en regresar en todos estos años! ¿Por qué todavía crees en ella?!",
  ui_story_5080_50801201_113_dialog_content = "¡Ella es la que nos llevó a todos de vuelta de ese infierno fundido con una sola mano!",
  ui_story_5080_50801201_114_dialog_content = "¡Ella es una verdadera heroína!",
  ui_story_5080_50801201_115_dialog_content = "Solo quiero limpiar tu nombre...",
  ui_story_5080_50801201_116_dialog_content = "Nuestra familia no hizo nada malo...",
  ui_story_5080_50801201_117_dialog_content = "¿A dónde vas, Rachel?",
  ui_story_5080_50801201_118_dialog_content = "¡Regresa, Rachel! ¡Te prohíbo ir allí!",
  ui_story_5080_50801201_119_dialog_content = "Rachel...",
  ui_story_5080_50801201_120_dialog_content = "Aunque la misión de Freebird fracasó, aún recopilaron una gran cantidad de inteligencia.",
  ui_story_5080_50801201_121_dialog_content = "La información que dejaron mencionaba cómo el Eclipsite que observaron en aquel entonces era una especie mutada que podía absorber energía geotérmica para sobrevivir.",
  ui_story_5080_50801201_122_dialog_content = "Y este volcán, siempre activo pero nunca llegando al punto crítico de erupción, está lleno de tales Eclipsites.",
  ui_story_5080_50801201_123_dialog_content = "Es probable que sea porque estos Eclipsites están absorbiendo la energía del volcán.",
  ui_story_5080_50801201_124_dialog_content = "La inestabilidad del volcán del Desierto de Rediesel se debe a la energía geotérmica inestable.",
  ui_story_5080_50801201_125_dialog_content = "La actividad de estos Eclipsites causa un desequilibrio en la energía geotérmica, sin embargo, su alimentación en el volcán suprime sus erupciones.",
  ui_story_5080_50801201_126_dialog_content = "Desde esta perspectiva, es probable que esos Eclipsites hayan estado prosperando bajo tierra todo este tiempo.",
  ui_story_5080_50801201_127_dialog_content = "Aunque solo se observó uno en aquel entonces, ahora se han convertido en toda una colonia.",
  ui_story_5080_50801201_128_dialog_content = "E incluso han transmitido este aterrador rasgo genéticamente.",
  ui_story_5080_50801201_129_dialog_content = "Espera, ¿eso significa que deberíamos estar agradecidos con estas criaturas?",
  ui_story_5080_50801201_130_dialog_content = "¿Es gracias a ellos que el volcán no ha hecho erupción? Bueno, eso es simplemente molesto.",
  ui_story_5080_50801201_131_dialog_content = "Pero si no fuera por estos Eclipsites, la energía geotérmica no sería tan inestable, y el ambiente no sería tan duro.",
  ui_story_5080_50801201_132_dialog_content = "¡No tendríamos que lidiar con todos esos molestos terremotos mientras conducimos!",
  ui_story_5080_50801201_133_dialog_content = "Incluso más que eso, ¿tiene la desolación del desierto algo que ver con estas criaturas?",
  ui_story_5080_50801201_134_dialog_content = "De todos modos, el hecho de que estos Eclipsites puedan <color=#FFB400>absorber</color> el poder del volcán ya es un paso demasiado lejos para mí.",
  ui_story_5080_50801201_135_dialog_content = "Si <color=#FFB400>ese Eclipsite</color> de aquel entonces ha logrado sobrevivir todo este tiempo, ¿qué tan poderoso es esa cosa?",
  ui_story_5080_50801201_136_dialog_content = "No podemos permitir que exista más tiempo...",
  ui_story_5080_50801201_137_dialog_content = "Absolutamente no podemos permitir que esto continúe...",
  ui_story_5080_50801201_138_dialog_content = "¡Así que sigamos avanzando, más profundo en el volcán! ¡Hacia Sinsa!",
  ui_story_5080_50801202_1_dialog_content = "Vaya... Hablar de un apretón estrecho.",
  ui_story_5080_50801202_2_dialog_content = "Y hay lava por todas partes... ¡Ten cuidado!",
  ui_story_5080_50801202_3_dialog_content = "Cría Dos, Niña Piruleta, ¡mantente a mi seis!",
  ui_story_5080_50801202_4_dialog_content = "Cazador Águila Uno, Dos, Tres—¡abre fuego!",
  ui_story_5080_50801202_5_dialog_content = "¡Capitán, no te esfuerces demasiado! ¡Estos Eclipsites tienen defensas realmente fuertes!",
  ui_story_5080_50801202_6_dialog_content = "¡Basta de hablar! ¡Golpe enfocado!",
  ui_story_5080_50801202_7_dialog_content = "¡No temas! ¡Mi dulce bomba va a resolver esto pronto!",
  ui_story_5080_50801202_8_dialog_content = "Rugido-!",
  ui_story_5080_50801202_9_dialog_content = "¡Capitán!",
  ui_story_5080_50801202_10_dialog_content = "Es solo un rasguño, quédate quieto.",
  ui_story_5080_50801202_11_dialog_content = "¡Aquí viene la segunda ronda!",
  ui_story_5080_50801202_12_dialog_content = "Cazador Águila Uno, ¡retrocede y defiende!",
  ui_story_5080_50801202_13_dialog_content = "¡No! Demasiado tarde...",
  ui_story_5080_50801202_14_dialog_content = "¡Golpe de Héroe!",
  ui_story_5080_50801202_15_dialog_content = "Rugido-!",
  ui_story_5080_50801202_16_dialog_content = "¿Zeta?!",
  ui_story_5080_50801202_17_dialog_content = "¡¡¡Niña Piruleta!!!",
  ui_story_5080_50801202_18_dialog_content = "Fleur, ¡Lo tengo atado con mi Potencia de Fuerza! ¡Ataca ahora!",
  ui_story_5080_50801202_19_dialog_content = "¡Nos vemos en el infierno!",
  ui_story_5080_50801202_20_dialog_content = "¿Cayó en la lava?",
  ui_story_5080_50801202_21_dialog_content = "¡¡¡Groooar!!!",
  ui_story_5080_50801202_22_dialog_content = "Fue tragado por la lava... ¿No se supone que estos Eclipsites pueden resistir la lava?",
  ui_story_5080_50801202_23_dialog_content = "Chica Piruleta, ¿estás bien?!",
  ui_story_5080_50801202_24_dialog_content = "Jeje, ¿qué te parece, Eagleshot? La llave Rediesel no está nada mal.",
  ui_story_5080_50801202_25_dialog_content = "¿Por qué harías eso... por mí...?",
  ui_story_5080_50801202_26_dialog_content = "Porque eres la hermana perdida del héroe que se desvió...",
  ui_story_5080_50801202_27_dialog_content = "¿Niña Piruleta? ¡Niña Piruleta!",
  ui_story_5080_50801202_28_dialog_content = "(Maldición, no hay botiquines y Zeta está en mal estado... Espera... ¿Eh?)",
  ui_story_5080_50801202_29_dialog_content = "¿Fallé en mi comando de nuevo? ¿Dejé, una vez más, que alguien más...",
  ui_story_5080_50801202_30_dialog_content = "Se suponía que yo debía ser el protector...",
  ui_story_5080_50801202_31_dialog_content = "¿Por qué sigo equivocándome? ¿Estoy demasiado lleno de mí mismo?",
  ui_story_5080_50801202_32_dialog_content = "No seas demasiado duro contigo mismo, ¡Zeta aún tiene una oportunidad de luchar! Rápido, ponla en mi espalda, necesitamos movernos.",
  ui_story_5080_50801202_33_dialog_content = "¡Aguanta, Zeta! Te sacaré de aquí, ¡lo prometo!",
  ui_story_5080_50801202_34_dialog_content = "El demonio mecánico reformado, parece que mi viaje podría estar llegando a su fin. Solo olvídate de mí...",
  ui_story_5080_50801202_35_dialog_content = "¡Deja de jugar!",
  ui_story_5080_50801202_36_dialog_content = "¡Despierta! ¿Recuerdas la nueva válvula que me pediste?",
  ui_story_5080_50801202_37_dialog_content = "Solo dame un poco más de tiempo, ¡y descubriré un motor twin-V8 aún más avanzado! ¿No quieres darle una vuelta?",
  ui_story_5080_50801202_38_dialog_content = "¡¿Eh?!",
  ui_story_5080_50801202_39_dialog_content = "Si te quedas hasta que salgamos de aquí, personalizaré tu coche exclusivamente, ¡no más ayuda para Azure! ¿Trato?",
  ui_story_5080_50801202_40_dialog_content = "Además, ¿no siempre has querido saber qué hay bajo el capó del coche de Azure? ¡Lo averiguaré por ti!",
  ui_story_5080_50801202_41_dialog_content = "Vamos a buscar a Roy y hacer que venga con nosotros... ¡Zeta, despierta!",
  ui_story_5080_50801202_42_dialog_content = "¡Estoy planeando una broma para Azure con ese chico! ¡Solo espera y verás!",
  ui_story_5080_50801202_43_dialog_content = "Correcto, correcto. Chica Lollipop, también puedo echar una mano. ¡Me especialicé en ingeniería mecánica en la academia!",
  ui_story_5080_50801202_44_dialog_content = "Pero ni siquiera me llamas por mi nombre...",
  ui_story_5080_50801202_45_dialog_content = "También puedo modificar tu vehículo. La tecnología de Illumina es de primera, ya sabes.",
  ui_story_5080_50801202_46_dialog_content = "¿Alguna vez soñaste con conducir un carruaje de princesa al estilo Illumina?",
  ui_story_5080_50801202_47_dialog_content = "¿¡Qué?! ¡De ninguna manera! ¡Quiero verlo ahora! ¿Tienes algún plano?",
  ui_story_5080_50801202_48_dialog_content = "Zeta? Tú... ¿estás bien?",
  ui_story_5080_50801202_49_dialog_content = "Uh... Je, parece que el Dulce Cazador en mi espalda recibió el golpe por mí... Supongo que después de todo, soy la heroína elegida.",
  ui_story_5080_50801202_50_dialog_content = "¡La señora Zeta ha vuelto a la acción!",
  ui_story_5080_50801202_51_dialog_content = "Hermana, tu...",
  ui_story_5080_50801202_52_dialog_content = "Esta es la historia del Niño Salvaje, la Guerrera Zeta! No caerá sin luchar... Eh...",
  ui_story_5080_50801202_53_dialog_content = "No estaba tratando de engañaros, solo quería que Fleur me llevara un rato.",
  ui_story_5080_50801202_54_dialog_content = "Me asustaste... ¿Por qué estás bromeando en un momento como este... En serio... Aunque me alegra que estés bien.",
  ui_story_5080_50801202_55_dialog_content = "(Cuando me di cuenta por primera vez, no sabía cómo decírselo... Me alegra que esa broma no durara mucho.)",
  ui_story_5080_50801202_56_dialog_content = "¡Mi espalda me está matando!",
  ui_story_5080_50801202_57_dialog_content = "Eagleshot, te ves abatido. No estás enfadado conmigo, ¿verdad...?",
  ui_story_5080_50801202_58_dialog_content = "¿Eh? Tu cara se ve tan malvada ahora... ¡Pareces que estás a punto de convertirte en un villano! ¿Estás planeando convertir esto en una historia de terror?!",
  ui_story_5080_50801202_59_dialog_content = "No—",
  ui_story_5080_50801202_60_dialog_content = "¡¿Eh?!",
  ui_story_5080_50801202_61_dialog_content = "Zeta... Estoy tan contenta de que estés bien.",
  ui_story_5080_50801202_62_dialog_content = "¡No puedes simplemente acariciar la cabeza de un héroe así como así! Pero como estás actuando de manera tan linda, realmente no puedo rechazarte... ¿Eh?",
  ui_story_5080_50801202_63_dialog_content = "¡T-Tú dijiste mi nombre!",
  ui_story_5080_50801202_64_dialog_content = "No deberías asustar a la gente con bromas así...",
  ui_story_5080_50801202_65_dialog_content = "Capitán...",
  ui_story_5080_50801202_66_dialog_content = "No te preocupes, un héroe nunca juega el mismo truco dos veces, jeje.",
  ui_story_5080_50801202_67_dialog_content = "Bueno, ya que todo está bien, después de todo eso... ¡salgamos de esta trampa de lava! ¡Sigue avanzando!",
  ui_story_5080_50801202_68_dialog_content = "Caelestite Uno, Cría Dos, ¡no te quedes atrás!",
  ui_story_5080_50801202_69_dialog_content = "¿Qué pasa con ella que todavía me llama por mi nombre en clave...",
  ui_story_5080_50801202_70_dialog_content = "No nos preocupemos por las pequeñas cosas por ahora. Es hora de salir.",
  ui_story_5080_50801202_71_dialog_content = "La misión debe continuar. ¡Apúrate!",
  ui_story_5080_50801202_72_dialog_content = "(Ella se pone esa fría máscara de indiferencia tan rápidamente, pero ahora parece tan fuera de lugar, Rachel...)",
  ui_story_5080_50801202_73_dialog_content = "Vamos, Vice. Tengo la sensación de que esto casi termina.",
  ui_story_5080_50801202_74_dialog_content = "¡Muévete rápido! Mantente alejado de las zonas de peligro. Uh...",
  ui_story_5080_50801202_75_dialog_content = "¿Qué pasa?",
  ui_story_5080_50801202_76_dialog_content = "¡Nada, vamos!",
  ui_story_5080_50801202_77_dialog_content = "Águila Cazador Uno, explora adelante. ¡Todos los demás, sigan a Águila Cazador Uno!",
  ui_story_5080_50801202_78_dialog_content = "Sus vidas todavía están en mis manos... No puedo... caer ahora...",
  ui_story_5080_50801301_1_dialog_content = "¡Graaaaah—!",
  ui_story_5080_50801301_2_dialog_content = "Están abarrotando.",
  ui_story_5080_50801301_3_dialog_content = "Lleno de malicia, rebosante de odio.",
  ui_story_5080_50801301_4_dialog_content = "Jeriah, ponte en movimiento, puedo manejar esto.",
  ui_story_5080_50801301_5_dialog_content = "¿De qué estás hablando? Tu vista está deteriorada. No puedo dejarte atrás.",
  ui_story_5080_50801301_6_dialog_content = "Tus habilidades... no son adecuadas para esta batalla.",
  ui_story_5080_50801301_7_dialog_content = "Después de todo, todavía soy un miembro senior.",
  ui_story_5080_50801301_8_dialog_content = "El suelo... se está hundiendo... ¡Voy a caer en la lava!",
  ui_story_5080_50801301_9_dialog_content = "Dawn! Un poco a la izquierda, ¡toma mi mano!",
  ui_story_5080_50801301_10_dialog_content = "Adelante, Jeriah.",
  ui_story_5080_50801301_11_dialog_content = "Tengo tu mano. No la sueltes, Dawn.",
  ui_story_5080_50801301_12_dialog_content = "Los Eclipsites, están llegando.",
  ui_story_5080_50801301_13_dialog_content = "No tengo tiempo para pensar en eso ahora mismo.",
  ui_story_5080_50801301_14_dialog_content = "¿Por qué? Jeriah, ¡necesitas vivir!",
  ui_story_5080_50801301_15_dialog_content = "Si mueres, todos estarán muy tristes.",
  ui_story_5080_50801301_16_dialog_content = "¿Puedes imaginar la cara de Eve empapada en lágrimas?",
  ui_story_5080_50801301_17_dialog_content = "¡Ella te estaría abrazando y llorando!",
  ui_story_5080_50801301_18_dialog_content = "...",
  ui_story_5080_50801301_19_dialog_content = "Esa cuerda de cometa realmente tiene un fuerte agarre en ti.",
  ui_story_5080_50801301_20_dialog_content = "¡Ahora que se ha establecido esta conexión entre nosotros, no permitiré que se corte fácilmente!",
  ui_story_5080_50801301_21_dialog_content = "Jeriah... ¡Cuidado!",
  ui_story_5080_50801301_22_dialog_content = "Attar, hice mi mejor esfuerzo...",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>¡Torrente rápido!</color>",
  ui_story_5080_50801301_24_dialog_content = "¡Justo a tiempo! Zeta, ¡bloquéalos con tus bombas!",
  ui_story_5080_50801301_25_dialog_content = "¡Eh-eh, la bomba de azúcar definitiva viene en tu dirección!",
  ui_story_5080_50801301_26_dialog_content = "Jeriah, ¡estoy aquí para ayudar! Fleur, por favor ayuda a levantar Dawn...",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>¡Flor de hielo!</color>",
  ui_story_5080_50801301_28_dialog_content = "¡El puente está listo, vamos arriba!",
  ui_story_5080_50801301_29_dialog_content = "¿Carleen? ¿Y Eve?",
  ui_story_5080_50801301_30_dialog_content = "Dawn, ¡estoy aquí para ayudarte!",
  ui_story_5080_50801301_31_dialog_content = "Has sido de gran ayuda, Pequeña Princesa de Lumopolis.",
  ui_story_5080_50801301_32_dialog_content = "No hay necesidad de agradecerme. También estás luchando duro para proteger a aquellos que te importan, ¿no es así?",
  ui_story_5080_50801301_33_dialog_content = "Ven conmigo, Dawn. ¡No sueltes mi mano!",
  ui_story_5080_50801301_34_dialog_content = "Jeriah... mi mano...",
  ui_story_5080_50801301_35_dialog_content = "Finalmente nos hemos reagrupado. Carleen, ¿están todos bien?",
  ui_story_5080_50801301_36_dialog_content = "Estamos bien, pero la lava aquí es demasiado peligrosa. No podremos luchar aquí por mucho tiempo.",
  ui_story_5080_50801301_37_dialog_content = "Pequeña ave de presa, Princesa, apresúrate y lleva a Zeta lejos de aquí.",
  ui_story_5080_50801301_38_dialog_content = "Celestita, me temo que debo molestarte para que uses tus habilidades psíquicas para guiarnos a Sinsa.",
  ui_story_5080_50801301_39_dialog_content = "¿No te vas?",
  ui_story_5080_50801301_40_dialog_content = "Jah... ¿Cómo podría abandonarlo en un momento como este?",
  ui_story_5080_50801301_41_dialog_content = "¡No me voy! ¡También quiero salvar al Berserker!",
  ui_story_5080_50801301_42_dialog_content = "Tampoco puedo simplemente alejarme.",
  ui_story_5080_50801301_43_dialog_content = "¿Por qué todos ustedes han elegido un momento como este para volverse tan tercos?",
  ui_story_5080_50801301_44_dialog_content = "Entonces, vayamos más adentro.",
  ui_story_5080_50801301_45_dialog_content = "¿Capitán?",
  ui_story_5080_50801301_46_dialog_content = "La misión debe continuar. Necesitamos recopilar más información... y salvar al líder de Rediesel también es una opción.",
  ui_story_5080_50801301_47_dialog_content = "Técnico Rediesel, préstame tus herramientas. Cría Dos, dame tu arma.",
  ui_story_5080_50801301_48_dialog_content = "¿Eh? ¿Yo?",
  ui_story_5080_50801301_49_dialog_content = "Está bien, he mejorado tu arma. Puede que necesites acostumbrarte, pero debería ser más fácil de usar ahora que estás lastimado.",
  ui_story_5080_50801301_50_dialog_content = "Cazador de Águilas Uno, Dos, Tres—¡regresa!",
  ui_story_5080_50801301_51_dialog_content = "Cazador de Águilas Uno y Tres, es el turno de Cazador de Águilas Dos para liderar.",
  ui_story_5080_50801301_52_dialog_content = "Prepárate, continúa la misión.",
  ui_story_5080_50801301_53_dialog_content = "Mi arco se siente más ligero. La cuerda del arco se siente más receptiva...",
  ui_story_5080_50801301_54_dialog_content = "La capitana recordaba exactamente lo que me gusta. Ella es tan considerada, ¿entonces por qué siempre mantiene su distancia con nosotros?",
  ui_story_5080_50801301_55_dialog_content = "Como capitana, tiene que completar la misión y mantener a sus compañeros de equipo con vida.",
  ui_story_5080_50801301_56_dialog_content = "Minimizar el afecto de su equipo hacia ella podría ser su último recurso para evitar que alguien más salga lastimado por su culpa.",
  ui_story_5080_50801301_57_dialog_content = "Entiendo el peso que ella está cargando.",
  ui_story_5080_50801301_58_dialog_content = "¡Sinsa!",
  ui_story_5080_50801301_59_dialog_content = "Idiota... ¿Puedes oírme?",
  ui_story_5080_50801301_60_dialog_content = "Sinsa?! ¡Respóndenos!",
  ui_story_5080_50801301_61_dialog_content = "Roy, ¡mira allí abajo! Ese lugar junto a la lava, ¿es el cabello rojo de Sinsa?",
  ui_story_5080_50801301_62_dialog_content = "¡Ya sea o no, voy a bajar a comprobarlo!",
  ui_story_5080_50801301_63_dialog_content = "¡Oye! ¡Eso es lava! ¿¡Cómo puedes simplemente saltar ahí así?! ¡Oye!",
  ui_story_5080_50801301_64_dialog_content = "Olvídalo, soy yo quien va a superar a Sinsa algún día, ¿cómo podría retroceder en un momento como este?",
  ui_story_5080_50801301_65_dialog_content = "¡Estoy saltando!",
  ui_story_5080_50801301_66_dialog_content = "¡Waaaahhhh—!",
  ui_story_5080_50801301_67_dialog_content = "¡Hay lava por todas partes!",
  ui_story_5080_50801301_68_dialog_content = "¡Muévete del camino!",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5080_50801301_70_dialog_content = "Me estás aplastando, anciano...",
  ui_story_5080_50801301_71_dialog_content = "Mira, es Sinsa! Realmente es Sinsa! ¡Está vivo!",
  ui_story_5080_50801301_72_dialog_content = "Sinsa, tú—",
  ui_story_5080_50801301_73_dialog_content = "Vaya... Mira todos estos Eclipsites muertos... ¿Los mató él solo?",
  ui_story_5080_50801301_74_dialog_content = "Incluso con heridas tan graves después de caer todo el camino hasta aquí, aún logró matar a tantos de ellos.",
  ui_story_5080_50801301_75_dialog_content = "Yo, ustedes vinieron... Acabo de estrangular a este grandote aquí...",
  ui_story_5080_50801301_76_dialog_content = "Sinsa?!",
  ui_story_5080_50801301_77_dialog_content = "Sinsa, sal de eso. Ya está muerto, suelta y ven con nosotros!",
  ui_story_5080_50801301_78_dialog_content = "¿Eh? ¿Sinsa?!",
  ui_story_5080_50801301_79_dialog_content = "No comí muy bien antes... Tengo hambre de nuevo...",
  ui_story_5080_50801301_80_dialog_content = "Realmente quiero volver y comer con todos. La comida siempre sabe mejor de esa manera...",
  ui_story_5080_50801301_81_dialog_content = "Roy, estoy tan somnoliento. Debo haber estado preocupándome demasiado estos últimos días.",
  ui_story_5080_50801301_82_dialog_content = "Volvamos para nuestro festín de victoria. No deberíamos hacer esperar a los demás demasiado tiempo...",
  ui_story_5080_50801301_83_dialog_content = "¿Qué le pasa? Comprueba si está bien, ¡no dejes que se desmaye así!",
  ui_story_5080_50801301_84_dialog_content = "... Está bien. Solo se agotó y se quedó dormido.",
  ui_story_5080_50801301_85_dialog_content = "Estuvo fuera buscando gente anoche y no comió mucho cuando regresó, pobre chico.",
  ui_story_5080_50801301_86_dialog_content = "Hmph, sabía que este chico no era tan frágil.",
  ui_story_5080_50801301_87_dialog_content = "Además, ¡soy el único que tiene permiso para vencerlo!",
  ui_story_5080_50801301_88_dialog_content = "Vamos, ponlo en mi espalda.",
  ui_story_5080_50801301_89_dialog_content = "¡Cuando se despierte y descubra que tuvo que depender de mí, estará tan avergonzado!",
  ui_story_5080_50801301_90_dialog_content = "Entonces te lo dejo a ti, y yo guiaré el camino. Vamos a apurarnos y volver—",
  ui_story_5080_50801301_91_dialog_content = "¿Dónde está su llave inglesa?",
  ui_story_5080_50801301_92_dialog_content = "Tal vez lo perdió cuando cayó... Necesito buscarlo...",
  ui_story_5080_50801301_93_dialog_content = "<color=#828282>¡Ruido!</color>",
  ui_story_5080_50801301_94_dialog_content = "¿Escuchaste eso?",
  ui_story_5080_50801301_95_dialog_content = "¿Es ese el sonido de la lava?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>¡Pum, pum!</color>",
  ui_story_5080_50801301_97_dialog_content = "¡Ahí está de nuevo!",
  ui_story_5080_50801301_98_dialog_content = "... ¡Pasos! Brock, ¡corre!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5080_50801301_100_dialog_content = "¡Corre!",
  ui_story_5080_50801302_1_dialog_content = "¡¡¡Ayuuuuda!!!",
  ui_story_5080_50801302_2_dialog_content = "¿Quién está ahí?",
  ui_story_5080_50801302_3_dialog_content = "¿Quién es ese?",
  ui_story_5080_50801302_4_dialog_content = "¡Guau! ¡Es ese capitán de Illumina! Roy, ¡ven aquí!",
  ui_story_5080_50801302_5_dialog_content = "¿Qué pasó?",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>¡Golpe, golpe, golpe, golpe, golpe, golpe, golpe, golpe, golpe, golpe!</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>Rugido-!</color>",
  ui_story_5080_50801302_8_dialog_content = "¡¿Un Eclipsite?! No... es el <color=#FFB400>objetivo</color>!",
  ui_story_5080_50801302_9_dialog_content = "Gracias por la ayuda, pequeña señorita de Illumina.",
  ui_story_5080_50801302_10_dialog_content = "Voy a poner un poco de fuego de supresión. Ustedes lárguense, los demás están justo detrás!",
  ui_story_5080_50801302_11_dialog_content = "Vamos, Roy, nosotros—",
  ui_story_5080_50801302_12_dialog_content = "¡Cuidado!",
  ui_story_5080_50801302_13_dialog_content = "Rugido-!",
  ui_story_5080_50801302_14_dialog_content = "Astuto chupón... Preferiría recibir una paliza antes que dejarnos pasar.",
  ui_story_5080_50801302_15_dialog_content = "¿Qué es eso? ¿Ese Eclipsite bloqueó el camino?",
  ui_story_5080_50801302_16_dialog_content = "Esa cosa... ¿Es la que mató a Attar...?",
  ui_story_5080_50801302_17_dialog_content = "¡Déjame encargarme de esto!",
  ui_story_5080_50801302_18_dialog_content = "¡<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>El techo es destrozado por un rayo, derribando al Eclipsite, pero esta violenta explosión de poder también hace rugir al volcán, y la tierra comienza a temblar una vez más.</color>",
  ui_story_5080_50801302_20_dialog_content = "Este poder... Malas noticias, gente—el volcán está a punto de explotar!",
  ui_story_5080_50801302_21_dialog_content = "¡Chica Rediesel, sigue atacando!",
  ui_story_5080_50801302_22_dialog_content = "Pero eso podría desencadenar una erupción.",
  ui_story_5080_50801302_23_dialog_content = "Ya se ha despertado. Si sale de aquí, los demás estarán en peligro!",
  ui_story_5080_50801302_24_dialog_content = "Le di justo en el blanco, pero no siento que haya hecho ningún daño... ¿Dónde está su punto débil?",
  ui_story_5080_50801302_25_dialog_content = "Los cazadores de águilas ya lo han explorado. Su caparazón aún no ha alcanzado la verdadera temperatura de la lava.",
  ui_story_5080_50801302_26_dialog_content = "Y, cualquier forma de vida es más vulnerable cuando se alimenta.",
  ui_story_5080_50801302_27_dialog_content = "Si podemos extinguir su caparazón, podría intentar absorber energía. ¡Entonces, expondrá su punto débil!",
  ui_story_5080_50801302_28_dialog_content = "Era claramente más grande en aquel entonces... ¿Cómo logró encogerse y esconderse aquí tan cómodamente durante más de una década...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>¡Reconocimiento de muerte!</color>",
  ui_story_5080_50801302_30_dialog_content = "¡<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>¡Torrente rápido!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>¡Flor de hielo!</color>",
  ui_story_5080_50801302_33_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801302_34_dialog_content = "¡Está herido! ¡Nuestros ataques están funcionando!",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5080_50801302_36_dialog_content = "¡Maldición, la pared está rota! ¡Está entrando lava!",
  ui_story_5080_50801302_37_dialog_content = "¡Cuidado, podría absorber la energía de la lava!",
  ui_story_5080_50801302_38_dialog_content = "Brock, lleva a Sinsa arriba. ¡Eve, cuídate!",
  ui_story_5080_50801302_39_dialog_content = "¡Wahhhhhh!!! ¡Mi robot está en llamas!",
  ui_story_5080_50801302_40_dialog_content = "Zeta, solo los retrasaremos. ¡Ven y retírate conmigo por ahora!",
  ui_story_5080_50801302_41_dialog_content = "¡Pero, la heroína no puede simplemente abandonar el escenario en un momento como este!",
  ui_story_5080_50801302_42_dialog_content = "Escucha, Zeta, no quieres que me preocupe, ¿verdad?",
  ui_story_5080_50801302_43_dialog_content = "¡Graaaaah—!",
  ui_story_5080_50801302_44_dialog_content = "¡Los Eclipsites están abandonando su nido!",
  ui_story_5080_50801302_45_dialog_content = "Como dijo el viejo... Dawn, te cubriré, ¡vamos a reunir a algunos nuevos amigos!",
  ui_story_5080_50801302_46_dialog_content = "¡Ni siquiera pienses en lastimar a mi hermano!",
  ui_story_5080_50801302_47_dialog_content = "Eve, retrocede—Jeriah, tú también...",
  ui_story_5080_50801302_48_dialog_content = "Lo mantendré ocupado. ¡Ustedes chicos salgan de Sinsa aquí!",
  ui_story_5080_50801302_49_dialog_content = "¿Jeriah?",
  ui_story_5080_50801302_50_dialog_content = "Si realmente es el mismo que mató a Attar... ¿cómo podría dejarlo ir?!",
  ui_story_5080_50801302_51_dialog_content = "Aunque la lava está fluyendo, no la está absorbiendo... ¿Por qué?",
  ui_story_5080_50801302_52_dialog_content = "Parece que está... ¿incluso evitando la lava?",
  ui_story_5080_50801302_53_dialog_content = "Espera, Vice, estás en un lugar peligroso, ¡acércate a mí!",
  ui_story_5080_50801302_54_dialog_content = "Carleen, ¡usa tu poder para crear un punto de apoyo en su cabeza!",
  ui_story_5080_50801302_55_dialog_content = "¡Te cubro! ¡Adelante!",
  ui_story_5080_50801302_56_dialog_content = "¡<color=#FFB400>Altavoces!</color>",
  ui_story_5080_50801302_57_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801302_58_dialog_content = "¿Está desacelerando? ¡Déjame ayudar también!",
  ui_story_5080_50801302_59_option_content = "¡Potencia de fuerza!",
  ui_story_5080_50801302_60_dialog_content = "¡Aquellos lo suficientemente depravados para romper las alas de un pájaro pagarán el precio!",
  ui_story_5080_50801302_61_dialog_content = "¡Ahora es el momento! ¿Estás lista, princesita?!",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>¡Flor de hielo!</color>",
  ui_story_5080_50801302_63_dialog_content = "Su caparazón de magma es demasiado caliente, y no estamos infligiendo suficiente daño.",
  ui_story_5080_50801302_64_dialog_content = "Está funcionando, necesitamos seguir atacando...",
  ui_story_5080_50801302_65_dialog_content = "Cazador de Águilas Uno, Cazador de Águilas Dos—perdóname.",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>¡Ataque Autodestrucción!</color>",
  ui_story_5080_50801302_67_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801302_68_dialog_content = "(Oh no, su energía de magma es demasiado fuerte ahora. No importa qué ataque usemos, simplemente rebotará.)",
  ui_story_5080_50801302_69_dialog_content = "Se ha liberado de mi control... ¡cuidado, todos!",
  ui_story_5080_50801302_70_dialog_content = "(Mi cabeza... duele tanto...)",
  ui_story_5080_50801302_71_dialog_content = "¡Oye, la cueva se está derrumbando! ¡Ustedes necesitan apurarse y subir aquí!",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5080_50801302_73_dialog_content = "Se está poniendo cada vez más caliente. A este ritmo...",
  ui_story_5080_50801302_74_dialog_content = "Tengo a la pequeña princesa. ¡Tómala y corre!",
  ui_story_5080_50801302_75_dialog_content = "¡Oh no, Carleen y Jeriah están atrapados!",
  ui_story_5080_50801302_76_dialog_content = "Puede que sea un poco lento, pero abriré un camino. ¡Ustedes tengan cuidado!",
  ui_story_5080_50801302_77_dialog_content = "¿Por qué está pasando esto? Ya lo hemos escaneado... ¿Por qué su energía sigue siendo tan abrumadora?",
  ui_story_5080_50801302_78_dialog_content = "¿Calculé mal?",
  ui_story_5080_50801302_79_dialog_content = "¿Puede continuar reponiendo su fuerza en medio de la batalla?",
  ui_story_5080_50801302_80_dialog_content = "¡La lava viene, Capitán! ¡Corre!",
  ui_story_5080_50801302_81_dialog_content = "¡Sigue sin mí! Debo asumir esta responsabilidad... ¡Cubriré tu retirada!",
  ui_story_5080_50801302_82_dialog_content = "¡Tráelo!",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>¡Torrente rápido!</color>",
  ui_story_5080_50801302_84_dialog_content = "¡Por aquí, así es!",
  ui_story_5080_50801302_85_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801302_86_dialog_content = "¡Cría Dos!",
  ui_story_5080_50801302_87_dialog_content = "¡No te atrevas a tocar Vice otra vez!!!",
  ui_story_5080_50801302_88_option_content = "¡Potencia de fuerza!",
  ui_story_5080_50801302_89_dialog_content = "Cría Dos, ¿estás bien? ¡Despierta!",
  ui_story_5080_50801302_90_dialog_content = "(El fanático de la eficiencia renunció a una oportunidad de atacar por Vice...)",
  ui_story_5080_50801302_91_dialog_content = "¿Por qué me siento tan feliz ahora... aunque me duele mucho la cabeza...?",
  ui_story_5080_50801302_92_dialog_content = "¡No hay tiempo para preocuparse por eso ahora! Eve, ¡ustedes vayan!",
  ui_story_5080_50801302_93_dialog_content = "¡Aquí vienen!",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>¡Puño de Hierro!</color>",
  ui_story_5080_50801302_95_dialog_content = "Pequeña princesa, te dejaré estabilizar el puente!",
  ui_story_5080_50801302_96_dialog_content = "¡<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_97_dialog_content = "¡Funcionó! ¡Lo golpeé desde tan lejos!",
  ui_story_5080_50801302_98_dialog_content = "Hace demasiado calor—No puedo ver nada desde aquí arriba.",
  ui_story_5080_50801302_99_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801302_100_dialog_content = "Está tratando de escapar.",
  ui_story_5080_50801302_101_dialog_content = "¡Ni siquiera pienses en escapar!",
  ui_story_5080_50801302_102_dialog_content = "¡No lo persigas, Jeriah! ¡El suelo bajo nosotros está a punto de ser tragado por la lava!",
  ui_story_5080_50801302_103_dialog_content = "... No tengan miedo, todos... Estoy aquí.",
  ui_story_5080_50801302_104_dialog_content = "Los altavoces han encontrado un punto débil en la pared. Por aquí.",
  ui_story_5080_50801302_105_dialog_content = "Huff... huff... Puente de hielo, despliegue...",
  ui_story_5080_50801302_106_dialog_content = "Esta es toda la fuerza que me queda.",
  ui_story_5080_50801302_107_dialog_content = "Tengo a Hatchling Two en mi espalda... Todos, salgan de aquí.",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>¡Flor de hielo!</color>",
  ui_story_5080_50801401_2_dialog_content = "¿No se rompió?",
  ui_story_5080_50801401_3_dialog_content = "La temperatura de esta pared es demasiado alta. Es difícil atravesarla a la fuerza.",
  ui_story_5080_50801401_4_dialog_content = "Todo es mi culpa... Eagle Hunter Uno y Tres se perdieron en vano.",
  ui_story_5080_50801401_5_dialog_content = "Hace demasiado calor aquí, demasiado calor para usar explosivos sin un cálculo cuidadoso...",
  ui_story_5080_50801401_6_dialog_content = "Solo dame un segundo, y calcularé una explosión precisa.",
  ui_story_5080_50801401_7_dialog_content = "Oye, Roy, ¿ves eso? Están atrapados en ese pasaje.",
  ui_story_5080_50801401_8_dialog_content = "No puedo hacer una buena toma desde aquí...",
  ui_story_5080_50801401_9_dialog_content = "Espera, Eve, ¡tu poder es demasiado volátil para algo así!",
  ui_story_5080_50801401_10_dialog_content = "Solo Sinsa puede lograr esto, ¡tengo que despertarlo!",
  ui_story_5080_50801401_11_dialog_content = "Roy, ¡saca todas las raciones!",
  ui_story_5080_50801401_12_dialog_content = "¿Eh? ¿Qué planeas hacerle a ese tipo...?",
  ui_story_5080_50801401_13_dialog_content = "¡Jajaja! ¿No es obvio? ¡Voy a llenarlo de comida!",
  ui_story_5080_50801401_14_dialog_content = "Munch, munch, munch, munch, munch, munch...",
  ui_story_5080_50801401_15_dialog_content = "¡Para! ¿Estás intentando asfixiarlo?!",
  ui_story_5080_50801401_16_dialog_content = "<size=45>¡Para ya!</size>",
  ui_story_5080_50801401_17_dialog_content = "Vice... Vice... No me asustes así...",
  ui_story_5080_50801401_18_dialog_content = "Cría Dos, Cría Dos, despierta.",
  ui_story_5080_50801401_19_dialog_content = "Cazador Águila Dos, ¡activa el modo de emergencia inmediatamente! ¡Ajusta el desfibrilador al nivel dos! ¡Cargando!",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>¡Borrar!</color>",
  ui_story_5080_50801401_21_dialog_content = "Oh...",
  ui_story_5080_50801401_22_dialog_content = "Gracias a Dios que estás bien...",
  ui_story_5080_50801401_23_dialog_content = "Cría Dos! ¿Puedes oír mi voz? No te preocupes, te sacaré de aquí...",
  ui_story_5080_50801401_24_dialog_content = "Capitán...",
  ui_story_5080_50801401_25_dialog_content = "¿Cría Dos? ¿Cría Dos?",
  ui_story_5080_50801401_26_dialog_content = "...¡Basta, Rachel!",
  ui_story_5080_50801401_27_dialog_content = "¡Si quieres despertar su corazón, al menos llámala por su nombre!",
  ui_story_5080_50801401_28_dialog_content = "¡Di su nombre! Ella no es \"Cría Dos\", ella tiene un nombre–Vice!",
  ui_story_5080_50801401_29_dialog_content = "Caelestita Uno...",
  ui_story_5080_50801401_30_dialog_content = "No importa lo que me pase, pero Vice...",
  ui_story_5080_50801401_31_dialog_content = "Ella te idolatra y respeta. Estaba en las nubes solo por tener la oportunidad de hacer equipo contigo.",
  ui_story_5080_50801401_32_dialog_content = "¡Y sin embargo, nunca la has llamado por su nombre ni una sola vez!",
  ui_story_5080_50801401_33_dialog_content = "...",
  ui_story_5080_50801401_34_dialog_content = "¡Su nombre es Vice! Se quedaría toda la noche trabajando en informes de misión para ti, agotada pero siempre tan emocionada...",
  ui_story_5080_50801401_35_dialog_content = "¡Aunque nunca la llamaste por su nombre, solo hablar con su oficial superior hizo su día!",
  ui_story_5080_50801401_36_dialog_content = "Vice adora a sus superiores, vive por sus elogios. No ha hecho nada malo... ¡Es solo un nombre! ¿De qué tienes tanto miedo...?",
  ui_story_5080_50801401_37_dialog_content = "Por favor, al menos... al menos ahora, llámala por su nombre...",
  ui_story_5080_50801401_38_dialog_content = "Yo... no puedo permitirme formar más apegos innecesarios...",
  ui_story_5080_50801401_39_dialog_content = "Pajarito de presa...",
  ui_story_5080_50801401_40_dialog_content = "Ya nos hemos desviado de la misión... No puedo... no puedo arrastrar a nadie más hacia abajo...",
  ui_story_5080_50801401_41_dialog_content = "...Lo siento, ella lo hizo tan bien... Todo es mi culpa...",
  ui_story_5080_50801401_42_dialog_content = "Tengo miedo de volver a ser una carga... No quiero que nadie más muera por mi culpa...",
  ui_story_5080_50801401_43_dialog_content = "Si formo nuevos lazos... si más de mi gente muere por mis órdenes... Yo... no puedo aceptar eso...",
  ui_story_5080_50801401_44_dialog_content = "¡No! ¡No estoy tratando de culpar a nadie!",
  ui_story_5080_50801401_45_dialog_content = "Siempre has ocultado tu amabilidad mientras te preocupabas genuinamente por todos. ¿Por qué mantenerlo oculto?",
  ui_story_5080_50801401_46_dialog_content = "Es porque cuando te preocupas sinceramente por los demás, están dispuestos a arriesgar sus vidas para protegerte.",
  ui_story_5080_50801401_47_dialog_content = "¿Cómo puedes llamar eso un adjunto innecesario...?",
  ui_story_5080_50801401_48_dialog_content = "Caelestite Uno, no lo entenderías...",
  ui_story_5080_50801401_49_dialog_content = "¿Cómo podría no entenderlo?! ¡He observado impotente mientras otros se sacrificaban por mí! ¿Cómo podría no entenderlo?!",
  ui_story_5080_50801401_50_dialog_content = "Perdí a toda mi raza, y los amigos que finalmente encontré... todo por culpa mía...",
  ui_story_5080_50801401_51_dialog_content = "Entiendo el dolor de perder a personas, la soledad y la culpa...",
  ui_story_5080_50801401_52_dialog_content = "Aprecio sinceramente a todos los que me han ayudado. Su apoyo permite que Vice, yo y todos nuestros amigos sigamos adelante.",
  ui_story_5080_50801401_53_dialog_content = "No creo que estos adjuntos sean innecesarios en absoluto.",
  ui_story_5080_50801401_54_dialog_content = "Solo poder conocer a todos fue una experiencia verdaderamente maravillosa... Si pudiera, me gustaría llamarlos por sus nombres y hablar con ellos de nuevo.",
  ui_story_5080_50801401_55_dialog_content = "PlayerName...",
  ui_story_5080_50801401_56_dialog_content = "Basta... Caelestita Uno...",
  ui_story_5080_50801401_57_dialog_content = "Las personas se sacrifican por los demás porque tienen un profundo amor en sus corazones.",
  ui_story_5080_50801401_58_dialog_content = "¡Los que te cubrieron, y Vice, no lo estaban haciendo por la misión!",
  ui_story_5080_50801401_59_dialog_content = "Solo querían protegerte... y el hecho de que hayas sobrevivido es más que suficiente para hacerlos felices.",
  ui_story_5080_50801401_60_dialog_content = "Al igual que el capitán del Escuadrón Freebird... ella debió haber tenido tanto amor por su equipo, que estaba dispuesta a empañar su reputación solo para traerlos de vuelta.",
  ui_story_5080_50801401_61_dialog_content = "El sacrificio se trata de proteger a las personas detrás de ti...",
  ui_story_5080_50801401_62_dialog_content = "¿Para aquellos que finalmente se entienden, no es esa razón suficiente...?",
  ui_story_5080_50801401_63_dialog_content = "No digas más... Yo...",
  ui_story_5080_50801401_64_dialog_content = "Rachel, lo sabes en tu corazón... A menudo has arriesgado tu vida por nosotros...",
  ui_story_5080_50801401_65_dialog_content = "¿Realmente todo era acerca de la eficiencia?",
  ui_story_5080_50801401_66_dialog_content = "Solo tienes miedo de que alguien salga lastimado... por eso te esfuerzas tanto en proteger a todos...",
  ui_story_5080_50801401_67_dialog_content = "Si ese es el caso... ¿por qué resistirse a formar conexiones...?",
  ui_story_5080_50801401_68_dialog_content = "PlayerName... no llores... ya te has esforzado demasiado...",
  ui_story_5080_50801401_69_dialog_content = "... Necesitamos prepararnos para la explosión, solo espera un poco más.",
  ui_story_5080_50801401_70_dialog_content = "Pequeño pájaro de presa... no, Rachel.",
  ui_story_5080_50801401_71_dialog_content = "Los cielos del desierto a menudo ven aves migratorias... incluso cuando se desvían solas, eventualmente regresan al rebaño.",
  ui_story_5080_50801401_72_dialog_content = "Yo... no entendía eso antes. Pero ahora, me doy cuenta de que elegir ser un ave de presa todavía significa que puedo tener amigos.",
  ui_story_5080_50801401_73_dialog_content = "Yo... Yo... No necesito amigos...",
  ui_story_5080_50801401_74_dialog_content = "Eres tan... terco...",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5080_50801401_76_dialog_content = "¿Qué pasó? ¿Fue eso una explosión?",
  ui_story_5080_50801401_77_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801401_78_dialog_content = "¡Cuidado!",
  ui_story_5080_50801401_79_dialog_content = "Rachel! ¡Ya voy!",
  ui_story_5080_50801401_80_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801401_81_dialog_content = "Maldita sea, está atacando el suelo.",
  ui_story_5080_50801401_82_dialog_content = "¡Altavoces, levanten a la pequeña princesa!",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5080_50801401_84_dialog_content = "¡La pared ha sido volada! ¡Ven conmigo!",
  ui_story_5080_50801401_85_dialog_content = "PlayerName y los demás todavía están ahí abajo!",
  ui_story_5080_50801401_86_dialog_content = "¡Roooooooor!",
  ui_story_5080_50801401_87_dialog_content = "¡No... lastimarás a mis amigos de nuevo!",
  ui_story_5080_50801401_88_dialog_content = "¡PlayerName! ¡Sal de aquí con Carleen y los demás!",
  ui_story_5080_50801401_89_dialog_content = "Rachel... tú... finalmente te abriste...",
  ui_story_5080_50801401_90_dialog_content = "Quizás el cuerpo es más honesto que la mente... PlayerName, en el momento en que te protegí de ese ataque...",
  ui_story_5080_50801401_91_dialog_content = "Esas palabras tercas se me escaparon.",
  ui_story_5080_50801401_92_dialog_content = "Entonces... vamos.",
  ui_story_5080_50801401_93_dialog_content = "¡La lava viene! Caelestite, ¡toma mi mano!",
  ui_story_5080_50801401_94_dialog_content = "Merry, Louis, Louis, Tarsi... Mis compañeros, por favor préstenme su fuerza.",
  ui_story_5080_50801401_95_dialog_content = "¡Deja ir a mis amigos!",
  ui_story_5080_50801401_96_dialog_content = "No... No huiré...",
  ui_story_5080_50801401_97_dialog_content = "¡¿PlayerName?!",
  ui_story_5080_50801401_98_dialog_content = "Dije que aprecio a todos los que me han ayudado... Valoro estas conexiones por encima de todo lo demás...",
  ui_story_5080_50801401_99_dialog_content = "Así que no me rendiré con ninguno de mis amigos, Rachel.",
  ui_story_5080_50801401_100_dialog_content = "...Realmente eres un soldado insubordinado.",
  ui_story_5080_50801401_101_dialog_content = "Pero, PlayerName, estoy contento...",
  ui_story_5080_50801401_102_dialog_content = "Me siento honrado de ser parte del mismo equipo que todos ustedes.",
  ui_story_5080_50801401_103_dialog_content = "Vamos arriba juntos.",
  ui_story_5080_50801401_104_dialog_content = "Carleen, ¡usa tu último bit de fuerza para reforzar nuestro equilibrio!",
  ui_story_5080_50801401_105_dialog_content = "Jeriah, los Portavoces deberían poder soportar la pared que se derrumba, ¿verdad?",
  ui_story_5080_50801401_106_dialog_content = "Fleur, tú estás a cargo de atacarlo de frente.",
  ui_story_5080_50801401_107_dialog_content = "Luchemos codo con codo.",
  ui_story_5080_50801402_1_dialog_content = "La lava se está volviendo más turbulenta, mi <color=#FFB400>Camino de Hielo</color> está... a punto de romperse!",
  ui_story_5080_50801402_2_dialog_content = "¡Solo un poco más, su armadura casi se queda sin energía!",
  ui_story_5080_50801402_3_dialog_content = "¡No! PlayerName, Rachel!",
  ui_story_5080_50801402_4_dialog_content = "(Oh no... la lava ha cortado el camino. Todos estamos separados...)",
  ui_story_5080_50801402_5_dialog_content = "Olviden de nosotros... Estoy agotado... ustedes salgan por el agujero que Fleur ha hecho estallar...",
  ui_story_5080_50801402_6_dialog_content = "¿Qué tipo de tonterías son esas? Aguanta. Lo lograremos.",
  ui_story_5080_50801402_7_dialog_content = "De todos los lugares... Intentar crear otro puente de hielo aquí... será casi imposible.",
  ui_story_5080_50801402_8_dialog_content = "<size=40>Grah!!!</size>",
  ui_story_5080_50801402_9_dialog_content = "No retrocederé, monstruo... incluso si todo lo que me queda es esta pistola...",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>Las balas de Rachel golpean al Eclipsite una por una, pero son bloqueadas por su último bit de calor.</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>Hacer clic-</color>",
  ui_story_5080_50801402_13_dialog_content = "Sin munición...",
  ui_story_5080_50801402_14_dialog_content = "Me quedé sin armas, pero todavía tengo mis puños.",
  ui_story_5080_50801402_15_dialog_content = "PlayerName, ¡escóndete detrás de mí y no te muevas ni un centímetro!",
  ui_story_5080_50801402_16_dialog_content = "Rachel... sigue adelante... Ya no puedo moverme más...",
  ui_story_5080_50801402_17_dialog_content = "¡Yo... nunca te abandonaré!",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5080_50801402_19_dialog_content = "Otra erupción de lava, este volcán parece que está a punto de... espera, ¿qué es eso?!",
  ui_story_5080_50801402_20_dialog_content = "Una llave... ¿La llave de Sinsa? ¿Cómo llegó aquí?",
  ui_story_5080_50801402_21_dialog_content = "Tiempo perfecto.",
  ui_story_5080_50801402_22_dialog_content = "¡Para, Rachel, esa llave es demasiado pesada para ti! ¡No te lastimes!",
  ui_story_5080_50801402_23_dialog_content = "Huff... Huff... Hemos vuelto... ¡Ah!",
  ui_story_5080_50801402_24_dialog_content = "¡Espera, ella realmente está levantando la llave de Sinsa! ¡Eso es simplemente alardear!",
  ui_story_5080_50801402_25_dialog_content = "Yo... o... odio cuando los miembros del equipo presumen...",
  ui_story_5080_50801402_26_dialog_content = "Pero me encanta presumir de mí mismo.",
  ui_story_5080_50801402_27_dialog_content = "Grah!!!",
  ui_story_5080_50801402_28_dialog_content = "¡No te atrevas a lastimar a mis compañeros de equipo!",
  ui_story_5080_50801402_29_dialog_content = "Grooo—!!!",
  ui_story_5080_50801402_30_dialog_content = "¿Cómo es eso posible? Nunca pensé que vería a alguien distinto a Sinsa balanceando esa llave...",
  ui_story_5080_50801402_31_dialog_content = "Awoo... Awoo... Awoo...!!!",
  ui_story_5080_50801402_32_dialog_content = "¿¡Aún no está muerto?!",
  ui_story_5080_50801402_33_dialog_content = "Entonces... hagámoslo una vez más...",
  ui_story_5080_50801402_34_dialog_content = "(Esto es malo... Puedo sentir que el cuerpo de Rachel ha alcanzado su límite... Ella está esforzándose demasiado... solo un poco más, y...)",
  ui_story_5080_50801402_35_dialog_content = "¡Yo... nunca me rendiré... Una vez más!",
  ui_story_5080_50801402_36_dialog_content = "Grah!!!",
  ui_story_5080_50801402_37_dialog_content = "Puente de Hielo... ¡Apúrate!",
  ui_story_5080_50801402_38_dialog_content = "Ella está sin fuerzas... Si esto continúa... ambos lo harán...",
  ui_story_5080_50801402_39_dialog_content = "¿Qué es todo este alboroto?! ¿No puede uno descansar un poco por aquí?!",
  ui_story_5080_50801402_40_dialog_content = "Tú... ¿Sinsa?!",
  ui_story_5080_50801402_41_dialog_content = "Hola, pequeña dama, tienes espíritu.",
  ui_story_5080_50801402_42_dialog_content = "Ser capaz de levantar esta llave inglesa significa que tienes verdadera fuerza.",
  ui_story_5080_50801402_43_dialog_content = "Usar esa fuerza para proteger a los demás demuestra que tienes una voluntad aún más brillante.",
  ui_story_5080_50801402_44_dialog_content = "¡Vamos! Por la <color=#FFB400>justicia</color> en tu corazón, ¡maneja ese <color=#FFB400>poder supremo</color>!",
  ui_story_5080_50801402_45_dialog_content = "<size=45>¡¡¡Hyaaaaaaah—!!!</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5080_50801402_47_dialog_content = "Personas de mundos completamente diferentes, levantando esa llave por los corazones que guardan...",
  ui_story_5080_50801402_48_dialog_content = "Esas dos siluetas...",
  ui_story_5080_50801402_49_dialog_content = "¡Ni siquiera pienses en lastimarlos!",
  ui_story_5080_50801402_50_dialog_content = "¡No me pasarás!",
  ui_story_5080_50801402_51_dialog_content = "Incluso aquel que no podía entenderte al principio, ahora levanta esa llave inglesa—",
  ui_story_5080_50801402_52_dialog_content = "Je... tu voluntad vive hasta el día de hoy... Attar...",
  ui_story_5080_50801402_53_dialog_content = "Continúa viviendo como... <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_5080_50801402_54_dialog_content = "Finalmente terminado y resuelto... Aquí viene la lava, vamos a movernos.",
  ui_story_5080_50801402_55_dialog_content = "El último puente de hielo está arriba. Vamos.",
  ui_story_5080_50801402_56_dialog_content = "¡Eh—! ¡Aquí!",
  ui_story_5080_50801402_57_dialog_content = "¡Por aquí! He lanzado un gancho de agarre allá arriba, ¡podemos salir escalando!",
  ui_story_5080_50801402_58_dialog_content = "PlayerName... vamos... ¡ugh!",
  ui_story_5080_50801402_59_dialog_content = "Oye, ¿estás bien? Te estás esforzando demasiado con todas esas heridas, ya no te queda nada de energía, ¿verdad?",
  ui_story_5080_50801402_60_dialog_content = "Supongo que no tienes opción. ¿Necesitas una mano de este bandido de Rediesel?",
  ui_story_5080_50801402_61_dialog_content = "...",
  ui_story_5080_50801402_62_dialog_content = "¡Oye!",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>Una piedra roza a los dos y se precipita en la lava.</color>",
  ui_story_5080_50801402_64_dialog_content = "... ¿Quién dice que no puedo levantarme? ¿Necesitas una mano de este soldado de Illumina?",
  ui_story_5080_50801402_65_dialog_content = "¡Jajajaja! Eres mucho más linda de lo que admites.",
  ui_story_5080_50801402_66_dialog_content = "Una piedrecita así no es gran cosa... pero no debería hacer que Eve se preocupe por mi herida.",
  ui_story_5080_50801402_67_dialog_content = "Muy agradecido.",
  ui_story_5080_50801402_68_dialog_content = "Lo siento... ¿pero alguien puede ayudarme? He sobrepasado mi habilidad psíquica. Estoy totalmente agotado...",
  ui_story_5080_50801402_69_dialog_content = "...",
  ui_story_5080_50801402_70_dialog_content = "Jej...",
  ui_story_5080_50801402_71_dialog_content = "¡Jajaja!",
  ui_story_5080_50801402_72_dialog_content = "¡Deja de reír allí, vamos a movernos!",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>Retumbar, retumbar!</color>",
  ui_story_5080_50801402_74_dialog_content = "¡Oh ho! ¡Finalmente fuera! ¡Aire fresco y una temperatura perfecta!",
  ui_story_5080_50801402_75_dialog_content = "¡Vaya! ¿Cómo se volvieron tan rápidos?!",
  ui_story_5080_50801402_76_dialog_content = "Parece que dejar que ustedes dos corrieran adelante fue la decisión correcta. Esa habilidad para encontrar el camino es realmente algo...",
  ui_story_5080_50801402_77_dialog_content = "Zeta lideró el camino.",
  ui_story_5080_50801402_78_dialog_content = "¿Y-Qué importa?! ¡Soy una leyenda de las carreras de rally! ¿Y qué si no soy un experto en espeleología!",
  ui_story_5080_50801402_79_dialog_content = "¡Jajajaja!",
  ui_story_5080_50801402_80_dialog_content = "¡Oye, Berserker! ¡No te rías!",
  ui_story_5080_50801402_81_dialog_content = "Bueno, por supuesto, tenemos que reír, pequeño Zeta.",
  ui_story_5080_50801402_82_dialog_content = "¿¡Tú?! ¿Incluso tú deseas intimidar a este gran héroe...?!",
  ui_story_5080_50801402_83_dialog_content = "¡Realmente podemos volver a tiempo para el festín! ¡En serio!",
  ui_story_5080_50801402_84_dialog_content = "¿Por qué estamos perdiendo el tiempo aquí? ¡Podrían empezar sin nosotros!",
  ui_story_5080_50801402_85_dialog_content = "¿Qué? ¿Con la Gran Heroína Zeta aquí? ¡Te traeré de vuelta en un instante!",
  ui_story_5080_50801402_86_dialog_content = "¡Sube al coche!",
  ui_story_5080_50801402_87_dialog_content = "¿Hola... Jonah?",
  ui_story_5080_50801402_88_dialog_content = "¿Azure?",
  ui_story_5080_50801402_89_dialog_content = "Oh Dios mío... Rara vez regreso, y cuando lo hago, el lugar está muerto.",
  ui_story_5080_50801402_90_dialog_content = "¡Espera! ¿Qué es eso allá?",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>¡Bang!!! ¡Bang, bang, bang!</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>Una explosión de una trampa desencadena una reacción en cadena entre todas las minas terrestres. En cuestión de momentos, el campamento entero es irreconocible.</color>",
  ui_story_5080_50801402_93_dialog_content = "Eso es el campo de minas...",
  ui_story_5080_50801402_94_dialog_content = "¿Qué pasa?",
  ui_story_5080_50801402_95_dialog_content = "¿Cómo terminó el campamento en este estado? Eh... ¿seguimos teniendo una fiesta esta noche?",
  ui_story_5080_50801402_96_dialog_content = "¡Ahhhhhhh!",
  ui_story_5080_50801402_97_dialog_content = "¡Idiotas! ¿Qué han hecho?!",
  ui_story_5080_50801402_98_dialog_content = "¡Solo un pequeño error de cálculo, jefe!",
  ui_story_5080_50801402_99_dialog_content = "¡Deja de correr! ¡Quédate quieto! ¡Voy a enseñarte una lección!",
  ui_story_5080_50801402_100_dialog_content = "Está bien, está bien, deja de golpear al niño por ahora. Veamos qué es comestible aquí, ¿verdad?",
  ui_story_5080_50801402_101_dialog_content = "¡Wahaaah! Mi hermoso escenario...!",
  ui_story_5080_50801402_102_dialog_content = "No llores, déjame ver si puedo arreglarlo...",
  ui_story_5080_50801402_103_dialog_content = "Je, nunca pensé que te vería tener un día tan duro, ¡bruja!",
  ui_story_5080_50801402_104_dialog_content = "¿Seguramente no tienes idea de qué tipo de hazañas es capaz de lograr Zeta el Grande?!",
  ui_story_5080_50801402_105_dialog_content = "... Meh, olvídalo... Estoy contenta de verte, hermana mayor.",
  ui_story_5080_50801402_106_dialog_content = "¿Qué es todo esto?",
  ui_story_5080_50801402_107_dialog_content = "En serio—",
  ui_story_5080_50801402_108_dialog_content = "¿Oye? ¡Rachel! ¡Rachel!",
  ui_story_5080_50801402_109_dialog_content = "¿Qué pasa? Déjame echar un vistazo...",
  ui_story_5080_50801402_110_dialog_content = "Oh, ella está bien. Estaba tan relajada que se desmayó.",
  ui_story_5080_50801402_111_dialog_content = "¿Su dron está roto de nuevo? Hmph, Odi, observa y aprende mientras demuestro mis exquisitas habilidades de reparación!",
  ui_story_5080_50801402_112_dialog_content = "¿Cómo podría ser tu turno conmigo aquí?",
  ui_story_5080_50801402_113_dialog_content = "¿Es esta... la ciudad de Gannon?",
  ui_story_5080_50801402_114_dialog_content = "¿Cuándo regresé a casa...?",
  ui_story_5080_50801402_115_dialog_content = "¡Capitán! ¡Capitán!",
  ui_story_5080_50801402_116_dialog_content = "Yo...",
  ui_story_5080_50801402_117_dialog_content = "Cisne Blanco... no, Merry, tú...",
  ui_story_5080_50801402_118_dialog_content = "Ah, ha pasado tanto tiempo... ¿Hmm?!",
  ui_story_5080_50801402_119_dialog_content = "Capitán, tú... ¿Por qué estás llorando?",
  ui_story_5080_50801402_120_dialog_content = "Lo siento, lo siento mucho... He querido decirte esto durante tanto tiempo.",
  ui_story_5080_50801402_121_dialog_content = "No soy un buen capitán... Te dejé... te dejé...",
  ui_story_5080_50801402_122_dialog_content = "Jajaja, nunca pensé que el capitán derramaría lágrimas tan libremente.",
  ui_story_5080_50801402_123_dialog_content = "Es la primera vez que lo veo... y con suerte, será la última.",
  ui_story_5080_50801402_124_dialog_content = "Eres el que sobrevivió, Capitán. ¿No es eso simplemente genial?",
  ui_story_5080_50801402_125_dialog_content = "Estamos tan felices de poder salvarte.",
  ui_story_5080_50801402_126_dialog_content = "¡Y ahora eres aún más perfecto que antes! Quiero decir, salvaste a todos, ¿verdad?",
  ui_story_5080_50801402_127_dialog_content = "Ahora eres el capitán definitivo.",
  ui_story_5080_50801402_128_dialog_content = "Ustedes...",
  ui_story_5080_50801402_129_dialog_content = "Estoy tan contento de haberte conocido, capitán.",
  ui_story_5080_50801402_130_dialog_content = "De todos los escuadrones, tuve la suerte de ser elegido por ti... Soy muy afortunado.",
  ui_story_5080_50801402_131_dialog_content = "Así que tú también tienes que ser feliz, Capitán.",
  ui_story_5080_50801402_132_dialog_content = "¿A dónde van, chicos? ¡Regresen aquí! Escúchenme...",
  ui_story_5080_50801402_133_dialog_content = "Es hora de volver, Capitán. Nosotros no somos a quienes necesitas proteger ahora.",
  ui_story_5080_50801402_134_dialog_content = "Por favor vive bien... Ríe más, eso es todo lo que queremos!",
  ui_story_5080_50801402_135_dialog_content = "¡Esperen, todos, no se vayan!",
  ui_story_5080_50801402_136_dialog_content = "Capitán...",
  ui_story_5080_50801402_137_dialog_content = "¡E-Espérame!",
  ui_story_5080_50801402_138_dialog_content = "¡Capitán...!",
  ui_story_5080_50801402_139_dialog_content = "Hermana, tu...",
  ui_story_5080_50801402_140_dialog_content = "Vice?",
  ui_story_5080_50801402_141_dialog_content = "¿Capitán...?",
  ui_story_5080_50801402_142_dialog_content = "Estás bien... Qué alivio.",
  ui_story_5080_50801402_143_dialog_content = "¡Espera! ¿Acabas de... decir mi nombre?",
  ui_story_5080_50801402_144_dialog_content = "¡Waaaah! ¡Capitán! ¡¡¡Capitán!!!",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>Vice, abrumado de alegría, abraza fuertemente a Rachel, sin importarle lo rígido que sea el recipiente de su abrazo.</color>",
  ui_story_5080_50801402_146_dialog_content = "(Pero... ese corazón sincero definitivamente no quedará sin ser correspondido.)",
  ui_story_5080_50801402_147_dialog_content = "Está bien ahora... Todo está bien...",
  ui_story_5080_50801402_148_dialog_content = "Gracias, Vice.",
  ui_story_5080_50801402_149_dialog_content = "Gracias a todos.",
  ui_story_5080_50801500_1_dialog_content = "Matamos a ese Eclipsite para salvarnos, pero ahora, el terremoto ha disminuido y el volcán no ha erupcionado.",
  ui_story_5080_50801500_2_dialog_content = "¿Quieres decir... todavía hay algo que está reprimiendo la energía del volcán?",
  ui_story_5080_50801500_3_dialog_content = "Es solo una suposición, pero antes de que nos fuéramos, los portavoces encontraron-",
  ui_story_5080_50801500_4_dialog_content = "El lugar donde aplastaste a ese Eclipsite había sido atravesado. Había otra capa debajo, con su propio camino.",
  ui_story_5080_50801500_5_dialog_content = "¿Un camino dentro del núcleo del volcán?",
  ui_story_5080_50801500_6_dialog_content = "Pero ahora todo está cubierto de lava, por lo que es posible que no podamos investigarlo.",
  ui_story_5080_50801500_7_dialog_content = "... Roy piensa que ese Eclipsite no era el de aquel entonces.",
  ui_story_5080_50801500_8_dialog_content = "En efecto. Si no fuera por el terreno, las cosas no habrían sido tan difíciles. Si este fuera el de aquel entonces, Attar no habría muerto...",
  ui_story_5080_50801500_9_dialog_content = "Parece que todo está estrechamente relacionado con las verdaderas profundidades del volcán.",
  ui_story_5080_50801500_10_dialog_content = "Nuestro verdadero <color=#FFB400>enemigo</color>... podría estar escondido allí.",
  ui_story_5080_50801500_11_dialog_content = "Investiguemos juntos una vez que la lava se enfríe y las heridas de todos sanen.",
  ui_story_5080_50801500_12_dialog_content = "Debe ser bastante molesto para el Rediesel Wrench, ¿dormir sobre un volcán tan activo?",
  ui_story_5080_50801500_13_dialog_content = "¿Quién puede decir...? Todos somos solo un gran grupo de tontos viviendo el momento. ¿Realmente hay alguien entre nosotros que se preocupe tanto por algo así?",
  ui_story_5080_50801500_14_dialog_content = "El escenario está arreglado... He estado trabajando en él sin parar, ¡y chico, estoy cansado!!!",
  ui_story_5080_50801500_15_dialog_content = "¡No te preocupes, déjame a mí la siguiente parte! ¡Que mi pasión arda a través del cielo nocturno—!",
  ui_story_5080_50801500_16_dialog_content = "¿Eh? Zeta?! Tú, tú...",
  ui_story_5080_50801500_17_dialog_content = "¿Por qué te maquillaste como un fantasma?",
  ui_story_5080_50801500_18_dialog_content = "¿Eh? Esta fue toda la idea de la chica bruja, ¡haciendo que Zeta se vista como un adulto!",
  ui_story_5080_50801500_19_dialog_content = "¿Te refieres a... esa chica bruja!!!",
  ui_story_5080_50801500_20_dialog_content = "¡No corras! ¿No dijiste que bailarías conmigo? ¡Estamos a punto de subir al escenario para el enfrentamiento final!",
  ui_story_5080_50801500_21_dialog_content = "Brock, tú también lo viste, ¿verdad? Todos tienen hambre.",
  ui_story_5080_50801500_22_dialog_content = "Sin duda, el lavador de verduras más rápido será aclamado como el verdadero héroe que resolvió esta crisis, un héroe digno del respeto de todos.",
  ui_story_5080_50801500_23_dialog_content = "¡Oh, oh, oh! No necesitas decírmelo dos veces, he estado entrenando para esto, ¡solo mírame!",
  ui_story_5080_50801500_24_dialog_content = "¿En serio? Vaya, ojalá todos fueran tan crédulos... ¡Oye! ¡Tengo aquí un lavador de verduras! ¿Interesado?",
  ui_story_5080_50801500_25_dialog_content = "El campamento es un desastre... También quiero ayudar.",
  ui_story_5080_50801500_26_dialog_content = "Yo también.",
  ui_story_5080_50801500_27_dialog_content = "¡Fuera del camino! ¡Nadie me roba el trueno!",
  ui_story_5080_50801500_28_dialog_content = "Solo déjalo hacer, si quieres una vida pacífica.",
  ui_story_5080_50801500_29_dialog_content = "¿Azure? ¿Azure? ¿Adónde fuiste?",
  ui_story_5080_50801500_30_dialog_content = "Prácticamente he vaciado el almacén. ¡Necesitas tomar una verdadera copa conmigo esta noche!",
  ui_story_5080_50801500_31_dialog_content = "En serio, qué multitud tan ruidosa...",
  ui_story_5080_50801500_32_dialog_content = "No soy un viejo de verdad, solo un pequeño mocoso que se metió en todo esto a mitad de camino.",
  ui_story_5080_50801500_33_dialog_content = "Astra es tan vasto... pero este es el único lugar que nos acogió a Eve y a mí cuando no teníamos a dónde ir.",
  ui_story_5080_50801500_34_dialog_content = "Finalmente hemos llegado tan lejos. Finalmente podemos confiar en nosotros mismos para seguir adelante y vivir juntos como una familia.",
  ui_story_5080_50801500_35_dialog_content = "Ya no te preocupes por complacer a los demás o temer al rechazo.",
  ui_story_5080_50801500_36_dialog_content = "¿Sabes qué? Esta es la primera vez que te escucho decir esto.",
  ui_story_5080_50801500_37_dialog_content = "Todos somos tan raros, como granos de arena desesperadamente frotándose juntos. Si es cierto que la sangre es más espesa que el agua, entonces debemos haber mezclado nuestra sangre hace mucho tiempo.",
  ui_story_5080_50801500_38_dialog_content = "Entonces, estoy feliz de pasar cada día con estos chicos.",
  ui_story_5080_50801500_39_dialog_content = "Sin importar los desafíos que se nos presenten, siempre nos unimos para forjar una vida feliz. ¡Eso es lo que significa la libertad para nosotros!",
  ui_story_5080_50801500_40_dialog_content = "¡Y para preservar nuestro estilo de vida, levantaré mi llave inglesa una y otra vez para ahuyentar a cualquiera que se meta con nosotros!",
  ui_story_5080_50801500_41_dialog_content = "Eres un líder extraordinario, Sinsa.",
  ui_story_5080_50801500_42_dialog_content = "Ahora, tengo un favor que pedirte. Mi misión está completa, pero aún no estoy satisfecho.",
  ui_story_5080_50801500_43_dialog_content = "Si el peligro aún acecha cerca, quiero enfrentarlo junto a todos los demás aquí.",
  ui_story_5080_50801500_44_dialog_content = "Además, el viejo líder salvó a mi tía, y quiero saldar la deuda.",
  ui_story_5080_50801500_45_dialog_content = "Entonces, permíteme preguntarte ahora, ¿entiendes el significado de \"sacrificio\"?",
  ui_story_5080_50801500_46_dialog_content = "Jej...",
  ui_story_5080_50801500_47_dialog_content = "¿Eh? ¿Por qué nos miras?",
  ui_story_5080_50801500_48_dialog_content = "He tomado una decisión. Para evitar que mis compañeros de equipo se preocupen constantemente, no hablaré a la ligera del sacrificio.",
  ui_story_5080_50801500_49_dialog_content = "Pero... si alguna vez estamos en peligro, daré mi vida por aquellos a mi lado.",
  ui_story_5080_50801500_50_dialog_content = "Pase lo que pase, deseo proteger a aquellos que caminan conmigo.",
  ui_story_5080_50801500_51_dialog_content = "Sí... los soldados de Illumina no deberían actuar solo por el bien de la misión o por honor.",
  ui_story_5080_50801500_52_dialog_content = "Pero porque queremos proteger todo en nuestras vidas.",
  ui_story_5080_50801500_53_dialog_content = "Rachel...",
  ui_story_5080_50801500_54_dialog_content = "Incluso si debo convertirme en un fuego ardiente para iluminar el camino y asegurar el futuro de quienes me rodean, este es el verdadero propósito de Illumina.",
  ui_story_5080_50801500_55_dialog_content = "Mis antepasados fueron ayudados por otros y sacrificaron por otros a su vez, ¡y yo no seré una excepción!",
  ui_story_5080_50801500_56_dialog_content = "A partir de ahora, lucharé para proteger mis deseos más profundos y me convertiré en una línea de defensa inquebrantable para Illumina.",
  ui_story_5080_50801500_57_dialog_content = "Tus palabras suenan un poco igual que siempre, pero tus ojos cuentan una historia diferente.",
  ui_story_5080_50801500_58_dialog_content = "¿Estás seguro de que estás listo para empezar a tomar tus propias decisiones ahora?",
  ui_story_5080_50801500_59_dialog_content = "El credo de Illumina es \"uno para todos, todos para uno.\"",
  ui_story_5080_50801500_60_dialog_content = "Aun así, podemos seguir tomando nuestras propias decisiones a través de nuestra propia voluntad. Podemos decidir por qué luchamos y por qué estamos dispuestos a sacrificar nuestras vidas.",
  ui_story_5080_50801500_61_dialog_content = "Este tipo de resolución nunca podría ser falso... ¡Ah!",
  ui_story_5080_50801500_62_dialog_content = "¿Todavía puedes encontrar a Illumina en tu corazón?",
  ui_story_5080_50801500_63_dialog_content = "¿Qué pasa, Capitán Rachel? ¿Te están molestando las heridas?",
  ui_story_5080_50801500_64_dialog_content = "...No, no te preocupes, Vice.",
  ui_story_5080_50801500_65_dialog_content = "Solo... finalmente sé cómo responder a esa pregunta.",
  ui_story_5080_50801500_66_dialog_content = "¿Qué pregunta...?",
  ui_story_5080_50801500_67_dialog_content = "Je... parece que finalmente sabes lo que estás buscando.",
  ui_story_5080_50801500_68_dialog_content = "Está bien, acepto que me eches una mano con la investigación.",
  ui_story_5080_50801500_69_dialog_content = "Pero con esas heridas, no pienses en apresurarte todavía.",
  ui_story_5080_50801500_70_dialog_content = "Quédate aquí esta noche, disfruta de una buena comida y descansa.",
  ui_story_5080_50801500_71_dialog_content = "Hmm... Pero...",
  ui_story_5080_50801500_72_dialog_content = "¿Pero?",
  ui_story_5080_50801500_73_dialog_content = "Aunque seamos aliados, si la llave Rediesel causa problemas de nuevo, te trataré de la misma manera que trataría a cualquiera!",
  ui_story_5080_50801500_74_dialog_content = "Si manchas la voluntad que representa esa llave, te haré entregarla.",
  ui_story_5080_50801500_75_dialog_content = "Oh...",
  ui_story_5080_50801500_76_dialog_content = "Si lo quieres, ven y tómalo tú mismo.",
  ui_story_5080_50801500_77_dialog_content = "Honestamente, tu loco cerebro de Illumina tiene algunos tornillos sueltos.",
  ui_story_5080_50801500_78_dialog_content = "¡Jajajaja!",
  ui_story_5080_50801500_79_dialog_content = "¿Qué te ríes?",
  ui_story_5080_50801500_80_dialog_content = "¡Esta es la primera vez que te veo tan indefenso, Sinsa! ¡Jajajaja!",
  ui_story_5080_50801500_81_dialog_content = "Dame un respiro...",
  ui_story_5080_50801500_82_dialog_content = "¡Jefe! ¡Jefe! ¡Mira esto!",
  ui_story_5080_50801500_83_dialog_content = "Lo encontramos mientras limpiábamos los escombros, parece que podría ser el diario del antiguo jefe.",
  ui_story_5080_50801500_84_dialog_content = "Lo descubrimos en una pequeña caja que fue volada por la explosión... Parece que ha estado escondido todo este tiempo.",
  ui_story_5080_50801500_85_dialog_content = "... Entendido. Por ahora, simplemente guardémoslo.",
  ui_story_5080_50801500_86_dialog_content = "Después de todo, es hora de fiesta. Nos preocuparemos por todo lo demás mañana, ¡divirtámonos!",
  ui_story_5080_50801500_87_dialog_content = "¡Entendido! ¡Oye! Deja de empujar... ¡Ay!",
  ui_story_5080_50801500_88_dialog_content = "¡Ahora es mi turno de reír! ¡Jajajaja!",
  ui_story_5080_50801500_89_dialog_content = "Mi pequeño pájaro de presa, por favor espera un momento.",
  ui_story_5080_50801500_90_dialog_content = "¿Qué pasa?",
  ui_story_5080_50801500_91_dialog_content = "Quiero contarte la parte final de la historia que Attar compartió conmigo.",
  ui_story_5080_50801500_92_dialog_content = "Después de que salvó a su compañero de equipo y abandonó su misión, dejó Illumina. Sin rumbo, vagó por el mundo durante un tiempo.",
  ui_story_5080_50801500_93_dialog_content = "Llegó por coincidencia a este mismo desierto donde había fracasado en su misión, sabiendo que su enemigo aún persistía.",
  ui_story_5080_50801500_94_dialog_content = "Ella dijo que nació en este desierto. Sabe que este desierto es un lugar sin ley y que es libre. Solo que nunca ha vivido aquí antes.",
  ui_story_5080_50801500_95_dialog_content = "Así que quería verlo por sí misma. Al menos, quería encontrar un lugar de descanso para sus miembros del equipo muertos.",
  ui_story_5080_50801500_96_dialog_content = "...",
  ui_story_5080_50801500_97_dialog_content = "Se encontró con bandidos mientras vagaba por el desierto y, por alguna jugada del destino, los llevó a luchar contra los Eclipsites, recogiendo esa llave legendaria para combatirlos.",
  ui_story_5080_50801500_98_dialog_content = "Para esas personas, ella levantó su llave, unió a los bandidos del desierto y puso fin al caos en esta tierra estéril.",
  ui_story_5080_50801500_99_dialog_content = "Ella guió a esas personas para que se establecieran en el oasis y aprendió la historia legendaria detrás de la llave inglesa.",
  ui_story_5080_50801500_100_dialog_content = "Y así, ella manchó la llave con rediesel extraído del oasis, estableciendo oficialmente la Rediesel Wrench.",
  ui_story_5080_50801500_101_dialog_content = "Vivió bien, no solo encontrando la verdadera libertad sino finalmente sacrificando todo para protegerla.",
  ui_story_5080_50801500_102_dialog_content = "¿Por qué... me estás contando todo esto?",
  ui_story_5080_50801500_103_dialog_content = "Por favor, dile a tu tía cuando regreses.",
  ui_story_5080_50801500_104_dialog_content = "Su capitán no abandonó sin más a su nación. A lo largo de su viaje en la vida, ella empuñó su arma por la libertad de los demás, hasta el final.",
  ui_story_5080_50801500_105_dialog_content = "Espero que esta información brinde algo de consuelo a tu tía.",
  ui_story_5080_50801500_106_dialog_content = "Gracias... Realmente no sé cómo más expresar mi gratitud.",
  ui_story_5080_50801500_107_dialog_content = "¡Canta, pequeño pájaro de presa! ¿No puedes escuchar la canción?",
  ui_story_5080_50801500_108_dialog_content = "La canción...?",
  ui_story_5080_50801500_109_dialog_content = "¡Arde brillantemente, hermoso paraíso, nuestro hogar!",
  ui_story_5080_50801500_110_dialog_content = "¡Canta, canta, incluso si el mundo de mañana está lleno de heridas!",
  ui_story_5080_50801500_111_dialog_content = "Eleva tu voz en la canción... Eso es... el poder de la vida.",
  ui_story_5080_50801500_112_dialog_content = "¡Capitán Rachel! ¡Por aquí! ¡La fiesta está a punto de comenzar!",
  ui_story_5080_50801500_113_dialog_content = "¡Ah... Llego en un momento!",
  ui_story_5080_50801500_114_dialog_content = "... También es hora de que me vaya...",
  ui_story_5080_50801500_115_dialog_content = "¿A dónde te diriges? Oye, toma esto.",
  ui_story_5080_50801500_116_dialog_content = "Esto es...",
  ui_story_5080_50801500_117_dialog_content = "Cactus con hígado de escorpión de cristal a la parrilla. ¡Es delicioso! Supongo que nunca lo has probado antes.",
  ui_story_5080_50801500_118_dialog_content = "Has explorado tanto, en tantos lugares que ni siquiera sabía que existían.",
  ui_story_5080_50801500_119_dialog_content = "Hablar sobre decir lo obvio...",
  ui_story_5080_50801500_120_dialog_content = "Oye... Jeriah, también deberías volver a casa de vez en cuando. Vamos a tener una gran comida juntos.",
  ui_story_5080_50801500_121_dialog_content = "... Parece que no hay salida de este festín,",
  ui_story_5080_50801500_122_dialog_content = "¿Entonces qué más hay que decir? ¡Vamos!",
  ui_story_5080_50801500_123_dialog_content = "Rachel, ¡por aquí! Te guardé un asiento.",
  ui_story_5080_50801500_124_dialog_content = "Una vez que la carne esté a la brasa, toma tu parte mientras puedas, ¡estos chicos generalmente no tienen tiempo para cortesías!",
  ui_story_5080_50801500_125_dialog_content = "Gracias... Gracias a todos.",
  ui_story_5080_50801500_126_dialog_content = "¿Para qué? Esto no es nada, de verdad.",
  ui_story_5080_50801500_127_dialog_content = "No... Estoy agradecido por la forma en que siempre has hecho un esfuerzo por aceptarme, a pesar de mis defectos.",
  ui_story_5080_50801500_128_dialog_content = "Estrechemos las manos, es una tradición de Illumina.",
  ui_story_5080_50801500_129_dialog_content = "... ¡Bueno!",
  ui_story_5080_50801500_130_dialog_content = "Curioso, ¿no es así? A pesar de que eres un Celestita, ¿por qué siento tal sensación de familiaridad cuando estoy contigo?",
  ui_story_5080_50801500_131_dialog_content = "Y nunca me juzgas. Pareces estar a gusto con los Illuminans.",
  ui_story_5080_50801500_132_dialog_content = "(¿Por dónde debería empezar? Ha sido un largo viaje... con Gram, Revy, Reinhardt, Barton, y los demás...)",
  ui_story_5080_50801500_133_dialog_content = "PlayerName, hagamos esto juntos, como acabo de decir!",
  ui_story_5080_50801500_134_dialog_content = "¡Exacto!",
  ui_story_5080_50801500_135_dialog_content = "¡Esplendor Illumina!! ¡Un saludo para ti!",
  ui_story_5080_50801500_136_dialog_content = "¡Gracias por salvarme a mí y a Vice!",
  ui_story_5080_50801500_137_dialog_content = "Un saludo militar tan fino... Je, parece que ambos han pasado por mucho. Esto debe ser por qué son compañeros tan legendarios.",
  ui_story_5080_50801500_138_dialog_content = "Ahora entiendo por qué el Gran Mariscal te llamó increíble.",
  ui_story_5080_50801500_139_dialog_content = "Pero por ahora, también son mis compañeros...",
  ui_story_5080_50801500_140_dialog_content = "¡Disfrutemos juntos de esta cena, todos!",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>La canción áspera de la llave Rediesel, aunque sin refinar, exuda una sensación de libertad desenfrenada. Enciende el desierto, resonando a través de la noche en una melodía frenética.</color>",
  ui_story_5080_50801500_142_dialog_content = "Merry... Louis... Tarsi... Lina... ¿Puedes oírlo?",
  ui_story_5080_50801500_143_dialog_content = "Dicen que este desierto abraza todas las almas... Entonces...",
  ui_story_5080_50801500_144_dialog_content = "Seguramente te abraza a ti también.",
  ui_story_5080_50801500_145_dialog_content = "Vuela... en esta noche de libertad.",
  ui_story_5080_50801500_146_dialog_content = "Hasta que sus almas encuentren descanso."
}
return config
